template <class T = long long>
struct edge {
	T cap;
	int from;
	int to;
	int rev;  // fromの方の配列で逆辺が何番目に存在するか
	bool operator<(const edge a) const {
		if(cap != a.cap) return cap < a.cap;
		if(from != a.from) return from < a.from;
		return to < a.to;
	}
	bool operator>(const edge a) const {
		if(cap != a.cap) return cap > a.cap;
		if(from != a.from) return from > a.from;
		return to > a.to;
	}
};

template <class T = long long>
class Dinic {
   private:
	int ver;  //頂点数
	vector<vector<edge<T>>> edges;
	vector<int> level;
	vector<int> chk;

   public:
	Dinic(int vertex) : ver(vertex), edges(vertex), level(vertex, -1), chk(vertex, 0) {}

	//辺と逆辺の追加 (0-indexed)
	void update(int from, int to, T cap = 1) {
		edge<T> e;
		e.cap = cap;
		e.from = from;
		e.to = to;
		e.rev = (int)edges[to].size();
		edges[from].push_back(e);

		e.cap = (T)0;
		swap(e.to, e.from);
		e.rev = (int)edges[from].size() - 1;
		edges[to].push_back(e);
	}

	//入力受取 (1-indexed)
	void input(int edge_num, int index = 1) {
		for(int i = 0; i < edge_num; i++) {
			int a;
			int b;
			T cap;
			cin >> a >> b >> cap;
			a -= index;
			b -= index;
			update(a, b, cap);
		}
	}

   private:
	//有効な辺のみを用いた幅優先探索で距離を求める
	void bfs(int s) {
		level.assign(ver, -1);
		level[s] = 0;
		queue<int> q;
		q.push(s);
		while(!q.empty()) {
			int now = q.front();
			q.pop();
			for(auto &e : edges[now]) {
				if(level[e.to] >= 0) continue;
				if(e.cap <= 0) continue;
				level[e.to] = level[now] + 1;
				q.push(e.to);
			}
		}
		return;
	}

	//流せる辺を探す
	T dfs(int now, int t, T f) {
		if(now == t) return f;
		for(int i = chk[now]; i < (int)edges[now].size(); i++) {
			auto &e = edges[now][i];
			if(level[now] + 1 != level[e.to] || e.cap <= 0) {
				chk[now]++;
				continue;
			}
			T k = dfs(e.to, t, min(f, e.cap));
			if(k > 0) {
				e.cap -= k;
				edges[e.to][e.rev].cap += k;
				return k;
			}
			chk[now]++;
		}
		return (T)0;
	}

   public:
	T maxflow(int s, int t) {
		T flow = 0;
		const T INF = 3e16;	 // T == int だとバグる
		while(1) {
			bfs(s);
			if(level[t] < 0) return flow;
			for(int i = 0; i < ver; i++) chk[i] = 0;
			T fl = 1;
			while(fl > 0) {
				fl = dfs(s, t, INF);
				flow += fl;
			}
		}
	}
};
struct UF {						 // Union_Find木
	vector<int> par;			 // par[i]:iの親の番号　(例) par[3] = 2 : 3の親が2
	vector<int> sz;				 // size[i]:iを根とする木のサイズ
	UF(int N) : par(N), sz(N) {	 //最初は全てが根であるとして初期化
		for(int i = 0; i < N; i++) {
			par[i] = i;
			sz[i] = 1;
		}
	}

	int root(int x) {  // データxが属する木の根を再帰で得る：root(x) = {xの木の根}
		if(par[x] == x) return x;
		return par[x] = root(par[x]);
	}

	// 2つのデータx, yが属する木が同じならtrueを返す
	bool same(int x, int y) { return root(x) == root(y); }

	void unite(int x, int y) {	// xとyの木を併合
		int rx = root(x);		// xの根をrx
		int ry = root(y);		// yの根をry
		if(rx == ry) return;	// xとyの根が同じ(=同じ木にある)時はそのまま
		par[rx] = ry;			// xとyの根が同じでない(=同じ木にない)時：xの根rxをyの根ryにつける
		sz[ry] += sz[rx];
		sz[rx] = 0;	 //サイズの処理 根じゃなくなったらサイズは0になる
	}

	// xが属する木のサイズ sz[x]は根でないとき0になるので注意
	int size(int x) { return sz[root(x)]; }
};

