const int N = 3e5+15;

int ret[N];
void solve() {
    int n,inc,dec;
    cin>>n>>inc>>dec;
    if(inc+dec-1>n || (ll)inc*dec<n) {
        printf("-1\n");
        return;
    }
    bool isSwaped = false;
    if(inc<=dec) {
        isSwaped = true;
        swap(inc,dec);
    }

    bool canMake = false;
    if(dec==1) {
        if(inc!=n) {
            printf("-1\n");
            return;
        }
        canMake = true;
        for(int i=0;i<n;++i) {
            ret[i] = i+1;
        }
    } else {
        int pos = 0;
        for(int i=0;i<dec;++i) {
            ret[i] = dec - i;
        }
        int rem = inc-1 + dec;
        rem = n - rem;
        pos = dec;
        if(rem==0) {
            canMake = true;
            for(int i = dec;i<n;++i) {
                ret[i] = i+1;
            }
        } else {
            rem += inc-1;
            int mySeg = -1;
            for(int seg=1;seg<=dec;++seg) {
                if(rem/seg <=inc-1) {
                    mySeg = seg;
                    break;
                }
            }
            int r = n;
            if(mySeg!=-1) {
                for(int seg=0;seg<mySeg;++seg) {
                    int l = max(dec+1,r - (inc-1) + 1);
                    for(int j = l;j<=r;++j) {
                        ret[pos++] = j;
                    }
                    r = l-1;
                }
                canMake = true;
            }
        }
        pos = dec;
    }
    if(!canMake) {
        printf("-1\n");
        return;
    }
    if(isSwaped) {
        for(int i=0;i<n;++i) {
            ret[i] = n - ret[i] + 1;
        }
    }
    for(int i=0;i<n;++i) {
        printf("%d ",ret[i]);
    }
    cout<<endl;
}

