int main() {

    ios::sync_with_stdio(false); // stdioを使うときはコメントアウトすること
    cin.tie(nullptr);            // インタラクティブ問題ではコメントアウトすること

    ll n, a, b; cin >> n >> a >> b;

    if (a+b > n+1 || n > a*b) {
        say(-1);
        return 0;
    }

    vector<ll> gl(a, 1);
    gl[0] = b;
    ll rem = n - accumulate(ALL_OF(gl), 0LL);
    if (rem < 0) {
        say(-1);
        return 0;
    }
    RANGE(i, 1, a-1) {
        ll t = min(rem, b-1);
        gl[i] += t;
        rem -= t;
    }

    vector<ll> hd(a, 0);
    hd[0] = gl[0];
    REP(i, a-1) hd[i+1] = hd[i] + gl[i+1];

    vector<ll> ans; ans.reserve(n);
    ll j = a-1;
    REP(i, n) {

        ++j %= a;
        while (gl[j] <= 0) ++j %= a;

        gl[j]--;
        ans.push_back(hd[j]--);
    }
    say(ans);

}

