vec slide(vec v, int n){
    int N = v.size();
    vec w(N);
    REP(i, n) w[N - 1 - i] = v[i];
    REP(i, N - n) w[i] = v[n + i];
    return w;
}

signed main(){

    int N, A, B; cin >> N >> A >> B;

    if(A + B > N + 1 || A * B < N){
        cout << -1 << endl;
        return 0;
    }

    int n = (N - 1) / B + 1;
    mat ans(n);
    int v = 1;
    REP(i, n){
        int m = min(N, B);
        ans[i] = vec(m);
        IREP(j, m){
            ans[i][j] = v;
            v++;
        }
        N -= m;
    }

    int a = n;
    IREP(i, n){
        int k = min((int)ans[i].size() - 1, A - a);
        //cout << i << " " << k << endl;
        ans[i] = slide(ans[i], k);
        a += k; 
    }

    REP(i, n) REP(j, ans[i].size()) cout << ans[i][j] << " ";


    return 0;
}

