            return 0;
        }
    }
    int flag = N - A + 1;
    for(int i = 0; i < block; i++){
        for(int j = 0; j < A; j++) cout << flag + j << " ";
        flag = max<int>(0, flag - A);
    }
    int nokori = max<int>(0, N - block * A);
    int sagaru = B - block;
    for(int i = 1; i <= nokori - sagaru; i++) cout << i << " ";
    for(int i = nokori; nokori - sagaru + 1 <= i; i--) cout << i << " ";
    cout << endl;
    return 0;
}

