    //index->[l,r]
    int l = N - (index * B) + 1;
    int r = N - (index * B) + B;
    if (l >= 1) {
        rep(i, B / 2) {
            swap(arr[l + i], arr[r - i]);
        }
        return;
    } else {
        rep(i, r / 2) {
            swap(arr[1 + i], arr[r - i]);
        }
        return;
    }
}

void flip(int index, int num) {
    int l = N - (index * B) + 1;
    if (l < 1)l = 1;
    int r = l + num - 1;
    rep(i, num/2) {
        swap(arr[l + i], arr[r + i]);
    }
}


