class Solve {
private:
	int n, a, b;

	void solve() {
		cin >> n >> a >> b;

		int mina = n / b;
		if (n % b != 0) mina++;
		int maxa = n - b + 1;

		if (a < mina || a > maxa) {
			cout << "-1" << endl;
			return;
		}

		int remain = a - mina;
		int cur = n % b;
		if (cur == 0) cur = b;

		int l = 1, r = cur;
		vector<int> rst;
		rst.reserve(n);

		while (l <= n) {
			int t = r - l;
			if (t > remain) t = remain;

			for (int i = r - t; i >= l; i--) {
				rst.push_back(i);
			}
			for (int i = r - t + 1; i <= r; i++) {
				rst.push_back(i);
			}

			remain -= t;
			l = r + 1;
			r = l + b - 1;
		}

		cout << rst[0];
		for (int i = 1; i < n; i++) {
			cout << ' ' << rst[i];
		}
		cout << endl;
	}

public:
	Solve() { solve(); }
};

int main(int argc, char* argv[]) {
	unique_ptr<Solve> solve = make_unique<Solve>();
	return 0;
}

