    ios::sync_with_stdio(false);
    cin.tie(0);
    cout << fixed << setprecision(20);

    cin >> N >> A >> B;
    rep(i, N)ans[i] = i + 1;
    if (A + B - 1 <= N && N <= (ll)A*B) {
        reverse(ans, ans + B);
        for (int i = 1, k = B; i < A; ++i) {
            // n個の元をm個に分割
            // 分割の大きさCは
            // 1<=C<=min(n-(m-1), B)
            int n = N - k, m = A - i;
            int C = min(n - m + 1, B);
            reverse(ans + k, ans + k + C);
            k += C;
        }
        rep(i, N)cout << ans[i] << (i != N - 1 ? ' ' : '\n');
    } else {
        cout << -1 << endl;
    }
}

