#include <bits/stdc++.h>
using namespace std;

const int N = 1111111;

#define int long long

int P[N];
bool vis[N];

int n , A , B;

int dn(int x , int y) {
	return (x / y);
}

bool pd(int x) {
	return (n - x) + dn(x , B) >= A;
}

void solve(int l , int r) {
	int it = r;
	for(int i = l;i <= r;++ i) P[i] = it --;
} 

main(void) {
	cin >>n >> A >> B;
	if(A * B < n || A + B > n + 1) {
		puts("-1"); return 0;
	}
	int l = 0 , r = n , res = -1;
	while(l <= r) {
		int mid = (l + r) >> 1;
		if(pd(mid)) {
			l = mid + 1; res = mid;
		}
		else r = mid - 1;
	}
	int it = 0;
	int now = 1;
	while(now <= res) {
		solve(now , min(now + B - 1 , n));
		now += B;
	}
	for(int i = 1;i <= res;++ i) vis[P[i]] = 1;
	now = 1;
	for(int i = res + 1;i <= n;++ i) {
		while(vis[now]) ++ now;
		P[i] = now;
		++ now;
	}
	for(int i = 1;i <= n;++ i) cout << P[i] <<" ";
}

