int longest_increasing_subsequence(vector<int> nums){
    int dp[N];
    fill(dp, dp + N, 1e9);
    for(int i = 0; i < N; i++){
        *lower_bound(dp, dp + N, nums[i]) = nums[i];
    }
    return int(lower_bound(dp, dp + N, 1e9) - dp);
}

vector<int> make_array(){
    vector<int> ans;
    for(int i = N - A + 1; i <= N; i++){
        ans.push_back(i);
    }
    for(int i = 2; i <= N - A - B + 1; i += 2){
        ans.push_back(i);
        ans.push_back(i - 1);
    }
    if((N - A - B + 1) % 2){
        ans.push_back(N - A - B + 1);
    }
    for(int i = N - A; i >= N - A - B + 2; i--){
        ans.push_back(i);
    }
    if(longest_increasing_subsequence(ans) != A){
        return {-1};
    }
    reverse(ans.begin(), ans.end());
    if(longest_increasing_subsequence(ans) != B){
        return {-1};
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

void output(vector<int> nums){
    string ans_string;
    for(int i = 0; i < N; i++){
        ans_string += to_string(nums[i]) + " ";
    }
    ans_string.pop_back();
    cout << ans_string << endl;
}

int main(){
    cin >> N >> A >> B;
    if(A + B - 1 > N){
        cout << -1 << endl;
        return 0;
    }
    vector<int> ans = make_array();
    if(ans[0] != -1){
        output(ans);
        return 0;
    }
    int tmp = A;
    A = B;
    B = tmp;
    ans = make_array();
    if(ans[0] != -1){
        reverse(ans.begin(), ans.end());
        output(ans);
    }else{
        cout << -1 << endl;
    }
}

