		cout << -1 << endl;
		return 0;
	}
	vl ans(n);

	REP(i, n)ans[i] = i + 1;
	if (a != 1) {
		ll sum = a * b;
		vl tmp(a + 1, b - (sum - n) / (a - 1));
		REP(i, (sum-n)%(a-1))tmp[a - i]--;
		tmp[0] = 0;
		tmp[1] = b;
		REP(i, a)tmp[i + 1] += tmp[i];

		REP(i, a) {
			reverse(ans.begin() + tmp[i], ans.begin() + tmp[i + 1]);
		}
	}
	REP(i, n) {
		if (i)cout << " ";
		cout << ans[i];
	}
	cout << endl;
	int A = (lis(ans)).size();
	REP(i, n)ans[i] *= -1;
	int B = (lis(ans)).size();
	assert(A == a && B == b);
}

