        REP(i,t){
            REP(j,b){
                res[i*b+j] = (i+1)*b-j;
            }
        }
        ll k = n-t*b;
        REP(i,k-(a-t)){
            res[b*t+i] = n-i;
        }

        REP(i,a-t){
            res[b*t+k-(a-t)+i] = t*b+1+i;
        }
    }
    put(res);
    return 0;
}

