int lis[10], lds[10];

vector<int> go(int N, int A, int B)
{
	vector<int> V;
	REP(i, N)
		V.push_back(i + 1);

	vector<int> res(1, -1);

	do {
		memset(lis, 0, sizeof(lis));
		memset(lds, 0, sizeof(lds));

		lds[0] = lis[0] = 1;

		FOR(i, 1, N)
		{
			lis[i] = lds[i] = 1;
			REP(j, i)
				if (V[i] > V[j])
					lis[i] = max(lis[i], 1 + lis[j]);
				else
					lds[i] = max(lds[i], 1 + lds[j]);
		}

		int vA = 0, vB = 0;
		REP(i, N)
		{
			vA = max(vA, lis[i]);
			vB = max(vB, lds[i]);
		}

		if (vA == A && vB == B)
			return V;
	} while (next_permutation(V.begin(), V.end()));

	return res;
}

vector<int> go1(int N, int A, int B)
{
	vector<int> res;

	if (B > N)
	{
		res.push_back(-1);
		return res;
	}

	int left = N - B; A--;

	if (left < A || (!A && left))
	{
		res.push_back(-1);
		return res;
	}

	if (!A)
	{
		REP(i, B)
			res.push_back(B - i);
		return res;
	}

	int beg = B + 1, ile = left / A, rm = left%A;

	if (ile + (rm ? 1 : 0) > B)
	{
		res.push_back(-1);
		return res;
	}

	REP(i, B)
		res.push_back(B - i);

	REP(i, A)
	{
		vector<int> tmp;
		REP(j, ile)
		{
			tmp.push_back(beg);
			beg++;
		}

		if (rm)
		{
			tmp.push_back(beg);
			beg++;
			rm--;
		}

		reverse(tmp.begin(), tmp.end());
		for (int l : tmp)
			res.push_back(l);
	}

	return res;
}

