#pragma region datastructure binary indexed tree
/**
* @brief Binary Indexed Tree
* @docs docs/datastructure/binaryindexedtree.md
*/

template<typename T> struct BinaryIndexedTree {
    vector< T > data;
    BinaryIndexedTree(int sz) { data.assign(++sz, 0); }
    T sum(int k) {
        if (k < 0) return T(0);
        T ret = 0;
        for (++k; k > 0; k -= k & -k) ret += data[k];
        return (ret);
    }
    T sum(int l, int r) {
        assert(l <= r);
        return sum(r - 1) - sum(l - 1);
    }
    void add(int k, T x) {
        for (++k; k < data.size(); k += k & -k) data[k] += x;
    }
    int lower_bound(T w) {
        if (w <= 0) return 0;
        int n = data.size(), x = 0, r = 1;
        while (r < n) r <<= 1;
        for (int k = r; k > 0; k >>= 1) {
            if (x + k <= n and data[x + k] < w) {
                w -= data[x + k];
                x += k;
            }
        }
        return x + 1;
    }
};
#pragma endregion

const int INF = 1 << 30;
int N, A, B;

void end() {
    cout << -1 << endl;
    exit(0);
}

int LIS(const vector<int> &v) {
    int n = v.size();
    vector<int> dp(300010, INF);
    for (int i = 0; i < n; ++i) {
        *lower_bound(dp.begin(), dp.end(), v[i]) = v[i];
    }
    return lower_bound(dp.begin(), dp.end(), INF) - dp.begin();
}

int LDS(const vector<int> &v) {
    vector<int> tmp(v);
    for (auto& e: tmp) e *= -1;
    return LIS(tmp);
}

signed main() {
    cin >> N >> A >> B;
    if (A + B > N + 1) end();
    if (A == 1 and B < N) end();
    if (B == 1 and A < N) end();
    vector<vector<int>> v;
    for (int i = N - A + 1; i >= 1; i -= A) {
        vector<int> tmp;
        for (int j = i; j < i + A; ++j) {
            tmp.emplace_back(j);
        }
        v.emplace_back(tmp);
    }
    if (N % A) {
        vector<int> tmp;
        for (int i = 1; i <= N % A; ++i) {
            tmp.emplace_back(i);
        }
        v.emplace_back(tmp);
    }
    vector<int> up;
    for (int i = (int)v.size() - 1; i > 0; --i) {
        for (int j = 0; j + 1 < v[i].size(); ++j) {
            up.emplace_back(v[i][j]);
        }
    }
    int idx = B - 1 - (int)v.size();
    int num = idx == -1 ? -1 : up[idx];
    vector<int> res;
    for (auto& a: v) {
        for (auto& e: a) {
            if (e > num) {
                res.emplace_back(e);
            }
        }
    }
    for (int i = num; i >= 1; --i) {
        res.emplace_back(i);
    }
    if (LIS(res) != A) end();
    if (LDS(res) != B) end();
    for (int i = 0; i < N; ++i) {
        cout << res[i] << " \n"[i == N - 1];
    }
}

