int main() {
	int n, a, b;
	std::cin >> n >> a >> b;
	int A{ a }, B{ b };
	std::vector<int> series(n);
	int idx{ 0 }, upper{ n }, lower{ 1 };
	bool do_once{ false };
	while (a >= 0 && b >= 0 && idx < n) {
		fill_with(series, idx, idx + a - 1, upper - a + 1, 1);
		idx += a;
		upper -= a - 1;
		--a; --b;
		fill_with(series, idx, idx + b - 1, lower + b - 1, -1);
		idx += b;
		lower -= b - 1;
		if (idx <= n) do_once = true;
	}
	if (a < 0 || b < 0 || !do_once) std::cout << -1 << std::endl;
	else {
		for (auto i = 0; i < n - 1; ++i) {
			std::cout << series[i] << ' ';
		}
		std::cout << series[n - 1] << std::endl;
	}
}

