void solve(){

  inl(N , A , B);
  if(A + B > N + 1) die(-1);
  if(A * B < N) die(-1);

  vi num;
  num.push_back(B);
  // 残り N - B個をA - 1列で分ける
  if(A != 1){
    int n1 = (N - B) / (A - 1);
    int n2 = n1 + 1;
    int a2 = N - B - n1 * (A - 1);
    int a1 = A - 1 - a2;
    rep(i,a1) num.pb(n1);
    rep(i,a2) num.pb(n2);
    trc(n1,n2,a2,a1);
  }
  vi ans;
  int idx = 0;
  each(x , num){
    for(int i = idx + x ; i > idx ; i--){
      ans.pb(i);
    }
    idx += x;
  }

  out(ans);


}


