    }
    for (int i = 1; i <= a; i++) ans[i] = n - a + i;
    cnt = a;
    t = n-a;
    -- b;
    while (b) {
        pres = min(n-cnt-b+1, a);
        for (int i = 1; i <= pres; i++) ans[cnt+i] = t-pres+i;
        cnt += pres; --b; t -= pres;
    }
    if (cnt != n) {
        puts("-1");
        return 0;
    }
    for (int i = 1; i <= n; i++) printf("%d ", ans[i]);
    printf("\n");
    return 0;
}

