#include <bits/stdc++.h>
using namespace std;
#define REP(i,a,n) for(int i=(a); i<(int)(n); i++)
#define rep(i,n) REP(i,0,n)
#define FOR(it,c) for(__typeof((c).begin()) it=(c).begin(); it!=(c).end(); ++it)
#define ALLOF(c) (c).begin(), (c).end()
typedef long long ll;
typedef unsigned long long ull;

vector<int> solve(int N, int A, int B){
  vector<int> ret;

  if(B > N) return vector<int>();
  REP(i,1,B+1){
    ret.push_back(i);
  }
  reverse(ALLOF(ret));

  if(N-B < A-1) return vector<int>();
  if(A-1 == 0){
    if(ret.size() != N) return vector<int>();
    return ret;
  }
  vector<int> tmp(A-1);
  int x = (N-B)/(A-1);
  int y = (N-B)%(A-1);
  rep(i,tmp.size()) tmp[i] = x;
  rep(i,y) tmp[i]++;

  rep(i,tmp.size()){
    if(tmp[i]>B) return vector<int>();
  }
  int pos = N;
  vector<vector<int>> ret2;
  rep(i,tmp.size()){
    vector<int> tmp2;
    rep(j,tmp[i]) tmp2.push_back(pos--);
    ret2.push_back(tmp2);
  }
  reverse(ALLOF(ret2));
  rep(i,ret2.size()){
    rep(j,ret2[i].size()){
      ret.push_back(ret2[i][j]);
    }
  }

  if(ret.size() != N) return vector<int>();
  return ret;
}


int main(){
  int N, A, B;
  cin >> N >> A >> B;

  vector<int> ret = solve(N, A, B);

  if(ret.size() == 0){
    cout << -1 << endl;
  }else{
    rep(i,ret.size()){
      if(i>0) cout << " ";
      cout << ret[i];
    }
    cout << endl;
  }

  return 0;
}

