    --rem;
    if(cur==a){
      cur=0;
    }
  }
  vector<int> add;
  while(!que.empty()){
    int buf=que.front();que.pop();
    add.push_back(buf);
  }
  sort(add.begin(),add.end());
  reverse(ALL(add));
  int ind=0;
  rep(i,n){
    if(ans[i]==-1){
      //cout<<"hoge"<<endl;
      ans[i]=add[ind];
      ind++;
    }
  }
  rem=min(rem,cur);
  rep(i,cur){
    swap(ans[n-rem+i],ans[n-rem-1-i]);
  }
  if(flag){
    reverse(ALL(ans));
  }
  for(const auto& val:ans){
    cout<<val<<" ";
  }
  cout<<endl;
  return 0;
}

