const int N=3e5+2, INF=N;

int dp[N];

pair <int, int> f(int n, int *a)
{
    int inc=0, dec=0;
    dp[0]=-INF;
    for(int i=1; i<=n; ++i)
        dp[i]=INF;
    for(int i=1; i<=n; ++i)
    {
        int j=upper_bound(dp, dp+n+1, a[i])-dp;
        if(dp[j-1] < a[i] && a[i] < dp[j])
        {
            dp[j]=a[i];
            inc=max(inc, j);
        }
    }
    dp[0]=-INF;
    for(int i=1; i<=n; ++i)
        dp[i]=INF;
    for(int i=n; i>=1; --i)
    {
        int j=upper_bound(dp, dp+n+1, a[i])-dp;
        if(dp[j-1] < a[i] && a[i] < dp[j])
        {
            dp[j]=a[i];
            dec=max(dec, j);
        }
    }
    return {inc, dec};
}

int ans[N];

void solve(int *arr, int n, int a, int b)
{
    a=min(a, n);
    b=min(b, n);
    b=min(b, n-a+1);
    for(int i=1; i<=a; ++i)
        arr[i]=n-a+i;

    for(int i=2; i<=b; ++i)
        arr[n-b+i]=n-a-i+2;

    if(n-a-b+1>0 && a>0 && b>0)
        solve(arr+a, n-a-b+1, a-1, b-1);
}

