inline int get_max(const vec< int >& f, int p) {
    int r = 0;
    for(int cur = p;cur >= 0;cur = (cur & (cur + 1)) - 1) {
        r = max(r, f[cur]);
    }
    return r;
}

inline void upd(vec< int >& f, int p, int x) {
    for(int cur = p;cur < (int)f.size();cur |= (cur + 1)) {
        f[cur] = max(f[cur], x);
    }
}

int inc(const vec< int >& a) {
    int n = (int)a.size();
    vec< int > f(n + 1, 0);
    int r = 0;
    for(int i = 0;i < n;i++) {
        int x = get_max(f, a[i] - 1) + 1;
        r = max(r, x);
        upd(f, a[i], x);
    }
    return r;
}

bool check(int n, int a, int b, vec< int > p) {
    vec< int > p2 = p;
    for(int i = 0;i < n;i++) {
        p2[i] = n + 1 - p2[i];
    }
    if(inc(p) == a && inc(p2) == b) {
        return true;
    }
    return false;
}

bool brute(int n, int a, int b, vec< int >& res) {
    vec< int > p(n);
    for(int i = 0;i < n;i++) {
        p[i] = i + 1;
    }
    do {
        vec< int > p2 = p;
        for(int i = 0;i < n;i++) {
            p2[i] = n + 1 - p2[i];
        }
        if(inc(p) == a && inc(p2) == b) {
            res = p;
            return true;
        }
    }while(next_permutation(ALL(p)));
    return false;
}

bool solve(int n, int a, int b, vec< int >& res) {
    if(a + b - 1 > n) {
        return false;
    }
    if(a == 1) {
        if(b == 1) {
            if(n == 1) {
                res = {1};
                return true;
            }else {
                return false;
            }
        }else {
            if(b == n) {
                res.clear();
                for(int i = n;i >= 1;i--) {
                    res.push_back(i);
                }
                return true;
            }else {
                return false;
            }
        }
    }
    if(b == 1) {
        if(a == 1) {
            if(n == 1) {
                res = {1};
                return true;
            }else {
                return false;
            }
        }else {
            if(a == n) {
                res.clear();
                for(int i = 1;i <= n;i++) {
                    res.push_back(i);
                }
                return true;
            }else {
                return false;
            }
        }
    }

    int flag = 0;

    if(a < b) {
        swap(a, b);
        flag = 1;
    }

    if(a <= 3) {
        if(n > 9) {
            return false;
        }
        if(!brute(n, a, b, res)) {
            return false;
        }
        if(flag) {
            for(int& x : res) x = n + 1 - x;
        }
        return true;
    }

    if(1ll * (a - 1) * b < n) {
        return false;
    }

    int empt = n - a;
    int last = 0;

    for(int i = 1;i <= a;i++) {
        int ad = min(empt, b - 1);
        empt -= ad;
        ad++;
        for(int x = last + ad;x > last;x--) {
            res.push_back(x);
        }
        last += ad;
    }

    if(flag) {
        for(int& x : res) x = n + 1 - x;
    }

    return true;
}

bool random_solve(int n, int a, int b, vec< int >& res) {
    vec< int > p(n);
    for(int i = 0;i < n;i++) {
        p[i] = i + 1;
    }
    const double MAX_TIME = 1.89 * CLOCKS_PER_SEC;
    while(clock() < MAX_TIME) {
        vec< int > p2 = p;
        for(int i = 0;i < n;i++) {
            p2[i] = n + 1 - p2[i];
        }
        if(inc(p) == a && inc(p2) == b) {
            res = p;
            return true;
        }
    };
    return false;
}

