vector<int> make(int a, int b){
    vector<int> v;
    b--;
    int mx = n, mn = 1;
    int rem = n;
    bool modeA = true;
    while(true){
        vector<int> tmp;
        if(modeA){
            rep(i,a){
                tmp.push_back(mx);
                mx--;
                rem--;
                if(rem==0)break;
            }
            a--;
            modeA = false;
        }else{
            rep(i,b){
                tmp.push_back(mn);
                mn++;
                rem--;
                if(rem==0)break;
            }
            b--;
        }
        reverse(all(tmp));
        for(auto x : tmp){
            v.push_back(x);
        }
        if(rem==0)return v;

    }
    return v;
}

