}

void bkt(int k)
{
    if(k == n + 1)
    {
        verif();

        return;
    }

    int i;
    for(i = 1; i <= n; i ++)
    {
        if(ap[i] == 0)
        {
            ap[i] = 1;
            stk[k] = i;
            bkt(k + 1);
            ap[i] = 0;
        }
    }
}

void c1()
{
    int i;
    int grup = 1;
    for(i = 1; i <= n; i ++)
    {
        int mn = (n - b) / i + 1;
        int mx = n - b - i + 1;

        //cout << i << " " << mn << " " << mx << " " << a << "\n";
        if(a >= mn && a <= mx)
        {
            grup = i;

            break;
        }
    }

    if(grup > b)
    {
        out();
    }

    int cate = 0;
    for(i = 1; i * grup <= n; i ++)
    {
        if(n - b - i * grup + i + 1 == a)
        {
            cate = i;
            break;
        }
    }

    if(cate == 0)
        out();

    for(i = 1; i <= n - b - cate * grup; i ++)
        cout << i << " ";

    int j;
    int last = n - b - cate * grup;
    for(i = 1; i <= cate; i ++)
    {
        for(j = last + grup; j >= last + 1; j --)
            cout << j << " ";

        last += grup;
    }

    for(i = n; i >= n - b + 1; i --)
        cout << i << " ";
}

void c2()
{
    int i;
    for(i = 1; i <= a - 2; i ++)
        cout << i << " ";
    cout << a << " " << a - 1 << " ";

    for(i = a + 1; i <= n; i ++)
        cout << n - (i - (a + 1)) << " ";
    cout << "\n";
}

void c3()
{
    int i;
    for(i = 1; i < a; i ++)
        cout << i << " ";

    for(i = a; i <= n; i ++)
        cout << n - (i - a) << " ";
    cout << "\n";
}

void solve()
{
    if(a + b <= n - 1)
        c1();

    if(a + b == n)
        c2();

    if(a + b == n + 1)
        c3();
}

int main()
{
    cin >> n >> a >> b;

    if(a == 1 || b == 1)
    {
        if(a + b != n + 1)
            out();
    }

    if(a + b > n + 1)
        out();

    solve();

   // bkt(1);

    return 0;
}

