        if (c-(min(n, l)-(l-b))<k){
            for (int l2=n-k; l2>l-b; --l2) ans.pb(l2);
            for(int l2=n-k+1; l2<=n; ++l2) ans.pb(l2);
            break;
        }
        c-=b;
        for(int l2=min(n, l); l2>l-b; --l2) ans.pb(l2);
    }
    fox(l, ans.size()) cout << ans[l] << ' ';
    return 0;
}

