            if(perm[j] > perm[i]) chmax(mab, dpb[j]);
        }
        dpa[i] = maa + 1;
        dpb[i] = mab + 1;
    }
    int ra = *max_element(dpa, dpa+N);
    int rb = *max_element(dpb, dpb+N);
    return make_pair(ra, rb);
}

signed main() {
    int N, A, B; cin >> N >> A >> B;
    if(A+B-1 <= N && N <= A*B) {
        vector<int> buckets;
        buckets.push_back(A);
        if(B > 1) {
            int div = (N - A) / (B - 1);
            int mo = (N - A) % (B - 1);
            for(int i=0; i<N-1; i++) {
                if(i < mo) buckets.push_back(div + 1);
                else buckets.push_back(div);
            }
        }

        vector<int> ans;
