        for(int i=0; i<B; i++) {
            int base = N - sum - (buckets[i] - 1);
            for(int k=0; k<buckets[i]; k++) {
                ans.push_back(base + k);
            }
            sum += buckets[i];
        }
        for(int i=0; i<N; i++) {
            printf("%lld%c", ans[i], (i+1 == N ? '\n' : ' '));
        }
    }
    else {
        cout << -1 << endl;
    }
    return 0;
}

