void dfs(int x, int depth) {
	if (depth ==0)return;
	if (x - m >= depth) {
		for (int i = x - m + 1; i <= x;i++)
			vt.push_back(i);
		dfs(x - m, depth - 1);
	}
	else {
		for (int i = depth; i <= x; i++)
			vt.push_back(i);
		dfs(depth - 1, depth - 1);
	}
}
