const int maxn = 3e5+115;

int n, A, B;
int ans[maxn];
int at = 0;

void Init()
{
	scanf("%d%d%d", &n, &A, &B);
}

void Solve()
{
	if (A * B < n || A + B > n + 1) {
		puts("-1");
	}
	else if (B == 1) {
		for (int i = 1; i <= n; ++i) {
			printf("%d ", i);
		}
	}
	else {
		int N = (n - A) / (B - 1);
		for (int i = 1; i <= N; ++i) {
			for (int j = i * B; j > (i - 1) * B; --j) {
				ans[++at] = j;
			}
		}
		if (N * (B - 1) < (n - A)) {
			for (int i = N * B + 1 + (n - A) - (N * (B - 1)); i > N * B; --i) {
				ans[++at] = i;
			}
		}
		for (int i = at + 1; i <= n; ++i) ans[++at] = i;
		for (int i = 1; i <= n; ++i) printf("%d ", ans[i]);
	}
}

int main()
{
	Init();
	Solve();
	return 0;
}

