template<typename T> struct Compression {
  vector<T> idx2orig;
  Compression(const vector<T>& values): idx2orig(values) {
    sort(idx2orig.begin(), idx2orig.end());
    idx2orig.erase(unique(idx2orig.begin(), idx2orig.end()), idx2orig.end());
  }
  int toIndex(const T& orig) const { return lower_bound(orig); }
  int fromIndex(int idx) const { assert(0 <= idx && idx < (int)idx2orig.size()); return idx2orig[idx]; }
  int size(void) const { return idx2orig.size(); }
  int lower_bound(const T& orig) const { return std::lower_bound(idx2orig.begin(), idx2orig.end(), orig) - idx2orig.begin(); }
  int upper_bound(const T& orig) const { return std::upper_bound(idx2orig.begin(), idx2orig.end(), orig) - idx2orig.begin(); }
};

