bool ok;
int N;
int ANS[300010];

void f(int A, int B, int L, int R, int P, int CNT)
{
	if (CNT == 0)
	{
		if (A + B - 1 > R - L + 1)
		{
			ok = false;
		}
		else
		{
			if (A > B)
			{
				rep(i, 0, B)
				{
					ANS[P - i] = R - B + 1 + i;
				}
				rep(i, 0, A - 1)
				{
					ANS[P - B - i] = L + A - 2 - i;
				}
				f(A - 1, B - 1, L + A - 1, R - B, P - B - A + 1, CNT + 1);
			}
			else
			{
				rep(i, 0, A)
				{
					ANS[P - i] = L + A - 1 - i;
				}
				rep(i, 0, B - 1)
				{
					ANS[P - A - i] = R - B + 2 + i;
				}

				f(A - 1, B - 1, L + A, R - B + 1, P - B - A + 1, CNT + 1);
			}
		}
	}
	else
	{
		if (CNT == -1)return;
		if (A == 0 || B == 0)
		{
			ok = false;
			return;
		}
		if (A > B)
		{
			int tb = min(P + 1, B);
			rep(i, 0, B)
			{
				if (P - i == -1)return;
				ANS[P - i] = R - tb + 1 + i;
			}
			int ta = min(P - B + 1, A - 1);
			rep(i, 0, A - 1)
			{
				if (P - B - i == -1)return;
				ANS[P - B - i] = L + ta - 1 - i;
			}
			f(A - 1, B - 1, L + A - 1, R - B, P - B - A + 1, CNT + 1);
		}
		else
		{
			int ta = min(P + 1, A);
			rep(i, 0, A)
			{
				if (P - i == -1)return;
				ANS[P - i] = L + ta - 1 - i;
			}
			int tb = min(P - A + 1, B - 1);
			rep(i, 0, B - 1)
			{
				if (P - B - i == -1)return;
				ANS[P - A - i] = R - tb + 1 + i;
			}

			f(A - 1, B - 1, L + A, R - B + 1, P - B - A + 1, CNT + 1);
		}
	}
}

signed main()
{
	cin.tie(0);
	ios::sync_with_stdio(false);

	int A, B;
	cin >> N >> A >> B;

	ok = true;
	f(A, B, 1, N, N - 1, 0);
	if (ok)
	{
		rep(i,0,N)cout << ANS[i] << " ";
		cout << endl;
	}
	else
	{
		cout << -1 << endl;
	}

	return 0;
}

