int N, A, B;

deque<int> calc(){
    int last_end = 0;
    deque<int> seq;
    while((int)seq.size() < N){
        bool is_first = false;
        int first = -1;
        if((int)seq.size() == 0){
            last_end = 0;
            for(int i = 0; i < A; i++){
                seq.push_back(i);
                if((int)seq.size() == N) return seq;
                if(!is_first){
                    is_first = true;
                    first = i;
                }
            }
        }
        else{
            seq.pop_back();
            int a = last_end - (A - 1);
            for(int i = 0; i < A; i++){
                seq.push_back(a + i);
                if((int)seq.size() == N) return seq;
                if(!is_first){
                    is_first = true;
                    first = a + i;
                }
            }
        }
        int n_last_end = -1;
        for(int i = 0; i < B - 1; i++){
            seq.push_back(first - 1 - i);
            if((int)seq.size() == N) return seq;
            n_last_end = first - 1 - i;
        }
        last_end = n_last_end;
    }
    return seq;
}

