                cout << i << " " ;
            }
            cout << endl;
        }
        else{
            cout << -1 << endl;
        }
        return 0;
    }

    if(A + B - 1 > N){
        cout << -1 << endl;
        return 0;
    }

    auto s = calc();


    vector<pii> v;
    for(int i = 0; i < (int)s.size(); i++){
        v.push_back(pii(s[i], i));
    }
    sort(v.begin(), v.end());

    vector<int> ans(N);

    for(int i = 0; i < (int)s.size(); i++){
        int b = v[i].second;
        ans[b] = i + 1;
    }

    for(int a : ans){
        cout << a << " ";
    }
    cout << endl;

    return 0;
}

