ll N, A, B;
void ind(){
    for (int i = 0; i < A; ++i) {
        ans.push_back(N - A + 1 + i);
    }
    N -= A; B--;
}

void solve(){
    for (int i = B; i <= N; ++i) {
        ans.push_back(i);
    }
    for (int i = B - 1; i > 0; --i) {
        ans.push_back(i);
    }
}

