int LIS(vi vec, int n) {
	set<int> s;
	for (int i = 1 ; i <= n ; ++i) {
		set<int>::iterator it = s.lower_bound(vec[i]);
		if (it != s.end()) s.erase(it);
		s.insert(vec[i]);
	}
	return s.size();
}

int LDS(vi vec, int n) {
	for (int i = 1 ; i <= n ; ++i) vec[i] = -vec[i];
	set<int> s;
	for (int i = 1 ; i <= n ; ++i) {
		set<int>::iterator it = s.lower_bound(vec[i]);
		if (it != s.end()) s.erase(it);
		s.insert(vec[i]);
	}
	return s.size();
}

vi soln(int n, int a, int b) {
	int mn = min(a, b);
	if (a + b > n + 1 || a * b < n) {
		return vi(); 
	}

	vi ans(n + 1);
	int curr = 1, rem = n, num = 1, A = a, B = b;

	while (rem > 0) {
		if (a + b > rem) {
			int m = num + rem - a;
			for (int i = 0 ; i < a ; ++i) {
				ans[curr++] = m++; 
			}
			for (int i = 1 ; i <= rem - a ; ++i) {
				ans[curr++] = num + rem - a - i;
			}
			break;
		}
		for (int i = 1 ; i <= b ; ++i) {
			ans[curr++] = num + b - i;
		}
		--a;
		num = num + b;
		rem -= b;
	}

	return ans;
}

