int n;

int Sg( int x , int k ){
	if( x < k ) return 0;
	if( k == 1 ) return x;

	int d = x/k;
	if( x%k == 0 ) return d;

	int step = d+1;
	int rest = x%k;
	int walk = max(1,rest/step);
	int dis = walk * step;
	return Sg( x - dis , k );
}

