template<class T, class T2> inline void chkmax(T &x, const T2 &y) { if(x < y) x = y; }
template<class T, class T2> inline void chkmin(T &x, const T2 &y) { if(x > y) x = y; }
const int MAXN = (1 << 20);

template <class T>
struct fenwick
{
	int sz;
	T tr[MAXN];

	void init(int n)
	{
		sz = n + 1;
		memset(tr, 0, sizeof(tr));
	}

	T query(int idx)
	{
		T ans = 0;
		for(; idx >= 1; idx -= (idx & -idx))
			chkmax(ans, tr[idx]);
		return ans;
	}

	void update(int idx, T val)
	{
		if(idx <= 0) return;
		for(; idx <= sz; idx += (idx & -idx))
			chkmax(tr[idx], val);
	}
};

int n, a, b;

void read()
{
	cin >> n >> a >> b;
}

void solve()
{
	if(a + b - 1 > n)
	{
		cout << -1 << endl;
		return;
	}

	vector<int> answer;
	for(int x = 1; x <= a; x++) answer.push_back(x);

	vector<int> bg;
	int val = n;
	for(int i = 0; i < a; i++)
	{
		int cnt = (n - answer.size() - bg.size());
		chkmin(cnt, b - 1);	

		for(int j = cnt; j >= 1; j--)
		{
			bg.push_back(val - j + 1);
			if((int)bg.size() + (int)answer.size() == n)
				break;
		}

		if((int)answer.size() + (int)bg.size() == n) break;
		val -= (b - 1);
	}

	if((int)answer.size() + (int)bg.size() != n) 
	{
		cout << -1 << endl;
		return;
	}

	reverse(bg.begin(), bg.end());
	reverse(answer.begin(), answer.end());
	while(!answer.empty())
	{
		bg.push_back(answer.back());
		answer.pop_back();
	}

	answer = bg;
	for(int x: answer) cout << x << " ";
	cout << endl;
}

int main()
{
	ios_base::sync_with_stdio(false);
	cin.tie(NULL);

	read();
	solve();
	return 0;
}

