	else {
		VI ans;

		if (A + B == N + 1) {
			B--;
			int n = N;
			REP(i, B)ans.push_back(n--);
			REP(i, A)ans.push_back(i + 1);

		}
		else {

			if (abs(A - B) > 1) {
				cout << -1 << endl;
				return 0;				
			}

			if (N % 2 == 0) {
				int a = 1, b = N;
				while (a < b) {
					ans.push_back(b--);
					ans.push_back(a++);
				}
			}
			else {
				if (A > B) {
					int a = A+1, b = B;
					while (b > 0 && a <= N) {
						ans.push_back(b--);
						ans.push_back(a++);
					}
					ans.push_back(max(A, B));
				}
				else {
					int a = B +1, b = B;
					while (b > 0 && a <= N) {
						ans.push_back(b--);
						ans.push_back(a++);
					}
					ans.push_back(1);
				}
			}

		}



		REP(i, N)cout << ans[i] << " ";
		cout << endl;
	}


	return 0;
}

