    int x = rem / (a - 1);
    int y = rem % (a - 1);
    for(int i = 0; i < y; i++){
        int size = (int)ans.size();
        for(int j = 0; j < x + 1; j++){
            ans.push_back(size + x - j + 1);
        }
    }
    int v = (a - 1) - y;
    for(int i = 0; i < v; i++){
        int size = (int)ans.size();
        for(int j = 0; j < x; j++){
            ans.push_back(size + x - j);
        }
    }
    REP(i, ans.size()) {
        cout << ans[i];
        i == (int)ans.size() - 1 ? cout << endl : cout << ' ';
    }
    return 0;
}

