int LIS(vector<int> x) {
    vector<int> dp(x.size() + 1, inf<int>);
    for(auto y : x) {
        *lower_bound(begin(dp), end(dp), y) = y;
    }
    return lower_bound(begin(dp), end(dp), inf<int>) - begin(dp);
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;
    vector<int> ans;
    if(A == 1) {
        for(int i = 0; i < N; ++i) {
            ans.push_back(N - i);
        }
    } else if(B == 1) {
        for(int i = 0; i < N; ++i) {
            ans.push_back(i + 1);
        }
    } else {
        int nowA = N - A + 1;
        int nowB = B - 1;
        int putB = 0;
        while((int)ans.size() != N) {
