inline int add(int a, int b) { int res = a + b; if(res >= mod) res -= mod;  return res; }
inline int sub(int a, int b) { int res = a - b; if(res < 0) res += mod; return res;}
inline int mul(int a, int b) { return (a * b)%mod; }

void solve() {
    int n, a, b; cin >> n >> a >> b;
    if(a+b-1 > n or a*b<n) {
        cout << -1 << endl;
        return;
    }
    if(b==1) {
        for(int i=1; i<=n; i++) cout << i << " ";
        return;
    }
    vector<int> ans;
    int st = n - a + 1;
    for(int i=st; i<=n; i++) ans.push_back(i);
    int div = (n - a)/(b - 1);
    int rem = n - a;
    int ex = rem - div*(b - 1);
    for(int i=0; i<ex; i++) {
        // Add extra in then
        vector<int> v;
        for(int j=0; j<div+1; j++) v.push_back(rem - j);
        rem -= (div + 1);
        reverse(v.begin(), v.end());
        for(int x : v) ans.push_back(x);
    }
    for(int i=0; i < (b - 1 - ex); i++) {
        vector<int>v;
        for(int j=0; j<div; j++) v.push_back(rem - j);
        rem -= div;
        reverse(v.begin(), v.end());
        for(int x : v) ans.push_back(x);
    }
    for(int x : ans) cout << x << " ";
    cout << endl;
}

