template<typename T>
int LIS(const vector<T> &a){
    vector<T> lis;
    for(auto &p:a){
        typename vector<T>::iterator it;
        //同値許容しない(狭義単調増加)
        it=lower_bound(begin(lis),end(lis),p);
        //同値許容(広義単調増加)
        // it=upper_bound(begin(lis),end(lis),p);
        if(end(lis)==it) lis.push_back(p);
        else *it=p;
    }
    return int(lis.size());
}

