        }
    }
    rep(i, N) {
        if (ans[i] == -1) ans[i] = i;
    }
    rep(i, N) {
        cout << ans[i] + 1;
        if (i == N - 1) cout << "\n";
        else cout << " ";
    }
    return 0;
}

