vll solve(ll n, ll a, ll b) {
    if (a+b>n+1) {
        return {-1};
    }
    bool swapped = 0;
    if (b > a) swap(a, b), swapped = 1;

    ll b0 = (n + a - 1) / a;
    ll rem = (n % a == 0 ? a : n % a);
    vll r;
    for (ll i = n; rem; i--, rem--) {
        r.pb(i);
    }
    reverse(all(r));
    if (b - b0 < 0) {
        return {-1};
    }
    if (b-b0+1 > r.size()) {
        return {-1};
    }
    reverse(r.begin(), r.begin()+b-b0+1);
    vll ret;
    rep(i, r.size()) {
        ret.pb(r[i]);
    }
    rep(i, b0-1) {
        rep(j, a) {
            ret.pb((b0-2-i)*a+j+1);
        }
    }

    if (swapped) {
        rep(i, ret.size()) {
            ret[i] = n+1-ret[i];
        }
        swap(a, b);
    }

    if (LISa(ret) != a || LISd(ret) != b) {
        cout << "##########################################" << endl;
        cout << n << " " << a << " " << b << endl;
    }
    return ret;
}

