    for(int i = 0; i < ans.size(); i++)
    {
        u[ans[i]] = 1;
    }

    for(int i = 1; i <= n; i++)
    {
        if(u[i] == 0)
        {
            l = min(l, i);
            r = max(r, i);
        }
    }

    if(l <= r)
    {
        int y = r - l + 1;
        for(int i = ans.size() - 1; i >= ans.size() - y; i--)
        {
            ans[i] += y * o;
        }
    }
    for(int i = 0; i < ans.size(); i++)
        cout << ans[i] << " ";

