    small_block = rest / (B - 1),
    large = rest % (B - 1),
    next_left = A,
    next_largest = N - A;
  for (auto i = 0; i < B - 1; i++) {
    Z bsize = i < large ? small_block + 1 : small_block;
    for (auto j = 0; j < bsize; j++) {
      ix(ans, next_left + j) = next_largest - bsize + 1 + j;
    }
    next_left += bsize;
    next_largest -= bsize;
  }
  assert(next_left == N);
  cout << ans << '\n';
