std::vector<int> lis_lds (int n, int a, int b) {
	std::vector<int> res; res.reserve(n);
	std::vector<int> c(b, 1);
	for (int i = 0, s = n - b; i < b; i++) {
		int v = std::min(s, a - 1);
		c[i] += v; s -= v;
	}
	for (int i = 0, s = n; i < b; i++) {
		for (int j = s - c[i]; j < s; j++) res.push_back(j);
		s -= c[i];
	}
	return res;
}

