#include<bits/stdc++.h>
using namespace std;
vector<int> solve(auto N, auto A, auto B) {
  if(N+1 < A+B) return {-1};
  vector<int> res;
  if(2*A < N) {
    if(B==1) return {-1};
    vector<vector<int>> part;
    auto Q = N/A;
    for(auto i=1; i+Q-1<=N; i+=Q) {
      part.insert(begin(part), vector<int>());
      for(auto j=0; j<Q; ++j) part.front().push_back(i+j);
      for(auto& j: part.front()) j = N-j+1;
    }
    if(part.size() < A) return {-1};
    for(auto i=0; i<part.size(); ++i) {
      if(i<A) res.insert(end(res), begin(part[i]), end(part[i]));
      else    res.insert(begin(res), begin(part[i]), end(part[i]));
    }
    B -= Q;
    B -= part.size()-A;
    auto r = N%Q;
    if(r < B) return {-1};
    for(auto i=0; i<B-1; ++i) res.push_back(B-i-1);
    vector<int> t1, t2;
    for(auto i=1; i<=r; ++i) {
      if(i<=B)t1.push_back(i);
      else    t2.push_back(i);
    }
    reverse(begin(t1), end(t1));
    res.insert(end(res), begin(t1), end(t1));
    res.insert(end(res), begin(t2), end(t2));
    return res;
  }
  for(auto i=N-A+1; i<=N; ++i) res.push_back(i);
  if(A+B==N+1) {
    for(auto i=0; i<B-1; ++i) res.push_back(N-B-i);
  } else if(B==1) {
    return {-1};
  } else {
    for(auto i=0; i<B-1; ++i) res.push_back(B-i-1);
    for(auto i=B; i<=N-A; ++i) res.push_back(i);
  }
  assert(res.size()==N);
  return res;
}
