  auto r = false;
  if(A < B) {
    r = true;
    swap(A, B);
  }
  auto v = solve(N, A, B);
  if(r) reverse(begin(v), end(v));
  for(auto i=0; i<v.size(); ++i) cout << (i ? " " : "") << v[i];
  cout << endl;
}

