    vector<ll> ans;

    if (N <= A + B - 2 || N > A * B) {
        cout << -1 << endl;
        return 0;
    }

    ans = solve2(N, A, B);

    for (ll i = 0; i < ans.size(); i++) {
        cout << ans[i] + 1 << " \n"[i == ans.size() - 1];
    }

    return 0;
}

