	now = n - a;
	FOR(i, n - a + 1, n + 1)ans.push_back(i);
	REP(i, b - 1) {
		ll s = (n - a) / (b - 1);
		if ((n - a) % (b - 1) > i)s++;
		FOR(j, now - s + 1, now + 1)ans.push_back(j);
		now -= s;
	}
	if (rev)reverse(ALL(ans));
	REP(i, ans.size()) {
		if (i != 0)cout << " ";
		cout << ans[i];
	}
	cout << endl;
}

