template <typename T> constexpr T inf;
template <> constexpr int inf<int> = 1e9;
template <> constexpr ll inf<ll> = 1e18;
template <> constexpr double inf<double> = 1e18;

int LIS(vector<int> x) {
    vector<int> dp(x.size() + 1, inf<int>);
    for(auto y : x) {
        *lower_bound(begin(dp), end(dp), y) = y;
    }
    return lower_bound(begin(dp), end(dp), inf<int>) - begin(dp);
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;
    if(A > N || B > N) {
        cout << -1 << endl;
        return 0;
    }
    vector<int> ans;
    if(A == 1) {
        for(int i = 0; i < N; ++i) {
            ans.push_back(N - i);
        }
    } else if(B == 1) {
        for(int i = 0; i < N; ++i) {
            ans.push_back(i + 1);
        }
    } else {
        int nowA = N - A + 1;
        int nowB = B - 1;
        int putB = 0;
        while(nowA <= N) {
            ans.push_back(nowA++);
            for(int minus = 0; minus <= B - 2 && putB != N - A && (int)ans.size() != N; ++minus) {
                ans.push_back(nowB - minus);
                putB++;
            }
            nowB = min(nowB + B - 1, B);
        }

        // check
        auto tmp = ans, rev_tmp = ans;
        auto aa = LIS(tmp);
        sort(begin(tmp), end(tmp));
        tmp.erase(unique(begin(tmp), end(tmp)), end(tmp)); // permutation ?
        reverse(begin(rev_tmp), end(rev_tmp));
        auto bb = LIS(rev_tmp);
        //for(auto x : ans) {
        //    cout << x << ' ';
        //}
        //cout << endl;
        if(aa != A || bb != B || (int)tmp.size() != N || nowA != N + 1 || putB != N - A) {
            ans.clear();
        }
    }
    if(ans.empty()) {
        cout << -1 << endl;
    } else {
        for(int i = 0; i < N; ++i) {
            cout << ans[i] << " \n"[i + 1 == N];
        }
    }
}

