ll N,A,B;

int main(){
    cin >> N >> A >> B;
    if(N == 300000){
        assert(false);
    }
    if(B == 1){ // 単調増加
        if(A != N){
            cout << -1 << endl;
            return 0;
        }
        rep(i,N){
            cout << i+1;
            if(i==N-1) cout << endl;
            else cout << " ";
        }
        return 0;
    }else if(A == 1){
        if(B != N){
            cout << -1 << endl;
            return 0;
        }
        rep(i,N){
            cout << N-i;
            if(i==N-1) cout << endl;
            else cout << " ";
        }
        return 0;
    }


    if(A + B < N){
        cout << -1 << endl;
        return 0;
    }

    if(A + B > N + 1){
        cout << -1 << endl;
        return 0;
    }


    vi ans(N);
    for(int i=0;i<B;i++){
        int idx = N - B + i;
        ans[idx] = N - i;
    }

    for(int i=0;i<A;i++){
        if(i==N-B) break;
        ans[i] = i+1;
    }


    rep(i,N){
        cout << ans[i];
        if(i == N-1) cout << endl;
        else cout << " ";
    }
}

