const int inf = 1e9 + 7;
const int N = 3e5 + 5;

int n, a, b, mn = inf, ans[N];

int main(){
      scanf("%d %d %d", &n, &a, &b);

      for(int i = 1; i <= n; i ++){
            int cur = i + (n + i - 1) / i;
            mn = min(mn, cur);
      }

      if((a + b) > n + 1 || (a + b) < mn){
            puts("-1");
            return 0;
      }

      if(a == 1){
            if(b != n){
                  puts("-1");
                  return 0;
            }
            for(int i = n; i >= 1; i --)
                  printf("%d ", i);
            return 0;
      }
      if(b == 1){
            if(a != n){
                  puts("-1");
                  return 0;
            }
            for(int i = 1; i <= n; i ++)
                  printf("%d ", i);
            return 0;
      }

      for(int i = 1; i <= n; i ++)
            ans[i] = i;

      int last = n - a + 1;

      for(int i = 1; i <= n; i += b){
            int l = i, r;
            r = l + b - 1;
            r = min(r, last);
            if(l >= r) break;
            reverse(ans + l, ans + r + 1);
            last ++;
      }

      for(int i = 1; i <= n; i ++)
            printf("%d ", ans[i]);
}

