      ans=-1;
    else{
      cnt=0;
      for(int i=0; i<a; ++i){
        g[i]=n-a+i+1;
        ++cnt;
      }
      --b;
      bool l=0;
      int tmp=2;
      vector <int> v;
      while(1){
        if(n-cnt>=a){
          for(int j=0; j<a; ++j){
            if(n-cnt<=b){
              l=1;
              for(int k=j; k<a; ++k)
                v.push_back(n-tmp*a+k+1);
              reverse(v.begin(), v.end());
              break;
            }
            g[cnt]=n-tmp*a+j+1;
            ++cnt;
          }
        }
        else{
          int t=n-cnt;
          for(int j=1; j<=t; ++j){
            if(n-cnt<=b){
              l=1;
              for(int k=j; k<=t; ++k)
                v.push_back(k);
              reverse(v.begin(), v.end());
              break;
            }
            g[cnt]=j;
            ++cnt;
          }
          if(l){
            if(n-cnt!=b)
              ans=-1;
            for(int j=0; j<v.size(); ++j){
              g[cnt]=v[j];
              ++cnt;
            }
          }
          break;
        }
        if(!l){
          ++tmp;
          --b;
        }
        else{
          if(n-cnt!=b)
            ans=-1;
          for(int j=0; j<v.size(); ++j){
            g[cnt]=v[j];
            ++cnt;
          }
          for(int j=cnt; j<n; ++j){
            g[j]=n-j;
          }
          break;
        }
      }
    }
    if(ans==-1){
      cout<<-1<<endl;
    }
    else{
      for(int i=0; i<n; ++i){
        cout<<g[i]<<" ";
      }
      cout<<endl;
    }
  }
  return 0;
}

