int main(void) {
    lint n, a, b;
    cin >> n >> a >> b;

    if (n < a + b -1) {
        cout << "-1" << endl;
        return 0;
    }
    if (n > a * b) {
        cout << "-1" << endl;
        return 0;
    }

    vector<lint> r(a * b, 0);
    lint idx = 0;
    repeat (i, b) {
        repeat (j, a) {
            r[idx] = a * (b - 1 - i) + 1 + j;
            ++idx;
        }
    }

    lint c = a * b - n;
    idx = -1;
    repeat (i, b) {
        repeat (j, a) {
            ++idx;
            if (i == 0) continue;
            if (j == 0) continue;
            if (c <= 0) break;
            //dump(i); dump(j); dump(c); dump(idx); el;
            r[idx] = (-1)*c;
            --c;
        }
        if (c <= 0) break;
    }
    //vdump(r);

    vector<lint> s;
    repeat (i, r.size()) {
        if (r[i] > 0) {
            s.emplace_back(r[i]);
        }
    }
    //vdump(s);

    // 座標圧縮(配列sの値を破壊的に変更する)
    // ソート → 一意要素を前に → 後半に残る重複要素を削除 → 二分探索で元の数字のindexを調べる
    auto t = s;
    sort(t.begin(), t.end());
    auto it = unique(t.begin(), t.end());
    t.erase(it, t.end());
    for(auto &e: s) {
        e = lower_bound(t.begin(), t.end(), e) - t.begin();
    }
    //vdump(s);

    repeat (i, s.size()) {
        cout << s[i] + 1 << " ";
    }
    return 0;
}

