#include <bits/stdc++.h>
#define REP(i, a, n) for(ll i = ((ll) a); i < ((ll) n); i++)
using namespace std;
typedef long long ll;

void compress(vector<ll> &x) {
  vector<ll> v(x.size());
  REP(i, 0, x.size()) v[i] = x[i];
  sort(v.begin(), v.end());
  v.erase(unique(v.begin(), v.end()), v.end());
  REP(i, 0, x.size()) x[i] = lower_bound(v.begin(), v.end(), x[i]) - v.begin();
}

int main(void) {
  ll N, A, B;
  cin >> N >> A >> B;

  ll xa = A * B - (A - 1), xb = A * B - (B - 1);
  if(min(xa, xb) <= N && N <= A * B) {
    vector<ll> vec(A * B);
    if(A >= B) {
      REP(i, 0, B) REP(j, 0, A) vec[i * A + j] = (B - i) + B * j;
    } else {
      REP(i, 0, B) REP(j, 0, A) vec[i * A + j] = A * B - ((A - j) + A * i);
    }

    vector<ll> ans;
    REP(i, 0, A) if(i >= A * B - N) ans.push_back(vec[i]);
    REP(i, A, A * B) ans.push_back(vec[i]);

    compress(ans);

    REP(i, 0, ans.size()) cout << ans[i] + 1 << (i + 1 != ans.size() ? " " : "\n");
  } else {
    cout << -1 << endl;
  }
}

