void solve() {
  i64 N, A, B;
  cin >> N >> A >> B;
  if (N < A + B - 1 || A * B < N) no();
  vector<vi32> lst(B, vi32(A, 0));
  vector<vi32> flg(B, vi32(A, 1));
  rep(i, B) rep(j, A) {
    lst[i][j] = (B - i - 1) * A + j;
  }
  int cnt = A;
  rep(j, A) reps(i, B - 1) {
    if (++cnt > N) flg[i][j] = 0;
  }
  vi32 cc;
  rep(i, B) rep(j, A) if (flg[i][j]) cc.push_back(lst[i][j]);
  sort(all(cc));
  unordered_map<int, int> ma;
  rep(i, N) ma[cc[i]] = i + 1;
  vi32 ans;
  rep(i, B) rep(j, A) if (flg[i][j]) {
    ans.push_back(ma[lst[i][j]]);
  }
  cout << ans << '\n';
}

