vector<int> LISLDS(const int N, const int A, const int B) {
    vector<int> ret;
    for(int i = B - 1; i >= 0; i--)
        ret.push_back(i);

    int n = N - B;
    int a = A - 1;
    if(a == 0) return ret;

    rep(i, a) {
        int siz = ret.size();
        for(int j = n / a - (i < n % a ? 0 : 1); j >= 0; j--)
            ret.push_back(siz + j);
    }

    return ret;
}

