void rev(vi& perm, int f, int t) { 
  while(f < t) { 
    swap(perm[f], perm[t-1]); 
    f++; 
    t--; 
    } 
  } 

class LadderPermutation { 
  public: 
  vector <int> createLadder(int n, int m, int k) { 
    // !FDI 
    vi error; 
    vi res; 
    for(int t=0; t<n; t++) res.push_back(t+1); 
    rev(res, n-k, n); 
    int currm = n - k + 1; 
    if(currm < m) return error; 
    int nat = n - k; 
    while(currm > m) { 
      if(nat == 0) return error; 
      int eat = k; 
      if(eat > nat) eat = nat; 
      /* currm - (eat-1) == m => eat = currm - m + 1 */ 
      if(eat > currm-m+1) eat = currm-m+1; 
      rev(res, nat-eat, nat); 
      currm -= (eat-1); 
      nat -= eat; 
      } 
    return res; 
    } 
  }; 


