vl p;

void my_reverse(vl &p,int i,int j){
    while(i<j){
        swap(p[i],p[j]);
        i++;j--;
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    ll N,A,B;
    cin >> N >> A >> B;
    if(A+B-1>N||A*B<N){
        cout << -1 << '\n';
    }
    else{
        ll now_B=(N-1)/A+1;
        p.resize(N);
        rep(i,N){
            p[i]=N-(A-1)-(i/A)*A+i%A;
        }
        ll D=B-now_B;
        for(int i=0;i<N-1;i+=A){
            if(D>=A-1&&i/A==(i+1)/A){
                my_reverse(p,i,i+A-1);
                D-=A-1;
            }
            else if(D>0){
                my_reverse(p,i,i+D);
                D=0;
            }
        }
        rep(i,N){
            cout << p[i] << ( i==N-1 ? '\n' : ' ' );
        }
    }
}

