int main(){
    int N, A, B;
    cin >> N >> A >> B;

    if(A + B - 1 > N || A * B < N){
        cout << -1 << endl;
        return 0;
    }

    int other = 0;
    int amari = 0;
    if(A - 1 != 0){
        other = (N - A - B + 1) / (A - 1);
        amari = (N - A - B + 1) % (A - 1);
    }
    //cout << other << " " << amari << endl;
    int prev = 0;

    vector<int> ans;
    for(int i = 0; i < A; ++i){
        ans.push_back(i+1);
        if(i == 0){
            for(int j = A + B - 1; j > A; --j){
                ans.push_back(j);
            }
            prev = A + B - 1;
        }
        else if(i <= amari){
            for(int j = other+1; j > 0; --j){
                ans.push_back(j + prev);
            }
            prev += other+1;
        }
        else if(i != A - 1){
            for(int j = other; j > 0; --j){
                ans.push_back(j + prev);
            }
            prev += other;
        }
    }
    if(ans.size() != N){
        cout << -1 << endl;
    }
    else {
        for(int i = 0; i < N; ++i){
            cout << ans[i];
            if(i != N - 1) cout << " ";
        }
        cout << endl;
    }
}

