void c1()
{
    int i;
    int grup = 1;
    for(i = 1; i <= n; i ++)
    {
        int mn = (n - b) / i + 1;
        int mx = n - b - i + 1 + 1;

        //cout << i << " " << mn << " " << mx << " " << a << "\n";
        if(a >= mn && a <= mx)
        {
            grup = i;

            break;
        }
    }

    //cout << grup << "\n";

    if(grup > b)
    {
        out(1);
    }

    int bs = 0;
    for(i = 0; i * b + b <= n; i ++)
    {
        if(i + 1 <= a && a <= n - b - i * b + i + 1)
            bs = i;
    }

    int rest = 0;
    if(bs + 1 + (n - b - bs * b) > a)
        rest = bs + 1 + (n - b - bs * b) - a;

    int nr = 0;
    for(i = 1; i <= n - b - bs * b - (rest + 1); i ++)
    {
        cout << i << " ";
        nr = i;
    }

    int ult = nr;
    int j;
    for(j = nr + rest + 1; j >= nr + 1; j --)
        cout << j << " ", ult = max(ult, j);

    for(i = 1; i <= bs; i ++)
    {
        int ant = ult;
        for(j = ult + b; j >= ult + 1; j --)
            cout << j << " ", ant = max(ant, j);

        ult = ant;
    }

    for(i = n; i >= n - b + 1; i --)
        cout << i << " ";
}

void c3()
{
    int i;
    for(i = 1; i < a; i ++)
        cout << i << " ";

    for(i = a; i <= n; i ++)
        cout << n - (i - a) << " ";
    cout << "\n";
}

void solve()
{
    if(a + b <= n)
        c1();

    if(a + b == n + 1)
        c3();
}

