void solve0() {
	int q0 = n / a + (n % a ? 1 : 0);
	int q1 = n / a + (n % a);
	if (q0 <= b && b <= q1) {
		for(int i = n - a + 1; i >= 1; i -= a) {
			fj(0, a - 1) {
				ans.pb(i + j);
			}			
		}		
		int q = b - n / a;
		int r = n % a;
		fdi(q, 1) {
			ans.pb(i);
		}
		fi(q + 1, r) {
			ans.pb(i);
		}
		for(int z : ans) {
			printf("%d ", z);
		}
		exit(0);
	} else {
		return;
	}
}

void solve1() {
	int q0 = n / b + (n % b ? 1 : 0);
	int q1 = n / b + (n % b);
	if (q0 <= a && a <= q1) {
		for(int i = b; i <= n; i += b) {
			fj(0, b - 1) {
				ans.pb(i - j);	
			}
		}		
		int q = a - n / b;
		int r = n % b;
		fdi(q - 1, 0) {
			ans.pb(n - i);			
		}
		fdi(n - q, n - r + 1) {
			ans.pb(i);
		}
		for(int z : ans) {
			printf("%d ", z);
		}
		exit(0);
	} else {
		return;
	}
}

void solve() {
	if (a > n || b > n) {
		bad();
	}
	solve0();
	solve1();	
	bad();
}

