    ios::sync_with_stdio(false);

    ll N, A, B;
    cin >> N >> A >> B;

    vector<ll> ans;

    bool rev = B > A;
    if (rev) {
        swap(A, B);
    }

    for (ll i = N - A + 1; i <= N; i++) {
        ans.push_back(i);
    }

    if (A == N) {
        if (B != 1) {
            cout << -1 << endl;
