            out(ans, rev);
        }
        return 0;
    }

    if (B == 1) {
        cout << -1 << endl;
        return 0;
    }

    for (ll i = 0; i < (N - A) / (B - 1); i++) {
        for (ll j = (i + 1) * (B - 1); j > i * (B - 1); j--) {
            ans.push_back(j);
        }
    }

    if ((N - A) % (B - 1) != 0) {
        for (ll i = N - A; i >= N - A - N % (B - 1); i--) {
            ans.push_back(i);
        }
    }

    if (ans.back() <= 0) {
