const int MAX_N = 300005;
int N, A, B, p[MAX_N];

int main() {
  scanf("%d%d%d", &N, &A, &B);
  if (A + B - 1 > N) {
    puts("-1");
    return 0;
  }

  if (1LL * A * B < N) {
    puts("-1");
    return 0;
  }

  int r = N, l = 1, pos = 0;
  for (int i = 1; i <= A; ++i)
    p[++pos] = N - A + i;
  for (int i = 1; i < B; ++i)
    p[++pos] = B - i;

  r = N - A, l = B;

  while (l <= r) {
    int len = min(A - 1, r - l + 1);
    for (int i = 1; i <= len; ++i)
      p[++pos] = r - len + i;
    r -= len;
    if (l > r) break;
    len = min(B - 1, r - l + 1);
    for (int i = 1; i <= len; ++i)
      p[++pos] = l + len - i;
    l += len;
  }

  for (int i = 1; i <= N; ++i)
    printf("%d ", p[i]);
  puts("");
  return 0;
}

