inline void solve() {
	int n, a, b;
	scanf("%d%d%d", &n, &a, &b);
	if (a + b - 1 <= n && 1ll * n <= 1ll * a * b) {
		vector <long long> v;
		int A = 0;
		int B = b;
		while ((int)v.size() + a< n) {
			if (B == b) {
				a--;
			}
			v.push_back(1ll * A * b + 1ll * B);
			B--;
			if (B == 0) {
				B = b;
				A++;
			}
		}
		A++;
		if (B != b) {
			A++;
		}
		while ((int)v.size() < n) {
			v.push_back(1ll * A * b);
			A++;
		}
		vector <long long> v2;
		v2 = v;
		sort(v2.begin(), v2.end());
		for (int i = 0; i < (int)v.size(); i++) {
			int pos = (int)(lower_bound(v2.begin(), v2.end(), v[i]) - v2.begin());
			v[i] = pos + 1;
		}
		for (auto i: v) {
			printf("%lld ", i);
		}
		printf("\n");
	} else {
		printf("-1\n");
	}
}
