        cout << -1 << endl;
        return 0;
    }
    if (a + b < (n + 1) / 2 + 2) {
        cout << -1 << endl;
        return 0;
    }

    deque<int> dq;
    for (int i = 1; i <= n; i++) {
        dq.push_back(i);
    }

    if (a == 1 || b == 1) {
        if (max(a,b) != n) {
            cout << -1 << endl;
            return 0;
        }
        vector<int> v;
