            v.push_back(dq.front());
            dq.pop_front();
        }
        if (a == 1) reverse(v.begin(), v.end());
        out(v);
        return 0;
    }

    for (int i = 0; i < (n + 1) - (a + b) + 1; i++) {
        dq.push_back(dq.front());
        dq.pop_front();
    }

    vector<int> v;
    while (!dq.empty()) {
        v.push_back(dq.front());
        dq.pop_front();
    }
    reverse(v.begin(), v.begin() + (min(a,b) - 1));

    if (a < b) reverse(v.begin(), v.end());
    out(v);

