bool solve(int n, int a, int b, vector<int>& ans)
{
    vector<int> v(a, 1);
    v[0] = b;
    int m = n - (a + b - 1);
    if(m < 0)
        return false;

    for(int i=1; i<a; ++i){
        int x = min(b - 1, m);
        v[i] += x;
        m -= x;
    }
    if(m > 0)
        return false;

    ans.resize(n);
    for(int i=0; i<n; ++i)
        ans[i] = i + 1;

    int k = 0;
    for(int i=0; i<a; ++i){
        reverse(ans.begin() + k, ans.begin() + k + v[i]);
        k += v[i];
    }
    return true;
}

