vector<long long> lis_and_lds(long long n, long long a, long long b) {
    assert(a + b <= n + 1 && n <= a * b);
    vector<long long> res;
    for (int i = b-1; i >= 0; --i) res.push_back(i);
    if (a == 1) return res;

    long long rem = n - b;
    long long width = rem / (a-1);
    long long r = rem % (a-1);

    for (int i = 0; i < r; ++i) {
        int sz = (int)res.size();
        for (int j = 0; j < width + 1; ++j) {
            res.push_back(sz + width - j);
        }
    }
    for (int i = 0; i < a - 1 - r; ++i) {
        int sz = (int)res.size();
        for (int j = 0; j < width; ++j) {
            res.push_back(sz + width - 1 - j);
        }
    }

    return res;
}

int main() {
    ll n, a, b;
    cin >> n >> a >> b;
    if (a + b > n + 1 || n > a * b) {
        cout << "-1\n";
        return 0;
    }
    auto ans = lis_and_lds(n, a, b);
    rep(i, n) cout << ans[i] + 1 << (i == n-1 ? '\n' : ' ');
}

