  { puts("-1"); return 0; }

  ll p = A*B;
  for( int i = A-1; i < A*B; i += A )
  {
    rep( j, A )
      vs.push_back( p-(A-1-j) );

    p -= A;
  }

  //show(vs);

  std::vector<ll> ans;

  rep( i, A )
    ans.push_back( N-(A-1-i) );

  ll rest = N-(A+B-1);
  p = N-A;
  for( int i = A; i < A*B; i += A )
  {
    ll cnt = std::min( A, rest+1 );

    rep( j, cnt )
      ans.push_back( p-cnt+1+j );

    p -= cnt;
    rest -= cnt-1;
  }

  show(ans);

  return 0;
}

