int arr[N];
deque<int> follow[N];
int main() {
	ios::sync_with_stdio(false);cin.tie(0);cout.tie(0);
	cin>>n>>a>>b;
	if (a+b>n+2) {
		cout<<"-1\n";
		return 0;
	}
	if (b==1) {
		if (a==n) {
			for(int i=1;i<=n;i++) cout<<i<<" \n"[i==n];
		} else {
			cout<<"-1\n";
		}
		return 0;
	}
	if ((n-a+b-1)/(b-1)>a) {
		cout<<"-1\n";
		return 0;
	}
	int tms=(n-a)/(b-1),pos=1,pos1=n-a+1;
	while (tms--) {
		for(int i=1;i<b;i++) follow[pos1].push_front(pos++);
		pos1++;
	}
	int rem=(n-a)%(b-1);
	for(int i=0;i<rem;i++) follow[pos1].push_back(pos++);
	pos=0;
	for(int i=1;i<=n;i++) {
		if (i>=n-a+1) arr[++pos]=i;
		while (!follow[i].empty()) {
			arr[++pos]=follow[i].front();follow[i].pop_front();
		}
	}
	for(int i=1;i<=n;i++) cout<<arr[i]<<" \n"[i==n];
	return 0;
}

