void solve()
{
    if (N < A + B - 1) {
        cout << -1 << endl;
        return;
    }

    if (A > B) {
        for (int i = 1; i < A; ++i) {
            cout << i << ' ';
        }

        for (int i = 0; i < B; ++i) {
            cout << N - i << ' ';
        }

        for (int i = A, iend = N - B + 1; i < iend; ++i) {
            cout << i << ' ';
        }
    } else {
        for (int i = 1; i < B; ++i) {
            cout << N - i + 1 << ' ';
        }

        for (int i = 0; i < A; ++i) {
            cout << i+1 << ' ';
        }

        for (int i = A, iend = N - B + 1; i < iend; ++i) {
            cout << i+1 << ' ';
        }
    }

    cout << endl;
}

