int N, A, B;
int p, rest;

inline void process (int num)
{
	--rest;
	for (int i = p - num + 1; i <= p; ++i) printf("%d ", i);
	p -= num;
}

inline void Solve ()
{
	if (A + B > N + 1) { puts("-1"); exit(0); }
	if ((LL) A * B < N) { puts("-1"); exit(0); }
	p = N, rest = B;
	process (A);
	if (B == 1) return ;
	for (int i = 1; i <= B - 1; ++i)
	{
		int ave = p / rest;
		if (rest == 1) process (p);
		else process (ave);
	}
	puts("");
}

