// Strict LIS
ll LISa(vector<ll> a) {
    // dp[i][len] = [0, i]のから取れる長さlenのLISを想定した時、その最後の要素として考えられる最小の値
    // iはdpテーブルを使い回している
    vll dp; dp.reserve(100000);
    rep(i, a.size()) {
        auto it = lower_bound(all(dp), a[i]);
        if (it == dp.end()) 
            dp.pb(a[i]);
        else
            *it = a[i];
    }
    return dp.size();
}
// Strict LIS
ll LISd(vector<ll> b) {
    vector<ll> a = b;
    rep(i, a.size()) {
        a[i] *= -1;
    }
    // dp[i][len] = [0, i]のから取れる長さlenのLISを想定した時、その最後の要素として考えられる最小の値
    // iはdpテーブルを使い回している
    vll dp; dp.reserve(100000);
    rep(i, a.size()) {
        auto it = lower_bound(all(dp), a[i]);
        if (it == dp.end()) 
            dp.pb(a[i]);
        else
            *it = a[i];
    }
    return dp.size();
}

vvll used;
void brutal(ll n) {
    used=vvll(n+1,vll(n+1));
    vll id(n);
    map<P, vll> memo;
    rep(i, n) {
        id[i] = 1+i;
    }
    do {
        chmax(memo[P(LISa(id),LISd(id))], id);
    } while (next_permutation(all(id)));
    for (auto x : memo) {
        used[x.fi.fi][x.fi.se] = 1;
        if (x.fi.fi >= x.fi.se)
            cout << x.fi << " " << x.se << endl;
    }
