		for(int i=1;i<n;++i) printf("%d ",n-i+1);
		printf("%d\n",1);
		return 0;
	}
	int J=n,L,R;
	for(int i=A;i>=1;--i) ans[i]=J,J--;
	L=B,R=n-A,J=B-1;
	for(int i=A+1;i<=A+B-1;++i) ans[i]=J,J--;

	A--,B--;
	int l=1,r=n;
	while(l<r)
	{
		int mid=(l+r)>>1;
		int s=(R-L+1)/mid;
		if((R-L+1)%mid!=0) s++;
		if(s<=B) r=mid;
		else l=mid+1;
	}
	if(l>A) {printf("-1\n");return 0;}
	J=A+B+2;
	while(R-L+1>=A)
	{
		int k=R-l+1;
		for(int i=J;i<=J+l-1;++i) ans[i]=k++;
		J=J+l,R-=l;
	}
	for(int i=J;i<=n;++i) ans[i]=L++;
	for(int i=1;i<n;++i) printf("%d ",ans[i]);
