void gao(int l,int r,int c){
    static int s[N],m;
    m=0;
    rep(i,r-c,r)s[m++]=ans[i];
    for(int i=r-c+1,j=r-1;i>=l;--i,--j)
        ans[j]=ans[i];
    int i=l;
    while(m>0)ans[i++]=s[--m];
}
int main(){
    int n,a,b;cin>>n>>a>>b;
    int m=0,top=0;
    for(int i=n+1,t;i>1;i=t){
        t=max(i-a,1);
        int tm=m;
        rep(j,t,i)ans[m++]=j;
        stk[top++]={tm,m};
        --b;
    }
    while(b>0 && top>1){
        int l=stk[top-1].y-stk[top-1].x;
        if(b>l-1){
            gao(stk[top-1].x,stk[top-1].y,l-1);
            b-=l-1;
        }else{
            gao(stk[top-1].x,stk[top-1].y,b);
            b=0;
        }
    }
    if(b!=0)puts("-1");
    else rep(i,0,n)printf("%d%c",ans[i]," \n"[i==n-1]);
    return 0;
}

