	ll n, a, b;
	cin >> n >> a >> b;
	if (a + b > n + 1 || a * b < n) {
		cout << -1;
		return 0;
	}
	Array ans;
	ll now = n - a + 1;
	REP(i, a) {
		ans.push_back(now);
		now++;
	}
	n -= a;
	if (b != 1) {
		ll step = n / (b - 1);
		ll cnt = n % (b - 1);
		REP(i, cnt) {
			now = n - step;
			for (int j = now; j < now + step + 1; j++) {
				ans.push_back(j);
			}
			n -= step + 1;
		}
		REP(i, b - 1 - cnt) {
			now = n - step + 1;
			for (int j = now; j < now + step; j++) {
				ans.push_back(j);
			}
			n -= step;
		}
	}
	REP(i, ans.size()) {
		cout << ans[i] << ' ';
	}


	return 0;
}

