void solve() {
  int N, A, B;
  cin >> N >> A >> B;
  if (N - A + 1 < B || (N + A - 1) / A > B) no();
  if (B == 1) {
    if (A != N) no();
    vi32 ans(N);
    reps(i, N) ans[i - 1] = i;
    cout << ans << '\n';
    return;
  }
  if (A == 1) {
    if (B != N) no();
    vi32 ans(N);
    rep(i, N) ans[i] = N - i;
    cout << ans << '\n';
    return;
  }
  vi32 ans(N);
  {
    int j = 0;
    for (int i = N - A + 1; i <= N; i++) {
      ans[j++] = i;
    }
    function<void(int, int, int)> crt = [&](int j, int R, int G) {
      if (R == G) {
        for (int i = R; i >= 1; i--) {
          ans[j++] = i;
        }
        return;
      }
      if (R - A < G - 1) {
        for (int i = G; i <= R; i++) {
          ans[j++] = i;
        }
        crt(j, G - 1, G - 1);
      } else {
        for (int i = R - A + 1; i <= R; i++) {
          ans[j++] = i;
        }
        crt(j, R - A, G - 1);
      }
    };
    crt(j, N - A, B - 1);
    cout << ans << '\n';
  }
}

