vector<long> ans;
long n, a, b;

void test() {
    vector<int> dp = vector<int>(ans.size());
    int l = 0;
    REP(i,ans.size()) {
        dp[i] = 1;
        for (int j = 0; j < i; j++) {
            if (ans[j] < ans[i]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
        l = max(l, dp[i]);
    }
    if (a != l) {
        cout << "invalid LIS" << endl;
        exit(-1);
    }

    vector<long> ians = vector<long>(ans);
    reverse(ians.begin(), ians.end());

    l = 0;
    REP(i,ians.size()) {
        dp[i] = 1;
        for (int j = 0; j < i; j++) {
            if (ians[j] < ians[i]) {
                dp[i] = max(dp[i], dp[j] + 1);
            }
        }
        l = max(l, dp[i]);
    }
    if (b != l) {
        cout << "invalid LDS" << endl;
        exit(-1);
    }

    sort(ans.begin(), ans.end());
    REP(i,n) {
        if (ans[i] != i + 1) {
            cout << "invalid SEQ" << endl;
            exit(-1);
        }
    }
}

