int main() {
    cin >> n >> a >> b;

    if (!(n <= a + b && a + b <= n + 1)) {
        cout << -1 << endl;
        return 0;
    }

    if (n == a + b) {
        if (a == 1 || b == 1) {
            cout << -1 << endl;
            return 0;
        }

        ans.push_back(n - 1);
        REP(i,a-1) {
            ans.push_back(i + 1);
        }

        ans.push_back(n);
        REP(i,b-2) {
            ans.push_back(n - 2 - i);
        }
        ans.push_back(n - b);

        test();
        print_vec(ans);
        return 0;
    }

    if (a == 1) {
        REP(i,n-1) cout << n - i << " ";
