vector<int> solve(int N, int A, int B)
{
    vector<int> L;
    if (B == 1) {
        if (N != A) return {-1};
        L = { N };
    } else {
        L = { A };
        int q = (N - A) / (B - 1);
        int r = (N - A) % (B - 1);
        if (q == 0) return {-1};
        if (q + (r != 0) > A) return {-1};
        for (int i = 0; i < r; i++) L.push_back(q + 1);
        for (int i = r; i < B-1; i++) L.push_back(q);
    }
    vector<int> ans;
    for (int i = 0; i < L.size(); i++) {
        for (int j = 0; j < L[i]; j++) {
            ans.push_back(N - L[i] + 1 + j);
        }
        N -= L[i];
    }
    return ans;
}
