// import here

void output(vector<int>& res){
    for(int j = 0; j < res.size(); ++j){
        cout << res[j];
        if(j + 1 >= res.size()){
            cout << endl;
        }else{
            cout << " ";
        }
    }
}

bool solve(int n, int a, int b, vector<int>& res){
    if(n == 1 && a == 1 && b == 1){
        res.clear();
        res.push_back(1);
        return true;
    }
    for(int n_block = 1; b * n_block <= n; ++n_block){
        LL rest = n - n_block * b;
        //cerr << n_block + max<LL>(1, rest + 1 - b) << ", " << a << ", " << n_block + rest << endl;
        if(n_block + max<LL>(1, rest + 1 - b) <= a && a <= n_block + rest){
            LL rest_up = a - n_block - 1;
            LL rest_down = rest - rest_up;
            res.clear();
            for(int i = 0; i < n_block; ++i){
                for(int j = 0; j < b; ++j){
                    res.push_back(b-j + i*b);
                }
            }
            for(int i = 0; i < rest_down; ++i){
                //cerr << "down: " << n - rest_up - i << endl;
                res.push_back(n - rest_up - i);
            }
            for(int i = 0; i < rest_up; ++i){
                //cerr << "up: " << n - rest_up + i + 1 << endl;
                res.push_back(n - rest_up + i + 1);
            }
            return true;
        }
    }
    return false;
}

int main(){
    LL n, a, b;
    cin >> n >> a >> b;
    vector<int> res;
    if(solve(n, a, b, res)){
        output(res);
        return 0;
    }
    if(solve(n, b, a, res)){
        for(int i = 0; i < n; ++i){
            res[i] = n+1 - res[i];
        }
        output(res);
        return 0;
    }
    cout << -1 << endl;

    return 0;
}

