vector<int> lis_and_lds(int n, int a, int b) {
    assert(a + b <= n + 1 && n <= a * b);
    vector<int> res;
    for (int i = b-1; i >= 0; --i) res.push_back(i);
    if (a == 1) return res;

    int rem = n - b;
    int p = rem / (a-1);
    int r = rem % (a-1);

    int c = r;
    int d = a-1-r;

    for (int i = 0; i < c; ++i) {
        int sz = (int)res.size();
        for (int j = 0; j < p+1; ++j) {
            res.push_back(sz + p - j);
        }
    }
    for (int i = 0; i < d; ++i) {
        int sz = (int)res.size();
        for (int j = 0; j < p; ++j) {
            res.push_back(sz + p-1 - j);
        }
    }

    return res;
}

