    vector <int> ans = solve(n, a, b);
    if(ans.size() == 0){
        ans = solve(n, b, a);
        for(auto &i : ans){
            i = n - i + 1;
        }
    }
    if(ans.size() == 0) finish(-1);
    for(auto &i : ans) cout << i << " ";
    cout << endl;
}

