int main(){
    cin>>N>>A>>B;
	if(A+B-1>N){
		cout<<-1;return 0;
	}
    if(A==1){
    	if(B==N){
			for(ll i=N;i>=1;i--){
				cout<<i<<" ";
			}
			return 0;
		}
		cout<<-1;
		return 0;
    }
	if(B==1){
		if(A==N){
			for(ll i=1;i<=N;i++){
				cout<<i<<" ";
			}
			return 0;
		}
		cout<<-1;
		return 0;
	}
	if(A>=B){
		for(ll i=N-A+1;i<=N;i++)ans.push_back(i);
		for(ll i=B-1  ;i>=1;i--)ans.push_back(i);
		if( (N-A+1-B)/(A-1)>=B ){
			cout<<-1;return 0;
		}
		ll cnt=0;
		ll now=N-A;
		while(cnt< N-A+1-B){
			for(ll i=max(B,now-(A-2));i<=now;i++){
				ans.push_back(i);
				cnt++;
				if(cnt==N-A+1-B )break;
			}
			now-=(A-1);
		}
		for(auto x:ans)cout<<x<<" ";
	}else{
		for(ll i=B;i>=1;i--)ans.push_back(i);
		for(ll i=N-A+2;i<=N;i++)ans.push_back(i);
		if((N-A+2-(B+1))/(B-1)>=A)return 0;
		ll cnt=0;
		ll now=B+1;
		while(cnt< N-A+2-(B+1) ){
			for(ll i=min(now+B-2,N-A+1);i>=now;i--){
				ans.push_back(i);
				cnt++;
				if(cnt==N-A+2-(B+1))break;
			}
			now+=B-1;
		}
		for(auto x:ans)cout<<x<<" ";
	}
    return 0;
}

