    while(ans.size() < n)
    {
        int y = vec.size();
        if(l == 0)
        {
            for(int j = min(l + a - 1, y - 1 ); j >= l; j--)
            {
                if(u[vec[j]] == 0)
                    ans.push_back(vec[j]);
                u[vec[j]] = 1;
            }
