{
  ios_base::sync_with_stdio(false);
  cin.tie(0);
  ll n, a, b;
  cin >> n >> a >> b;
  if(a + b - 1 > n || n > a * b){
    cout << -1 << endl;
    return 0;
  }
  vector<int> res;
  for(int i = b; i >= 1; i--)res.pb(i);
  int curr = b + 1;
  int now = 0;
  //ll rem = n - b - (n - a - 1) / (b - 1);
  ll st = n - b - a + 1;
  for(int i = 0; i < a - 1; i++){
    int end;
    if(now + b - 1 <= st){
      end = curr + b - 1;
      now += b - 1;
    }else{
      if(st > now){
        end = curr + st - now;
      }else{
        end = curr;
      }
    }
    for(int i = end; i >= curr; i--){
      res.pb(i);
    }
    curr = end + 1;
  }
  cout << res << endl;
  return 0;
}

