      for (int j = 0; j < a && x; ++j) {
        v[i].push_back(x--);
        if (x == y) break;
      }
      --y;
    }

    // for (int i = 0; i < b; ++i) cout << v[i] << endl;

    if (v[b - 1].empty()) {
      cout << -1 << endl;
      continue;
    }
    if (v[0].size() != a) {
      cout << -1 << endl;
      continue;
    }

    vec<int> u;
    for (int i = 0; i < b; ++i) {
      while (v[i].size()) {
        u.push_back(v[i].back());
        v[i].pop_back();
      }
    }

    if (u.size() != n) {
      cout << -1 << endl;
      continue;
    }

    for (int i = 0; i < u.size(); ++i) {
      if (i) cout << ' ';
      cout << u[i];
    }
    cout << endl;
  }
  return 0;
}

