    cout << fixed << setprecision(20);

    int N, A, B;
    cin >> N >> A >> B;

    vi p(N);
    iota(all(p), 0);

    if (N == A + B) {
        reverse(p.begin(), p.begin() + A);
    } else if (N + 1 == A + B) {
        vi a(N);
        rep(i, A) {
            a[i + 1] = 1;
            p[i + 1] = i;
