        int n = N - B;
        for(int i=A-1;i>=1;--i) {
            L.push_back(min(B, n / i + n % i));
            n -= L.back();
        }
        if (n > 0) {
            cout << -1 << endl;
            exit(0);
        }
        int cur = 0;
        rep(i, sz(L)) {
            reverse(p.begin() + cur, p.begin() + cur + L[i]);
            cur += L[i];
        }
    } else {
        cout << -1 << endl;
        exit(0);
    }

    rep(i, N) {
        cout << p[i]+1 << (i != N - 1 ? ' ' : '\n');
    }
}

