            l += a - 1, r += a - 1;
        }
        //  ///
    } else if (ceil(N, a) == b) {
        iota(all(A), 1);
        reverse(all(A));
        int l = 0, r = a;
        while (l < N) {
            auto lb = A.begin() + l;
            auto rb = A.begin() + min(r, N);
            reverse(lb, rb);
            l += a, r += a;
        }
        //  /\\\  //
    } else if (ceil(N - a, b - 1) <= a) {
        rer(i, a - 1) A.pb(N - i);
        rep(i, N - a) A.pb(i + 1);
        int l = a, r = a + b - 1;
        while (l < N) {
            auto lb = A.begin() + l;
            auto rb = A.begin() + min(r, N);
            reverse(lb, rb);
            l += b - 1, r += b - 1;
        }
        //  /\\\     //
    } else if (ceil(N, b) == a) {
        rep(i, N) A.pb(i + 1);
        int l = a, r = a + b;
        while (l < N) {
            auto lb = A.begin() + l;
            auto rb = A.begin() + min(r, N);
            reverse(lb, rb);
            l += b, r += b;
        }
        //  \\\\   //
    } else {
        fin(-1);
    }
    out(A);

    return 0;
}

