const int MAX_N = 300005;
int N, A, B, p[MAX_N];

int main() {
  scanf("%d%d%d", &N, &A, &B);
  if (A + B - 1 > N) {
    puts("-1");
    return 0;
  }
  if (A > B) {
    int r = N, l = 1, pos = 0;
    for (int i = 1; i <= A; ++i)
      p[++pos] = N - A + i;
    for (int i = 1; i < B; ++i)
      p[++pos] = B - i;

    r = N - A, l = B;
    int num1 = 1, num2 = 1;
    while (l <= r) {
      if (num1 >= B && num2 >= A) {
	puts("-1");
	return 0;
      }
      int len = max(0, min(A - num2, r - l + 1));
      for (int i = 1; i <= len; ++i)
	p[++pos] = r - len + i;
      r -= len, num1++;
      len = max(0, min(B - num1, r - l + 1));
      for (int i = 1; i <= len; ++i)
	p[++pos] = l + len - i;
      l += len, num2++;
    }
    if (num1 > B || num2 > A) {
      puts("-1");
      return 0;
    }
  } else {
    int r = N, l = 1, pos = 0;
    for (int i = 1; i <= B; ++i)
      p[++pos] = B - i + 1;
    for (int i = 1; i < A; ++i)
      p[++pos] = N - A + i + 1;

    r = N - A + 1, l = B + 1;
    int num1 = 1, num2 = 1;
    while (l <= r) {
      if (num1 >= B && num2 >= A) {
	puts("-1");
	return 0;
      }
      int len;
      len = max(0, min(B - num1, r - l + 1));
      for (int i = 1; i <= len; ++i)
	p[++pos] = l + len - i;

      l += len, num2++;
      len = max(0, min(A - num2, r - l + 1));
      for (int i = 1; i <= len; ++i)
	p[++pos] = r - len + i;
      r -= len, num1++;
    }
    if (num1 > B || num2 > A) {
      puts("-1");
      return 0;
    }
  }
  for (int i = 1; i <= N; ++i)
    printf("%d ", p[i]);
  puts("");
  return 0;
}

