void verif()
{
    int i, j;
    for(i = 1; i <= n; i ++)
        dp[i][0] = dp[i][1] = 0;

    int na = 0;
    int nb = 0;
    for(i = 1; i <= n; i ++)
    {
        dp[i][0] = 1;

        for(j = 1; j < i; j ++)
        {
            if(stk[j] < stk[i])
                dp[i][0] = max(dp[i][0], dp[j][0] + 1);
        }

        na = max(na, dp[i][0]);
    }

    for(i = 1; i <= n; i ++)
    {
        dp[i][1] = 1;
        for(j = 1; j < i; j ++)
        {
            if(stk[j] > stk[i])
                dp[i][1] = max(dp[i][1], dp[j][1] + 1);
        }

        nb = max(nb, dp[i][1]);
    }

//    cout << na << " " << nb << "\n";

    if(a != na || b != nb)
        return;

    cout << "DA\n";

    for(i = 1; i <= n; i ++)
        cout << stk[i] << " ";
    cout << "\n";

    exit(0);
}

void bkt(int k)
{
    if(k == n + 1)
    {
        verif();

        return;
    }

    int i;
    for(i = 1; i <= n; i ++)
    {
        if(ap[i] == 0)
        {
            ap[i] = 1;
            stk[k] = i;
            bkt(k + 1);
            ap[i] = 0;
        }
    }
}

void c1()
{
    int i;
    int grup = 1;
    for(i = 1; i <= n; i ++)
    {
        int mn = (n - b) / i + 1;
        int mx = n - b - i + 1;

        //cout << i << " " << mn << " " << mx << " " << a << "\n";
        if(a >= mn && a <= mx)
        {
            grup = i;

            break;
        }
    }

    if(grup > b)
    {
        out();
    }

    int cate = 0;
    for(i = 1; i * grup <= n; i ++)
    {
        if(n - b - i * grup + i + 1 == a)
        {
            cate = i;
            break;
        }
    }

    if(cate == 0)
        out();

    for(i = 1; i <= n - b - cate * grup; i ++)
        cout << i << " ";

    int j;
    int last = n - b - cate * grup;
    for(i = 1; i <= cate; i ++)
    {
        for(j = last + grup; j >= last + 1; j --)
            cout << j << " ";

        last += grup;
    }

    for(i = n; i >= n - b + 1; i --)
        cout << i << " ";
}

