void solve(void)
{
  //https://kmjp.hatenablog.jp/entry/2018/03/11/1100
  int n,a,b;
  cin>>n>>a>>b;
  if(a + b > n + 1)
  {
    cout<<-1<<endl;
    return;
  }
  if(a*b < n)
  {
    cout<<-1<<endl;
    return;
  }
  vector<int> vec;
  int s = n - a;
  int cur = n;
  for (int i = 0; i < a; i++)
  {
    int num = min(b-1,s) + 1;
    s -= num -1;
    for (int j = 0; j < num; j++)
    {
      vec.push_back(cur - num + 1 +j);
    }
      cur -= num;  
  }
  reverse(ALL(vec));
  for (int i = 0; i < vec.size(); i++)
  {
      if(i != 0)cout<<char(32);
      cout<<vec[i];
  }
  cout<<endl;

  return;
}


