		int k=min(a-1,m);
		rep(j,k+1) ans[idx++]=num+j-k;
		num-=k+1;
		m-=k;
	}

	rep(i,n) printf("%d%c",ans[i],i<n-1?' ':'\n');

	return 0;
}

