int main()
{
	cin.tie( 0 );
	ios::sync_with_stdio( false );
	cout << setprecision( 12 ) << fixed;

	IN( LL, N, A, B );

	if ( A + B > N + 1 || A * B < N )
	{
		cout << -1 << endl;
		return 0;
	}

	VI bucukets( A, B );
	int remaining = A * B;
	REP( i, 1, A )
	{
		if ( remaining <= N )
		{
			continue;
		}

		if ( remaining - N >= B - 1 )
		{
			bucukets[i] -= B - 1;
			remaining -= B - 1;
			continue;
		}
		else
		{
			while ( remaining > N && bucukets[i] > 1 )
			{
				--bucukets[i];
				--remaining;
			}
		}
	}

	VI res;
	int processed = 0;

	FOR( a, bucukets )
	{
		VI row( a );
		iota( row.rbegin(), row.rend(), processed + 1 );
		copy( ALL( row ), BI( res ) );
		processed += a;
	}

	cout << res << endl;

	return 0;
}

