int main() {
  ios::sync_with_stdio(false);
  int n, a, b;
  cin >> n >> a >> b;
  if (n < a + b - 1 || a * b < n) {
    cout << -1 << endl;
    return 0;
  }
  VI vs(a, 1);
  int m = n - a;
  FOR(v, vs) {
    if (m <= 0) {
      break;
    }
    int d = min(m, b - v);
    m -= d;
    v += d;
  }
  int i = 0;
  FOR(v, vs) {
    REP(j,0,v) {
      cout << i + v - j << " ";
    }
    i += v;
  }
  cout << endl;

  return 0;
}

