		vec.push_back(take);
		sum -= take;
		--a;
	}

	int r = n - b;
	while(vec.size()) {
		int sz = vec.back();
		vec.pop_back();
		for (int i = r - sz + 1; i <= r; ++i) p[i] = r + r - sz + 1 - i;
		r -= sz;
	}

	for (int i = 1; i <= n; ++i) cout << p[i] << ' '; cout << endl;
}

