template<typename T>
class compress_fn_t {
public:
  void add(T x) {
    if (! map_.count(x))
      map_[x] = 0;
  };

public:
  void clear() {
    map_.clear();
  };

public:
  std::pair<std::map<T, int>, std::vector<T>> get() {
    int size = map_.size(), i = 0;

    std::pair<std::map<T, int>, std::vector<T>> pair;

    pair.second.resize(size);

    for (auto& kv : map_) {
      kv.second = i;

      pair.second[i] = kv.first;

      i ++;
    }

    pair.first = map_;

    return std::move(pair);
  };

private:
  std::map<T, int> map_;
};


