    return 0;
  }

  std::vector<std::pair<int, int>> a;

  bool used[333333] = {0};

  int i;

  long long j;

  for (i = 0, j = A * B - A + 1; j >= 1; i ++, j -= A) {
    if (i == 0) {
      for (int k = 0; k < A; k ++) {
        a.emplace_back(i, j + k);

        if (j + k <= N)
          used[j + k] = true;
      }
    }
    else {
      a.emplace_back(i, j);

      if (j <= N)
        used[j] = true;
    }
  }

  for (const auto& pair : a)
    std::cerr << pair.second << ',' << pair.first << ' ';
  std::cerr << std::endl;

  for (int i = 1; a.size() < N; i ++)
    if (! used[i])
      a.emplace_back(B - (i - 1) / A - 1, i);

  std::sort(ALL(a));

  for (const auto& pair : a)
    std::cerr << pair.second << ',' << pair.first << ' ';
  std::cerr << std::endl;

  compress_fn_t<int> fn;

  for (const auto& pair : a)
