void make_sequence(int N, int A, int B, int shift)
{
	if (A*B == N)
	{
		for (int i = 0; i < A - 1; ++i)
		{
			for (int j = B; j > 0; --j)
			{
				std::cout << i * B + j + shift << " ";
			}
		}
		for (int j = B; j > 1; --j)
		{
			std::cout << (A - 1)*B + j + shift << " ";
		}
		std::cout << (A - 1)*B + 1 + shift;
	}
	else if (N / B == A - 1)
	{
		for (int i = 0; i < A - 1; ++i)
		{
			for (int j = B; j > 0; --j)
			{
				std::cout << i * B + j + shift << " ";
			}
		}
		for (int j = N; j > B*(A - 1) + 1; --j)
		{
			std::cout << j + shift << " ";
		}
		std::cout << B * (A - 1) + 1 + shift;
	}
	else if (B > 2)
	{
		std::cout << shift + N << " ";
		make_sequence(N - 1, A, B - 1, shift);
	}
	else
	{
		std::cout << shift + 1 << " ";
		make_sequence(N - 1, A - 1, B, shift + 1);
	}
}

void Main()
{
	int N, A, B;
	std::cin >> N >> A >> B;
	if (A + B >= N + 2)
	{
		std::cout << -1 << std::endl;
		return;
	}
	if (A*B < N)
	{
		std::cout << -1 << std::endl;
		return;
	}
	make_sequence(N, A, B, 0);
	std::cout << std::endl;
}

