    ll num = (n-b)/(a-1);
    ll rem = (n-b)%(a-1);
    rep(i,a-2)rep(j,num)ans.push_back(i*num+b+1-j);
    rep(i,a-1+rem)ans.push_back(n-i);
    rep(i,n)cout << ans[i] << " \n"[i == n -1];
}

