int getLIS(vector<int> a){
	vector<int> dp(a.size(),INF);
	for(int i = 0; i < a.size(); i++){
		*lower_bound(ALL(dp),a[i]) = a[i];
	}
	return lower_bound(ALL(dp),INF)-dp.begin();
}

int getLISr(vector<int> a){
	REP(i, SZ(a)) a[i] = -a[i];
	vector<int> dp(a.size(),INF);
	for(int i = 0; i < a.size(); i++){
		*lower_bound(ALL(dp),a[i]) = a[i];
	}
	return lower_bound(ALL(dp),INF)-dp.begin();
}


