class bint{
    public:
    constexpr static int mx=36;
    constexpr static int base=10;
    int v[mx]={};
    bint(string s){
        for(int i=0;i<(int)s.size();i++)v[i]=s[s.size()-i-1]-'0';
    }
    bint(long long x=0){
        int idx=0;
        while(x){
            v[idx++]=x%10;
            x/=10;
        }
    }
    string to_string(){
        string t;
        const bint tmp=(v[mx-1]==9)?inv():bint(*this);
        if(v[mx-1]==9)t="-";
        bool f=0;
        for(int i=mx-2;i>=0;i--){
            if(tmp.v[i])f=1;
            if(f)t+=(tmp.v[i]+'0');
        }
        if(t==""||t=="-")return "0";
        else return t;
    }
    bint operator+(const bint& rhs) const noexcept {
        return bint(*this) += rhs;
    }
    bint operator-(const bint& rhs) const noexcept {
        return bint(*this) -= rhs;
    }
    bint operator-() const noexcept {
        return bint(*this).inv();
    }
    bint operator*(const bint& rhs) const noexcept {
        return bint(*this) *= rhs;
    }
    bint operator/(const bint& rhs) const noexcept {
        return bint(*this) /= rhs;
    }
    bint &operator+=(const bint& t) noexcept {
        plus(t);
        return *this;
    }
    bint &operator-=(const bint& t) noexcept {
        plus(t.inv());
        return *this;
    }
    bint &operator*=(const bint& t) noexcept {
        bint ret;
        for(int i=0;i<mx;i++)for(int j=0;j<mx-i;j++){
            ret.v[i+j]+=v[i]*t.v[j];
        }
        for(int i=0;i<mx-1;i++){
            v[i+1]+=v[i]%10;
            v[i]/=10;
        }
        return *this=ret;
    }
    bint &operator/=(bint rhs) noexcept {
        return *this;
    }
    bint &operator=(bint rhs) noexcept {
        memcpy(v,rhs.v,mx*sizeof(int));
        return *this;
    }
    void plus(const bint& t){
        for(int i=0;i<mx;i++){
            v[i]+=t.v[i];
            if(i!=mx-1)v[i+1]+=(v[i]>=10);
            if(v[i]>=10)v[i]-=10;
        }
    }
    bint inv()const{
        bint res;
        bool b=0;
        for(int i=0;i<mx;i++){
            if(b){
                res.v[i]=9-v[i];
            }else{
                if(v[i]){
                    b=1;
                    res.v[i]=10-v[i];
                }else{
                    res.v[i]=0;
                }
            }
        }
        return res;
    }
};

