// 繰り返し二乗法
ll power(ll a, ll b){
    if(a==1)return a;
    // if(a==0)re
    ll res=1;
    while(b>0){
        if(b&1) res=res*a%MOD;
        a=a*a%MOD;
        b>>=1;
    }
    return res;
}

const int MAX=2100000;

ll fact[MAX], fact_inv[MAX];

void init_fact(ll n){
    fact[0]=1;
    // 階乗の計算
    for(ll i=0; i<n; i++) fact[i+1]=fact[i]*(i+1)%MOD;
    fact_inv[n]=power(fact[n], MOD-2);
    // 逆元の計算
    for(ll i=n-1;i>=0;i--) fact_inv[i]=fact_inv[i+1]*(i+1)%MOD;
}

ll comb(ll n, ll r){
    return (fact[n]*fact_inv[r])%MOD*fact_inv[n-r]%MOD;
}

ll perm(ll n, ll r){
    return (fact[n]*fact_inv[n-r])%MOD;
}

ll LIS(vint &v){
    vint L;
    L.push_back(v.front());
    repf(i,1,v.size()){
        auto it = lower_bound(ALL(L), v[i]);
        if(it == L.end()){
            L.push_back(v[i]);
        }else{
            L[it - L.begin()] = v[i];
        }
    }
    return L.size();
}

ll LDS(vint &v){
    vint tmp(v.size());
    rep(i,v.size()) tmp[i] = -v[i];
    return LIS(tmp);
}


