vector<int> construct(int n, int a, int b) {
	assert(a + b <= n + 1 && ((ll)a) * b >= n);
	vector<int> res(n, 0);
	int ptr = 0;
	for (int i = b; i > 0; --i)
		res[ptr++] = i;
	if (ptr == n)
		return res;
	vector<int> bsz(a - 1, (n - b) / (a - 1));
	for (int i = 0; i < (n - b) % (a - 1); ++i)
		++bsz[a - 2 - i];
	int bmx = b;
	for (int i = 0; i < bsz.size(); ++i) {
		bmx += bsz[i];
		int nx = bmx;
		for (int j = 0; j < bsz[i]; ++j)
			res[ptr++] = nx--;
	}
	return res;
}

