int ans[SIZE];

bool solve(int n, int a, int b){

  if(n + 1 < a + b){
    return false;
  }

  int t = n;
  int used[SIZE] = {};


  for(int i=0;i<n-b;){
    b--;
    int rest = (n-b) - i;
    t -= min(a,rest);
    for(int j=0;j<min(a,rest);j++){
      int q = t + 1 + j;
      ans[i] = q;
      used[q] = true;
      i++;
    }
  }

  if(t < 0 || b < 0){
    return false;
  }

  int k = n;

  for(int i=n-b;i<n;i++){
    while(used[k]) k--;
    ans[i] = k;
    used[k] = true;
  }

  return true;
}

