int input() {
	if (scanf("%d %d %d", &n, &a, &b) < 0) return 0;
	return 1;
}

void init() {
}

long solve() {
	if (a+b-1>n || a<=0 || b<=0) return 0;
	int t=n, s=1, p=0;
	while (p<n) {
		if (a<0) return 0;
		int q = p;
		for (int i=0; i<a && p<n; i++) {
			r[p++] = t--;
		}
		reverse(r+q, r+p);
		a--;
		if (p==n) break;

		b--;
		if (b<0) return 0;
		q = p;
		for (int i=0; i<b && p<n; i++) {
			r[p++] = s++;
		}
		reverse(r+q, r+p);
	}
	return 1;
}

void output(long ans) {
	if (!ans) {
		printf("-1\n");
		return;
	}
	for (int i=0; i<n; i++) printf("%d ", r[i]);
	printf("\n");
}

