vector<ll> solve(){
    ll N,A,B; cin >> N >> A >> B;
    if(A + B > N + 1) return vector<ll>{-1};
    if(A*B < N) return vector<ll>{-1};
    vector<ll> res;
    ll tA = N - A;
    ll now = N;
    for(int i = 0; i < A;i++){
        ll num = min(B-1,tA)+1;
        tA -= num - 1;
        for(int j = 0; j < num;j++) res.push_back(now-num+1+j);
        now -= num;
    }
    reverse(res.begin(),res.end());
    return res;
}
