void solve(int l, int r, int a, int b) {
	if (a < 1 || b < 1) {
		cout << -1 << endl;
		exit(0);
	}
	if (b > a) {
		for (int i = r - a; i < r; i++) {
			ans.push_back(p[i]);
			if (ans.size() >= n) {
				return;
			}
		}
		for (int i = l + (b - 1) - 1; i >= 0; i--) {
			ans.push_back(p[i]);
			if (ans.size() >= n) {
				return;
			}
		}
		solve(l + b - 1, r - a, a - 1, b - 1);
	}
	else {
		for (int i = l + b - 1; i >= 0; i--) {
			ans.push_back(p[i]);
			if (ans.size() >= n) {
				return;
			}
		}
		for (int i = r - (a - 1); i < r; i++) {
			ans.push_back(p[i]);
			if (ans.size() >= n) {
				return;
			}
		}
		solve(l + b, r - a + 1, a - 1, b - 1);
	}
}

