long long N, A, B;

vector<long long> solve() {
    vector<long long> res;
    for (long long i = B-1; i >= 0; --i) res.push_back(i);

    if (A == 1) return res;

    long long rem = N - B;
    long long p = rem / (A-1);
    long long r = rem % (A-1);

    long long b = r;
    long long c = A-1-r;

    for (int i = 0; i < b; ++i) {
        int size = res.size();
        for (int j = 0; j < p+1; ++j) {
            res.push_back(size + p - j);
        }
    }
    for (int i = 0; i < c; ++i) {
        int size = res.size();
        for (int j = 0; j < p; ++j) {
            res.push_back(size + p-1 - j);
        }
    }

    return res;
}

int main() {
    while (cin >> N >> A >> B) {
        if (N <= A + B - 2) {
            cout << -1 << endl;
            continue;
        }
        if (N > A*B) {
            cout << -1 << endl;
            continue;
        }

        vector<long long> res = solve();

        for (int i = 0; i < res.size(); ++i) {
            cout << res[i] + 1;
            if (i != (int)res.size() - 1) cout << " ";
        }
        cout << endl;

    }
}

