// Strict LIS
ll LISa(vector<ll>& a) {
    // dp[i][len] = [0, i]のから取れる長さlenのLISを想定した時、その最後の要素として考えられる最小の値
    // iはdpテーブルを使い回している
    vll dp; dp.reserve(100000);
    rep(i, a.size()) {
        auto it = lower_bound(all(dp), a[i]);
        if (it == dp.end()) 
            dp.pb(a[i]);
        else
            *it = a[i];
    }
    return dp.size();
}
// Strict LIS
ll LISd(vector<ll>& b) {
    vector<ll> a = b;
    rep(i, a.size()) {
        a[i] *= -1;
    }
    // dp[i][len] = [0, i]のから取れる長さlenのLISを想定した時、その最後の要素として考えられる最小の値
    // iはdpテーブルを使い回している
    vll dp; dp.reserve(100000);
    rep(i, a.size()) {
        auto it = lower_bound(all(dp), a[i]);
        if (it == dp.end()) 
            dp.pb(a[i]);
        else
            *it = a[i];
    }
    return dp.size();
}

