int M;
bool check(VI xs, int A, int B){
  vector<bool> use(M+1);
  REP(i,M){
	int x = xs[i];
	if(!(1 <= x && x <= M) || use[x]) return false;
	use[x] = true;
  }

  VI lis(M+1, 1e9);
  REP(i,M) *lower_bound(ALL(lis), xs[i]) = xs[i];
  if(lower_bound(ALL(lis), 1e9) - begin(lis) != A) return false;

  fill(ALL(lis), 1e9);
  reverse(begin(xs), begin(xs)+M);
  REP(i,M) *lower_bound(ALL(lis), xs[i]) = xs[i];
  if(lower_bound(ALL(lis), 1e9) - begin(lis) != B) return false;

  return true;
}

bool solve(int g, int i, int ub, int A, int B, VI& xs){
  int n = M - i;
  int x = n - B + g + 1;
  if(0 <= x && x <= A){
	REP(k,x)
	  xs[i+k] = ub + k - (x-1);
	FOR(k,i+x,M)
	  xs[k] = -k + (M-1) + 1;

	return true;
  }
  if(x < 0) return false;

  REP(d,A){
	xs[i] = ub + d - (A-1);
	++i;
  }

  return solve(g+1, i, ub-A, A, B, xs);
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int A, B;
  cin >> M >> A >> B;

  VI xs(2e6);
  if(solve(0, 0, M, A, B, xs) && check(xs, A, B)){
	REP(i,M) cout << (i?" ":"") << xs[i];
	cout << endl;

	return 0;
  }

  swap(A, B);
  fill(ALL(xs), 0);
  if(solve(0, 0, M, A, B, xs) && check(xs, A, B)){
	reverse(begin(xs), begin(xs)+M);
	REP(i,M) cout << (i?" ":"") << xs[i];
	cout << endl;
	return 0;
  }

  cout << -1 << endl;

  return 0;
}

