vector<int> solve(int n, int a, int b) {
	if (a + b > n + 1) {
		return {};
	}

	int bmx = (n - a) + 1;
	int bmn = n / a;
	if (n % a != 0) bmn++;
	if (bmn <= b && b <= bmx) {
		vector<int> cur(b, 1);
		cur[0] = a;
		int rem = n - b - (a-1);
		FOR(i, b - 1) {
			int add = min(a-1, rem);
			rem -= add;
			cur[i + 1] += add;
		}

		vector<int> ret;
		int used = 0;
		FOR(i, b) {
			int st = n - used - cur[i];
			FOR(j, cur[i]) {
				ret.push_back(++st);
			}
			used += cur[i];
		}

		return ret;
	} else {
		return {};
	}
}

