	if(B==1){
		for(int i=1;i<=N;i++){
			printf("%s%d",sp,i);
			sp=" ";
		}
		puts("");
		return 0;
	}
	if(A==1){
		for(int i=N;i>0;i--){
			printf("%s%d",sp,i);
			sp=" ";
		}
		puts("");
		return 0;
	}

	for(int i=N-A+1;i<=N;i++){
		printf("%s%d",sp,i);
		sp=" ";
	}
	LL k=(N-A)/(B-1);
	LL r=(N-A)%(B-1);
	int m=N-A;
	for(int i=0;i<B-1;i++){
		int hi=m;
		int low;
		if(i<r){
			low=m-k;
		}
		else{
			low=m-k+1;
		}
		for(int i=low;i<=hi;i++){
			printf("%s%d",sp,i);
			sp=" ";
		}
		m=low-1;
	}
	puts("");
	assert(m==0);

	return 0;
}

