#include<bits/stdc++.h>
using namespace std;
typedef long long ll;

ll N,A,B;
vector<ll> ans;

void solve(){
  if(A+B > N+1)return;

  if(A==1){
    if(B==N)
      for(int i=0;i<N;i++)ans.push_back(N-i);
    return;
  }
  if(B==1){
    if(A==N)
      for(int i=0;i<N;i++)ans.push_back(i+1);
    return;
  }

  for(int i=1;i<=A;i++){
    ans.push_back(N-A+i);
  }
  B--;
  ll m=N-A;
  ll base=m/B + (m%B>0?1:0);

  if( base > A || base < 1){
    ans.clear();
    return;
  }

  for(int i=0;i<B;i++){
    int flag=false;
    for(int j=1;j<=base;j++){
      int target=m-base+j;
      if(target>0){
        ans.push_back(target);
        flag=true;
      }
    }
    if(!flag){
      ans.clear();
      return;
    }
    m-=base;
  }

  if( (int)ans.size() != N){
    ans.clear();
  }
}

int main(){


