    ll decr_min = (remain / incrs + ((remain % incrs) ? 1LL : 0LL)) + 1LL;
    ll decr_max = remain + 1LL;

    if (decrs < decr_min || decr_max < decrs) {
        cout << -1 << endl;
        return;
    }

    V<ll> anslist;
    ll now = 1LL;
    rep (incr, incrs) {
        ll len = min(n - now + 1LL, decrs);
        ll llen = len;
        rrep (i, now + len) {
            anslist.pb(i);
            llen--;
            if (!llen) break;
        }
        now += len;
    }

    assert(anslist.size() == n);

    rep (i, n) cout << anslist[i] << ((i == n-1) ? "" : " ");
    cout << endl;
}

