void solve(long long N, long long A, long long B){
    if (N < A+B-1 || N > A*B) {
        std::cout << -1 << std::endl;
        return;
    } else {
        vector<int> ret(N);
        int i = 0;
        for (int j = 0; j < A; j++) {
            ret[i] = N - A + j + 1;
            i++;
        }
        if (A == N) {
            for (int j = 0; j < N-1; j++) {
                std::cout << ret[j] << ' ';
            }
            std::cout << ret[N-1] << std::endl;
            return;
        }
        for (int j = 0; j < (N - A)/(B-1); j++) {
            int a = (j+1)*(B-1);
            for (int k = 0; k < B-1; k++) {
                ret[i] = a;
                a--;
                i++;
                if (i == N) {
                    break;
                }
            }
        }
        int l = N-i;
        for (int j = 0; j < l; j++) {
            ret[i] = ret[0] - 1 - j;
            i++;
        }
        for (int j = 0; j < N-1; j++) {
            std::cout << ret[j] << ' ';
        }
        std::cout << ret[N-1] << std::endl;
        return;
    }
}

