	ll N, A, B;
	cin >> N >> A >> B;
	if (N < A + B - 1 || N > A*B) {
		puts(-1);
		return 0;
	}

	vector<int>temp(N);
	vector<int>ans;
	for (int i = 0; i < A; i++) {
		temp[i] = N - A + 1 + i;
		ans.pb(temp[i]);
	}
	for (int i = A; i < N; i++)temp[i] = N - i;


	int cur = N - A + 1;
	int idx = A;
	while (idx < N) {
		if (cur - (A - 1) > B) {
			for (int i = 0; i < A; i++)ans.pb(temp[idx+A-1-i]);
			cur -= A - 1;
			idx += A;
			continue;
		}
		for (int i = 0; i < cur - B; i++)ans.pb(temp[idx+cur-B-i]);
		ans.pb(temp[idx]);
		for (int i = idx + cur - B + 1; i < min(N,idx + A); i++)ans.pb(temp[i]);
		idx += A;
		break;
	}
	for (int i = idx; i < N; i++)ans.pb(temp[i]);
	for (int i = 0; i < N; i++)cout << ans[i] << " ";
