vector<int> calc(ll n, ll x, ll y, bool rev) {
    if (x > n || y > n) {
        LINE;
        return vi{};
    }
    vector<int> len;
    ll m = n - x;
    len.pb(x);
    rep(i, y - 1) {
        if (i == y-2) {
            if (m > x) {
                LINE;
                return vi{};
            }
            if(m < 0) {
                return vi{};
            }
            len.pb(m);
            m = 0;
        } else {
            int k = 1;
            if (m > n - (ll)len.size()) {
                k = min(x, m - (n - (ll)len.size()));
            }
            len.pb(k);
            m -= k;
            if(m<0) return vi{};
        }
    }
    if(accumulate(all(len), 0LL) != n) return vi{};
    vector<int> ans;
    queue<int> q;
    if(rev) {rep(i, n) q.push(i+1);}
    else {rep(i, n) q.push(n - i);}
    rep(i, y) {
        stack<int> st;
        rep(j, len[i]) {
            st.push(q.front());
            q.pop();
        }
        while (!st.empty()) {
            ans.pb(st.top());
            st.pop();
        }
    }
    return ans;
}

