int dp[1111];

int LIS(const vector<int>& V) {
    dp[0]=1;

    int ans = 1;
    for(int i=1;i<V.size();i++) {
        dp[i]=1;
        for(int j=0;j<i;j++)
            if (V[j]<V[i])
                dp[i]=max(dp[i],1+dp[j]);
        ans = max(ans, dp[i]);
    }
    return ans;



}

int ceilval(int a,int b) {
    return (a+b-1)/b;
}

vector<int> Solve(int N,int A,int B) {


    if (A < 0 || B < 0)
        return vector<int>();

    if (A > B) {
        vector<int> tmp = Solve(N,B,A);
        std::reverse(tmp.begin(),tmp.end());
        return tmp;
    }



    vector<int> suff;
    for(int i=N;i>=N-B+1;i--) {
        suff.push_back(i);
    }


    if (B == N) {
        if (A == 1) {
            return suff;
        } else {
           // printf("%d %d %d\n",N,A,B);
            return vector<int>();
        }
    }

    // <= B

    // (N-B,A-1)

    if (A-1 > N-B || A-1 == 0)
        return vector<int>();


    int ymax = N-B+1-(A-1);
    int ymin = ceilval(N-B,A-1);
    ymin = min(ymin, B);

    if (ymin > ymax)
        return vector<int>();


    vector<int> pref = Solve(N-B,A-1,ymin);


    if (pref.empty())
        return vector<int>();


    for(int x : suff)
        pref.push_back(x);
    return pref;

}


void SolveBrute(int N,int A,int B) {

    vector<int> V(N,-1);
    for(int i=0;i<N;i++)
        V[i]=i;


    do {
        vector<int> Vr = V;
        std::reverse(Vr.begin(),Vr.end());
        if (LIS(V)==A && LIS(Vr)==B) {
            for(int i=0;i<V.size();i++)
                printf("%d ",V[i]+1);
            cout << endl;
            return;
        }


    }while(next_permutation(V.begin(),V.end()));

}


