int N, A, B;

deque<int> ans;

int main(){
    cin >> N >> A >> B;
    if (A + B > N + 1) {
        cout << -1 << endl;
        return 0;
    }

    bool rev = false;
    if (A < B) {
        int tmp = B;
        B = A;
        A = tmp;
        rev = true;
    }

    if (B == 1) {
        if (A == N) {
            for (int i = 1; i <= N; ++i) {
                ans.push_back(i);
            }
        } else {
            cout << -1 << endl;
            return 0;
        }
    } else {
        int cnt = A + B - 1;
        for (int i = 1; i <= A - 1; ++i) {
            ans.push_back(i);
        }
        for (int i = N; i >= N - B + 1; --i) {
            ans.push_back(i);
        }
        int k = 0;
        while(k * A + A <= N - B) {
            int i = min(k * A + A + A - 1, N - B);
            for (; i >= k * A + A; --i) {
                ans.push_front(i);
            }
            k++;
        }
        if (k >= B) {
            cout << -1 << endl;
            return 0;
        }
    }
    if (rev) {
        reverse(ans.begin(), ans.end());
    }

    for (int i = 0; i < ans.size() - 1; ++i) {
        cout << ans[i] << " ";
    }
    cout << ans[ans.size() - 1];
    cout << endl;
}

