vector<Int> solve(Int N, Int A, Int B){
  if(A + B > N + 1) return {-1};
  if(A * B < N) return {-1};

  vector<Int> res;
  Int cur = 0;
  Int num = A * B - N;
  for(Int i=0;i<B;i++) res.push_back(cur + B - i);
  cur += B;
  for(Int i=0;i<A - 1;i++){
    if(num) res.push_back(cur + 1), num--, cur++;
    else{
      for(Int i=0;i<B;i++) res.push_back(cur + B - i);
      cur += B;
    }
  }
  Int x = N;
  Int y = res.back(); res.pop_back();
  while((Int)res.size() != N - 1) res.push_back(x--);
  res.push_back(y);
  assert(res.size() == N);
  return res;
}


