int N;
int A;
int B;
deque<vector<int>> buckets;

int main() {
  scanf("%d%d%d", &N, &A, &B);
  int low = N/A + (N%A != 0);
  int high = N-A+1;
  if (B < low || high < B) {
    puts("-1");
    return 0;
  }

  for (int i=0; i<N; i+=A) {
    vector<int> buck;
    reps(j, i, min(i+A, N)) buck.emplace_back(j);
    buckets.emplace_front(move(buck));
  }

  int M = buckets.size();
  //printf("high: %d\n", high);
  rep(i, M-1) {
    auto &buck = buckets[i];
    int t = (int)buck.size();
    int d = min(high - B, t-1);
    //printf("d: %d\n", d);
    reverse(buck.begin()+d, buck.end());
    high -= d;
  }
  assert(high == B);

  bool first = true;
  for (auto &buck : buckets) {
    for (auto v : buck) {
      if (first) printf("%d", v+1);
      else printf(" %d", v+1);
      first = false;
    }
  }
  puts("");
}

