			pack.back().push_back(i + 1);
			if (pack.back().size() == A) {
				pack.push_back(vector<int>());
			}
		}
		int chomp = B - (int)pack.size();
		vector<vector<int>>rev;
		while (pack.size()) {
			vector<int>vec = pack.back();
			while (vec.size() && chomp > 0) {
				rev.push_back(vector<int>(1, vec.back()));
				vec.pop_back();
				--chomp;
			}
			if (vec.size()) {
				rev.push_back(vec);
			}
			pack.pop_back();
		}
		assert(chomp == 0);
		vector<int>ans;
		for (auto& elm : rev) {
			for (int x : elm) {
				ans.push_back(x);
			}
		}
		print(ans);
		return 0;
	}
	cout << "-1" << endl;
	return 0;
}

