int main() {
	int N, A, B;
	cin >> N >> A >> B;
	if (N < A + B - 1 || N > (int64_t)A * B) { // これ不可能なので
		cout << -1;
		return 0;
	}
	int use = 0;
	int64_t branch;
	for (int i = 0;i < A;i ++) {
		branch = N - (int64_t)i * B - (A - i) + 1; // この親ノードにおける左の列の長さ
		if (branch > B) branch = B; // Bは超えない
		if (branch <= 0) branch = 1; // 最低1マスを確保するように作ってる
		for (int j = 0;j < branch;j ++) {
			cout << use + branch - j;
			if (i < A - 1 || j < branch - 1) cout << " "; // 空白条件を間違えずに
		}
		use += branch;
	}
	return 0;
}
/*
31536000のコメント解説欄
ここテンプレで用意してるから、A問題とかだとこの先空欄の危険あり

一つ構成し～系は分かりやすい形のを1個作れば通ることが多い
さて、次のような木を作ることにする
全ての親ノードについて、左の子は親より小さく、右の子は親より大きい
これを親→左→右の順番で表示するとそれは列Pになるし、
最大の左に続く長さが最小部分文字列、最大の右に続く長さが最大部分文字列になる
ということで、この木を作っていけば良い
木が完成すれば適当な数を、上から順に入れていく この時最大の左に続く長さ+1を親にしておけば無問題に動く

さて、これは実は木を作らなくても動く
まず根を決めて、左にずっとB-1個、右にずっとA-1個置いてしまう
これが置ければ、次に根より下の右側の親から要素数がNを超えない範囲で左にB-1個置いていけば良い
これで最大AB個置ける
*/

