    cin >> n >> a >> b;
    bool flip = 0;
    if((n + a - 1) / a != b){
        if((n + b - 1) / b != a) finish(-1);
        swap(a, b);
        flip = 1;
    }
    vector <int> ans(n);
    int cur = 0;
    for(int i = 0 ; i < n ; i++){
        if(i % a == 0){
            cur = max(1, n - i / a * a - a + 1);
