const double EPS = 1e-10;
const double PI  = acos(-1.0);
const LL MOD = 1e9+7;

int M;
bool check(VI xs, int A, int B){
  vector<bool> use(M+1);
  REP(i,M){
	int x = xs[i];
	if(!(1 <= x && x <= M) || use[x]) return false;
	use[x] = true;
  }

  VI lis(M+1, 1e9);
  REP(i,M) *lower_bound(ALL(lis), xs[i]) = xs[i];
  if(lower_bound(ALL(lis), 1e9) - begin(lis) != A) return false;

  fill(ALL(lis), 1e9);
  reverse(begin(xs), begin(xs)+M);
  REP(i,M) *lower_bound(ALL(lis), xs[i]) = xs[i];
  if(lower_bound(ALL(lis), 1e9) - begin(lis) != B) return false;

  return true;
}

bool solve(int ub, int lb, int A, int B, int b, VI& xs){
  int N = ub-lb+1;

  if(b >= M) return true;
  if(A == 0 || B == 0 || N <= 0) return true;
  if(b+A < M){
	REP(i,A) xs[b+i] = ub-A+1+i;
  }
  else{
	A = M - b;
	REP(i,A) xs[b+i] = ub-A+1+i;
	return true;
  }

  if(b+A+B-1 < M){
	REP(i,B-1) xs[b+A+i] = B-1-i+lb-1;
  }
  else{
	for(int i=M-1;i>=b+A;--i){
	  xs[i] = B + (M-1)-i;
	}
	return true;
  }

  return solve(ub-A, lb+B-1, A-1, B-1, b+A+B-1, xs);
}

int main(){
  cin.tie(0);
  ios_base::sync_with_stdio(false);

  int A, B;
  cin >> M >> A >> B;

  VI xs(2e6);
  if(solve(M, 1, A, B, 0, xs) && check(xs, A, B)){
	REP(i,M) cout << (i?" ":"") << xs[i];
	cout << endl;

	return 0;
  }

  swap(A, B);
  fill(ALL(xs), 0);
  if(solve(M, 1, A, B, 0, xs) && check(xs, A, B)){
	reverse(ALL(xs));
	REP(i,M) cout << (i?" ":"") << xs[i];
	cout << endl;
	return 0;
  }

  cout << -1 << endl;

  return 0;
}

