  b--;
  vector< int > ans;
  int bottom = 1, top = n;
  while (n > 0) {
    if (a+b > n+1) {
      if (ans.size() == 0) {
        cout << -1 << endl;
        return 0;
      }
      for (int i=max(bottom, top-a+1); i<=top; ++i) ans.push_back(i);
