int N, A, B;
int ans[MAX_N];

void solve() {
	cin >> N >> A >> B;
	if(N == 1) {
		if(A == 1 && B == 1) {
			cout << 1 << "\n";
		}
		else cout << "-1\n";
		return;
	}
	bool swaped = false;
	if(A < B) {
		swap(A, B);
		swaped = true;
	}
	vector<int> cnt(B, 1);
	int n = N;

	if((N + A - 1) / A > B) {
		cout << "-1\n";
		return;
	}

	rep(i, 0, (N + A - 1) / A) {
		cnt[i] = min(A, n);
		n -= A;
	}

	int r = B - (N + A - 1) / A;

	rep(i, 1, (N + A - 1) / A) {
		if(cnt[i] - 1 >= r) {
			cnt[i] -= r;
			r = 0;
		}
		else {
			cnt[i] = 1;
			r -= (cnt[i] - 1);
		}
	}

	if(r != 0) {
		cout << "-1\n";
		return;
	}

	int at = 0;
	int from = N - 1;

	rep(i, 0, B) {
		rep(j, 0, cnt[i]) {
			ans[at] = from - cnt[i] + j + 1;
			at++;
		}
		from -= cnt[i];
	}

	if(swaped) reverse(ans, ans + N);
	rep(i, 0, N) {
		cout << ans[i] + 1 << " ";
	}
	cout << "\n";
}

