void solve() {
  int N, A, B;
  cin >> N >> A >> B;
  if (N < A + B - 1 || (i64) A * B < N) no();
  vector<vi32> lst(B, vi32(A, 0));
  vector<vi32> flg(B, vi32(A, 1));
  rep(i, B) rep(j, A) {
    lst[i][j] = (B - i - 1) * A + j;
  }
  int cnt = A;
  rep(j, A) reps(i, B - 1) {
    if (++cnt > N) flg[i][j] = 0;
  }
  vi32 cc;
  rep(i, B) rep(j, A) if (flg[i][j]) cc.push_back(lst[i][j]);
  sort(all(cc));
  vi32 ans;
  rep(i, B) rep(j, A) if (flg[i][j]) {
    int idx = lower_bound(all(cc), lst[i][j]) - cc.begin();
    ans.push_back(idx + 1);
  }
  cout << ans << '\n';
}

