    rep(i,A-1) ans[i] = i+1;
    rep(i,B-1) ans[A-1+i] = N-i;
    int k = 0;
    rep(i,N+2-A-B) {
        if (i%2==0) {
            ans[A+B-2+i] = A+k;
        } else {
            ans[A+B-2+i] = N+1-B-k;
            k++;
        }
    }

    rep(i,N) cout << ans[i] << " ";
    cout << endl;
}

