vi lis(const vi &v) {
	int n = v.size();
	vi prev(n, -1);
	vi dp(n + 1, INF);
	vi pos(n + 1, -1);
	REP(i, n) {
		int c = lower_bound(ALL(dp), v[i]) - dp.begin();//lower:strongly increasing
														//int c = upper_bound(ALL(dp), v[i]) - dp.begin();// upper:weakly increasing
		pos[c] = i;
		dp[c] = v[i];
		if (c != 0)prev[i] = pos[c - 1];
	}

	vi ret;

	int p = pos[lower_bound(ALL(dp), INF) - dp.begin() - 1];


	while (p != -1) {
		ret.push_back(v[p]);
		p = prev[p];
	}
	reverse(ALL(ret));
	return ret;

}

