long solve() {
	if (a+b-1>n || a<=0 || b<=0) return 0;
	int t=n, s=1, p=0;
	while (p<n) {
		if (a<0 && b<=0) return 0;
		int q = p;
		for (int i=0; i<a && p<n; i++) {
			r[p++] = t--;
