void solve(std::istream &in, std::ostream &out) {
  int n,a,b;
  in >> n >> a >> b;
  if (a + b - 1 > n || (int64_t) a * b < n)
    return void(out << "-1\n");
  for (int block = b, sz; block >= 1; --block) {
    sz = min(n - block + 1, a);
    for (int i = 0; i < sz; ++i) {
      out << n - sz + 1 + i << ' ';
    }
    n -= sz;
  }
}

