int LongestIncreasingSubsequence(const std::vector<int> &a) {
    std::vector<int> dp(a.size(), 1 << 28);
    for (int i = 0; i < a.size(); ++i) {
        *std::lower_bound(dp.begin(), dp.end(), a[i]) = a[i];
    }
    return (std::lower_bound(dp.begin(), dp.end(), 1 << 28) - dp.begin());
}

int main() {
    i64 n, a, b;
    in(n, a, b);

    if (a + b > n + 1 || a * b < n) {
        out(-1);
        return 0;
    }

    i64 m = a * b;
    i64 r = 0;
    vector<i64> seq;
    seq.reserve(n);

    for (i64 i : rep(0, b)) {
        seq.push_back(b - i);
    }

    r += n - (a + b - 1);

    for (i64 i : rep(1, a)) {
        seq.push_back(b * (i + 1));

        for (i64 j : rep(1, b)) {
            if (r == 0) {
                break;
            }

            seq.push_back(b * (i + 1) - j);
            r--;
        }
    }

    auto sorted = seq;
    sort(sorted);

    map<i64, i64> comp;

    for (i64 x : sorted) {
        comp.insert({x, comp.size() + 1});
    }

    for (i64 &x : seq) {
        x = comp[x];
    }

    vout(seq, n);
}

