		for (int j = 0; j < base + 1; ++j)
		{
			std::cout << now - j << " ";
		}
	}
	for (int i = (N - B) % (A - 1); i < A - 1; ++i)
	{
		now += base;
		for (int j = 0; j < base; ++j)
		{
			std::cout << now - j << " ";
		}
	}
	std::cout << N;
	for (int i = N - 1; i > now; --i)
	{
