typedef long long ll;
bool solve(ll n,ll a,ll b,int k){
  vector<ll> vec[300005];
  ll fa=a,fb=b;
  int cnt=0;
  for(int sp=n-a;sp>=0;sp-=a){
    for(int i=sp+1;i<=sp+a;i++){
      vec[cnt].push_back(i);
    }
    cnt++;
  }
  for(int i=1;i<=n%a;i++) vec[cnt].push_back(i);
  if(n%a!=0) cnt++;
  vector<ll> kans;
  b-=cnt;
  for(int sp=cnt-1;sp>=0;sp--){
    ll dec=min(b,(ll)vec[sp].size());
    b-=dec;
    for(int i=vec[sp].size()-dec-1;i>=0;i--) kans.push_back(vec[sp][i]);
    for(int i=vec[sp].size()-dec;i<vec[sp].size();i++) kans.push_back(vec[sp][i]);
  }
  vector<ll> ans;
  for(int i=n-1;i>=0;i--) {
    ans.push_back(kans[i]);
  }
  vector<ll> up(300005,17441744);
  up[0]=0;
  up[1]=ans[0];
  for(int i=1;i<n;i++){
    ll pos=upper_bound(up.begin(),up.end(),ans[i])-up.begin();
    up[pos]=min(up[pos],ans[i]);
  }

  vector<ll> down(300005,17441744);
  down[0]=0;
  down[1]=kans[0];
  for(int i=1;i<n;i++){
    ll pos=upper_bound(down.begin(),down.end(),kans[i])-down.begin();
    down[pos]=min(down[pos],kans[i]);
  }
  bool f=true;
  if(up[fa]==17441744||up[fa+1]<17441744){
    f=false;
  }
  if(down[fb]==17441744||down[fb+1]<17441744){
    f=false;
  }
  if(f){
    if(k==0){
      for(int i=0;i<n;i++) cout<<ans[i]<<" ";
      cout<<endl;
    }
    else{
      for(int i=0;i<n;i++) cout<<kans[i]<<" ";
      cout<<endl;
    }
  }
  return f;
}
