#define N 10
int n = N-1;
int t[N];

void upd(int pos, int v){
    for(;pos <= n; pos += pos & -pos){
        if(v > t[pos]){
            t[pos] = v;
        }
    }
}

int qu(int pos){
    int ret = 0;
    for(;pos > 0; pos -= pos & -pos){
        if(t[pos] > ret){
            ret = t[pos];
        }
    }
    return ret;
}

