            }
            int l = i / a * a, r = min(n, (i / a + 1) * a - 1);
            int g = r - i + 1;
            for(int j = l ; j < i ; j++){
                ans[j] += g;
            }
            break;
        }
    }
    if(ok == 0) return {};
    return ans;
}
