#define FOR(i, n, m) for(ll (i)=(m);(i)<(n);++(i))
#define REP(i, n) FOR(i,n,0)
#define OF64 std::setprecision(10)

const ll MOD = 1000000007;
const ll INF = (ll) 1e15;

ll dp[100];

vector<ll> solve(ll N, ll A, ll B) {
    vector<ll> v;
    ll t = 0;
    while (v.size() < N) {
        if (N - t == A) {
            for (ll i = t + 1; i <= N; ++i) {
                v.push_back(i);
            }
            break;
        }
        for (ll i = std::min(N - (A - 1), t + B); i > t; --i) {
            v.push_back(i);
        }
        t = std::min(N - (A - 1), t + B);
        A--;
    }
    return v;
}

ll LIS(vector<ll> v) {
    ll n = v.size();
    REP(i, n + 1) {
        dp[i] = INF;
    }

    REP(i, n) {
        *lower_bound(dp, dp + n, v[i]) = v[i];
    }

    return lower_bound(dp, dp + n, INF) - dp;
}

ll LDS(vector<ll> v) {
    ll n = v.size();
    REP(i, n + 1) {
        dp[i] = 0;
    }

    REP(i, n) {
        REP(j, n) {
            if (dp[j] < v[i]) {
                dp[j] = v[i];
                break;
            }
        }
    }
    REP(i, n + 1) {
        if (dp[i] == 0)
            return i;
    }
    return 0;
}

