#include <bits/stdc++.h>
using namespace std;

typedef long long ll;

ll N, A, B;
ll Top;

void go(ll k) {
  for (ll i = 0; i < k; ++i) {
    cout << Top - (k - 1) + i << endl;
  }
  Top -= k;
}
void solve() {
  if (N < A + B - 1 || A * B < N) {
    cout << -1 << endl;
    return;
  }
  Top = N;
  for (ll i = 0; i < B; ++i) {
    if (A == 1) {
      assert(N == B);
      go(1);
    } else {
      ll n_fulls = (N - B) / (A - 1);
      go(i < n_fulls ? A : i == n_fulls ? (N - B) % (A - 1) + 1 : 0);
    }
  }
}
int main() {
  cin >> N >> A >> B;
  solve();
  return 0;
}

