void solve(int n, int a, int b)
{
  if (a + b - 1 > n)
    {
      puts("-1"); return;
    }
  int lower_bound = (n + (a-1))/a;
  if (b < lower_bound)
    {
      puts("-1"); return;
    }
  vector<int> ans;
  int tmp = n-a;
  for (int i = 0, cur = 1; i < a; ++i)
    {
      int len = min(tmp, b-1);
      tmp -= len;
      ++len;
      cur += len;
      for (int i = 1; i <= len; ++i) ans.pb(cur - i);
    }
  assert(ans.size() == n);
  for (int i = 0; i < n; ++i)
    printf("%d%c", ans[i], " \n"[i+1==n]);
}
int main()
{
  int n, a, b;
  while (~scanf("%d %d %d", &n, &a, &b)) solve(n, a, b);

}

