#include<bits/stdc++.h>
using namespace std;
int main(){
    int N, A, B;
    cin >> N >> A >> B;
    if(N < A + B - 1){
        cout << -1 << endl;
        return 0;
    }
    set<int> se;
    se.insert(0);
    vector<int> ans;
    int block = N / A + !!(N % A);
    for(;; block--){
        int nokori = max<int>(0, N - block * A);
        if(block + (block * A >= N ? 0 : 1) <= B && B <= block + nokori) break;
        if(block == 0){
            cout << -1 << endl;
            return 0;
        }
    }
    int flag = N - A + 1;
    int small = N + 1;
    for(int i = 0; i < block; i++){
        bool ok = 0;
        for(int j = 0; j < A && flag + j < small; j++){
            ans.push_back(flag + j);
            ok = 1;
            if(se.find(flag + j) != se.end()){
                cout << -1 << endl;
                return 0;
            }
            se.insert(flag + j);
        }
        if(!ok){
            cout << -1 << endl;
            return 0;
        }
        small = flag;
        flag = max<int>(1, flag - A);
    }
    int nokori = max<int>(0, N - block * A);
    int sagaru = B - block;
    for(int i = 1; i <= nokori - sagaru; i++){
        ans.push_back(i);
        if(se.find(i) != se.end()){
            cout << -1 << endl;
            return 0;
        }
        se.insert(i);
    }
    for(int i = nokori; nokori - sagaru + 1 <= i; i--){
        ans.push_back(i);
        if(se.find(i) != se.end()){
            cout << -1 << endl;
            return 0;
        }
        se.insert(i);
    }
    if(nokori - sagaru > A || block + sagaru != B || ans.size() != N){
        cout << -1 << endl;
        return 0;
    }
    for(int aaa : ans) cout << aaa << " ";
    cout << endl;
    return 0;
}

