{
    scanf("%d %d %d", &n, &a, &b);
    for (int i = 1; i <= n; ++i) s[i] = i;
    if (a + b > n + 1) puts("-1");
    else{
        if (solve()){
            for (int i = 1; i <= n; ++i) printf(i == n ? "%d\n" : "%d ", s[i]);
        }else puts("-1");
    }
    return 0;
}

