	cin >> N >> A >> B;

	if (A == 1 && B == N) {
		REP(i,N) cout << N - i << " ";
		cout << endl;
		return 0;
	}

	if (B == 1 && A == N) {
		REP(i,N) cout << i + 1 << " ";
		cout << endl;
		return 0;
	}

	if (A + B > N) {
		cout << -1 << endl;
		return 0;
	}

	if (A + B == N) {
		if (A >= B) {
			REP(i,B) cout << N - i << " ";
			REP(i,A) cout << i + 1 << " ";
			cout << endl;
		} else {
			REP(i,A) cout << i + 1 << " ";
			REP(i,B) cout << N - i << " ";
			cout << endl;
		}
		return 0;
	}

	ll L = N - A - B;
	ll a = 1, b = 1;
	for (ll i = 1; i * i <= L; i++) {
		if (L % i == 0) {
			a = i;
			b = L / i;
			if (a <= A && b <= B) break;
		}
	}

	if (!(a <= A && b <= B)) {
		cout << -1 << endl;
		return 0;
	}

