void compress(vector<ll> &x) {
  vector<ll> v(x.size());
  REP(i, 0, x.size()) v[i] = x[i];
  sort(v.begin(), v.end());
  v.erase(unique(v.begin(), v.end()), v.end());
  REP(i, 0, x.size()) x[i] = lower_bound(v.begin(), v.end(), x[i]) - v.begin();
}

