#include<bits/stdc++.h>
using namespace std;
const int N=4e5+5;
int n,a,b,s[N],f1[N],f2[N];
bool check()
{
    int ans1=0,ans2=0;
    for(int i=1;i<=n;i++)
    {
        f1[s[i]]=max(f1[s[i]-1]+1,1);
        f2[s[i]]=max(f2[s[i]+1]+1,1);
        ans1=max(ans1,f1[s[i]]);
        ans2=max(ans2,f2[s[i]]);
    }
    return ans1==a&&ans2==b;
}
void solve(int a,int b)
{
    int tot=0;
    for(int i=n-a+1;i<=n;i++)
        s[++tot]=i;
    n-=a;
    b--;
    if(b==0)
    {
        if(n==0)
            for(int i=1;i<=tot;i++) cout<<s[i]<<' ';
        else cout<<-1;
        return;
    }
    int len=n/b,k=n%b;
    for(int i=1;i<=k;i++)
    {
        int x=len+1;
        for(int i=n-x+1;i<=n;i++)
            s[++tot]=i;
        n-=x;
    }
    for(int i=1;i<=b-k;i++)
    {
        int x=len;
        for(int i=n-x+1;i<=n;i++)
            s[++tot]=i;
        n-=x;
    }
    assert(n==0);
    n=tot;
    if(!check()) printf("-1\n");
    else for(int i=1;i<=n;i++)
        printf(i==n?"%d\n":"%d ",s[i]);
}
int main()
{
    scanf("%d%d%d",&n,&a,&b);
    if(a+b-1>n||a>n||b>n) printf("-1\n");
    else solve(a,b);
}

