    int nodef(const int& lhs,const int& rhs)const{return lhs+rhs;}
public:
    RSQ(int size, const int& def = 0) :kaageSegTree<int>(size, def, 0) {}
    RSQ(const std::vector<int>& initvec) :kaageSegTree<int>(initvec, 0) {}
};
