        cin >> n >> a >> b;
        if (a * 1LL * b < n || a + b - 1 > n) {          // without 1LL here can be a bug
            cout << -1 << endl;
            continue;
        }
        int maxElement = n;
        int ansLength = 0;
        int remainDS = b;
        while (remainDS > 0 && ansLength + a + remainDS - 1 <= n) {
            for(int i = maxElement - a + 1; i <= maxElement; i++) {
                ans[++ansLength] = i;
            }
            --remainDS;
            maxElement -= a;
        }
        if (remainDS != 0) {
            --remainDS;
            int wn = 0;
            while (maxElement != remainDS) {
                w[++wn] = maxElement;
                --maxElement;
            }
            reverse(w + 1, w + wn + 1);
            for(int i = 1; i <= wn; i++) {
                ans[++ansLength] = w[i];
            }
            for(int i = remainDS; i >= 1; i--) {
                ans[++ansLength] = i;
            }
        }
        for(int i = 1; i < n; i++) {
            cout << ans[i] << " ";
        }
        cout << ans[n] << endl;
    }
    return 0;
}

