  }

  vector<ll> ans(n);
  int x=n;
  rep(i,n){
    if(i%a==0){
      if(i+a-1>=n) ans[i]=1;
      else ans[i]=x-a+1;
      x-=a;
    }
    else ans[i]=ans[i-1]+1;
  }

  auto p=ans;
  reverse(all(p));

  int sa=b-lis(p);

  int y=0;
  while(sa>=a-1){
    reverse(ans.begin()+y,ans.begin()+y+a);
    y+=a;
    sa-=a-1;
  }
  reverse(ans.begin()+y,ans.begin()+y+sa+1);

  rep(i,n){
    if(i!=0) cout << " ";
    cout << ans[i];
  }
  cout << endl;

}

