int main() {

	ll N,A,B;
	cin >> N >> A >> B;

	if (A == 1 && B == N) {
		REP(i,N) cout << N - i << " ";
		cout << endl;
		return 0;
	}

	if (B == 1 && A == N) {
		REP(i,N) cout << i + 1 << " ";
		cout << endl;
		return 0;
	}

	if (A + B > N) {
		cout << -1 << endl;
		return 0;
	}

	if (A + B == N) {
		if (A >= B) {
			REP(i,B) cout << N - i << " ";
			REP(i,A) cout << i + 1 << " ";
			cout << endl;
		} else {
			REP(i,A) cout << i + 1 << " ";
			REP(i,B) cout << N - i << " ";
			cout << endl;
		}
		return 0;
	}


	ll L = N - A - B;
	ll a = 1, b = 1;
	for (ll i = 1; i * i <= L; i++) {
		if (L % i == 0) {
			a = i;
			b = L / i;
		}
	}

	if (A >= B) {
		if (b > a) swap(a, b);
	} else {
		if (a > b) swap(a, b);
	}

	if (!(a <= A && b <= B)) {
		cout << -1 << endl;
		return 0;
	}

	if (A >= B) {
		vector < ll > left_t;
		for (ll i = A + 1; i <= N - B; i++) {
			left_t.push_back(i);
		}
		for (ll i = b - 1; i >= 0; i--) {
			for (ll j = i * a; j < (i + 1) * a; j++) {
				cout << left_t[j] << " ";
			}
