		REP(i,B) cout << N - i << " ";
		REP(i,A) cout << i + 1 << " ";
		cout << endl;
	} else {
		vector < ll > left_t;
		for (ll i = A + 1; i <= N - B; i++) {
			left_t.push_back(i);
		}
		for (ll i = b - 1; i >= 0; i--) {
			for (ll j = i * a; j < (i + 1) * a; j++) {
				cout << left_t[j] << " ";
