	cin >> n >> a >> b;
	if (a + b > n + 1 || a * b < n) {
		cout << -1 << endl;
		return 0;
	}
	vector<int> ans;
	for (int i = n + 1 - a; i <= n; i++) ans.push_back(i);
	int base = (n - a) / (b - 1);
	int over = n - a - base * (b - 1);
	int c = ans[0] - base;
	if (over != 0) c--;
	for (int i = 0; i < over; i++) {
		for (int j = 0; j <= base; j++) {
			ans.push_back(c);
			c++;
		}
