void solve() {
    ll n, a, b;
    cin >> n >> a >> b;
    if(a * b < n || a + b - 1 > n) {
        cout << -1 << endl;
        return;
    }
    vvll v(a, vll(b));
    rep(i, a) rep(j, b) v[i][j] = i * a + b - j;
    vll v2;
    ll rem = a * b - n;
    rep(i, a) rep(j, b) {
        if(i > 0 && j > 0 && rem > 0) {
            --rem;
            continue;
        }
        v2.push_back(v[i][j]);
    }
    vll v3 = v2;
    sort(v3.begin(), v3.end());
    for(ll i : v2) {
        ll j = lower_bound(v3.begin(), v3.end(), i) - v3.begin() + 1;
        cout << j << ' ';
    }
    cout << endl;
    return;
}

