	//! 増加部分
	for (size_t i = N - (A - 1); i <= N; i++)
	{
		cout << i << endl;
	}

	//! 減少部
	for (size_t i = (B - 1); i >= 1; i--)
	{
		cout << i << endl;
	}

	//! 増加部と減少部の長さが1になるように
	int max = N - A;
	int min = B;
	for (size_t i = 0; min <= max; i++)
	{
		if (i % 2 == 0)
		{
			cout << max << endl;
			max--;
			continue;
		}
		cout << min << endl;
		min++;
	}
	return 0;
}

