int LIS(vector<int>& v) {
	int N = v.size();
	vector<int> dp(N, INF);

	for (int i = 0; i < N; i++)
		* lower_bound(dp.begin(), dp.end(), v[i]) = v[i];

	int ans = lower_bound(dp.begin(), dp.end(), INF) - dp.begin();
	return ans;
}

int LDS(vector<int> v) {
	int N = v.size();
	rep(i, N) v[i] *= -1;
	vector<int> dp(N, INF);

	for (int i = 0; i < N; i++)
		* lower_bound(dp.begin(), dp.end(), v[i]) = v[i];

	int ans = lower_bound(dp.begin(), dp.end(), INF) - dp.begin();
	return ans;
}

