    if (A + B > N+1) {
        cout << -1 << endl;
        return 0;
    }
    if (A == 1) {
        if (B != N) {
            cout << -1 << endl;
            return 0;
        } else {
            rep(i,N) cout << N-i << " ";
            cout << endl;
            return 0;
        }
    }
    if (B == 1) {
        if (A != N) {
            cout << -1 << endl;
            return 0;
        } else {
            rep(i,N) cout << i+1 << " ";
            cout << endl;
            return 0;
        }
    }
    int K = (N+A-1) / A;
    if (K > B) {
        cout << -1 << endl;
        return 0;
    }
    int L,R;
    rep(i,N+1) {
        if (B == N-i+(i+A-2)/A) {
            R = i;
            L = N - R;
        }
    }
    vector<int> ans(R);
    int num = A;
    int val = 1;
    rep(_,R) {
        ans[--num] = val++;
        if (num%A == 0) num = min(R,num+A*2);
    }
    rep(i,L) ans.emplace_back(val++);
