int n,a,b;
vector<int>ans;
int main(void){
    cin>>n>>a>>b;
    if(n+1<a+b||((n+a-1)/a>b&&(n+b-1)/b>a)){
        cout<<-1<<endl;
        return 0;
    }
    if((n+a-1)/a<=b){
        int o=1;
        for(int i=o+b-1;i>=o;i--)ans.push_back(i);
        o+=b;
        b=(n-o+1+a-2)/(a-1);
        for(;o+b-1<=n;o+=b){
            for(int j=o+b-1;j>=o;j--)ans.push_back(j);
        }
        for(int i=n;i>=o;i--)ans.push_back(i);
    }else{
        int o=n;
        for(int i=o-b+1;i<=o;i++)ans.push_back(i);
        o-=b;
        b=(n-o+1+a-2)/(a-1);
        for(;o-b+1>=1;o-=b){
            for(int j=o-b+1;j<=o;j++)ans.push_back(j);
        }
        for(int i=1;i<=o;i--)ans.push_back(i);
    }
    for(int i=0;i<ans.size();i++){
        if(i!=0)cout<<' ';
        cout<<ans[i];
    }
    cout<<endl;
    return 0;
}

