void NO() {
	puts("-1");
	exit(0);
}
int main()
{
	int n, a, b;
	cin >> n >> a >> b;
	bool rev = false;
	if (rev = a < b)
		swap(a, b);
	vector<int> v;
	for (int i = 1; i <= a; ++i)
		v.push_back(i);
	reverse(v.begin(), v.end());
	for (int i = 1; i < b; ++i)
		v.push_back(a + i);
	reverse(v.begin(), v.end());
	if (v.size() > n)
		NO();
	vector<int> sol;
	int rem = n - v.size();
	int l = n - rem + 1;
	int r = n;
	int dx = -1;
	swap(l, r);
	dx = -dx;
	for (int i = v.size() - 1; i >= 0; --i) {
		if (rem) {
			--rem;
			sol.push_back(r);
			r += dx;
			dx = -dx;
			swap(l, r);
		}
		sol.push_back(v[i]);
	}
	while (rem--) {
		sol.push_back(r);
		r += dx;
		dx = -dx;
		swap(l, r);
	}
	if (sol.size() != n)
		NO();
	sol = v;
	reverse(sol.begin(), sol.end());
	for (int it = 0; it < 2; ++it) {
		vector<int> tmp;
		for (int i = 0; i < sol.size(); ++i) {
			auto it = lower_bound(tmp.begin(), tmp.end(), sol[i]);
			if (it == tmp.end())
				tmp.push_back(sol[i]);
			else
				*it = sol[i];
		}
		if (tmp.size() != b)
			NO();
		swap(a, b);
		reverse(sol.begin(), sol.end());
	}
	v.swap(sol);
	rev = !rev;
	if (rev)
		reverse(v.begin(), v.end());
	for (auto x : v)
		printf("%d ", x);
	return 0;
}

