int check(vector<int> A) {
    vector<int> v;
    for(int a: A) {
        auto itr=lower_bound(all(v), a);
        if(itr==v.end())v.push_back(a);
        else *itr=a;
    }
    return v.size();
}

bool solve(int N, int A, int B) {
    vector<int> As, Bs;
    if(A > N) return false;
    As.push_back(A);
    int sum = A;
    int nxt_a = A;
    int nxt_b = B - 1;    
    while(sum < N) {
        if(nxt_a == 0 and nxt_b == 0) return false;
        int left = N - sum;
        if(left > 0 and nxt_b > 0) {
            int v = min(nxt_b, left);
            Bs.push_back(v);
            sum += v;
            nxt_a--;
        }
        left = N - sum;
        if(left > 0 and nxt_a > 0) {
            int v = min(nxt_a, left);
            As.push_back(v);
            sum += v;
            nxt_b--;
        }
    }
    if(B > 1 and Bs.size() == 0) return false;
    if(B > 1 and Bs[0] != B - 1) return false;
    if(As.size() > B or Bs.size() > A) return false;
    vector<int> ans;
    int l = 1, r = N;
    rep(i, max(As.size(), Bs.size())) {
        if(i < As.size()) {
            for(int a = l + As[i] - 1; a >= l; a--) ans.push_back(a);
            l += As[i];
        }
        if(i < Bs.size()) {
            for(int b = r - Bs[i] + 1; b <= r; b++) ans.push_back(b);
            r -= Bs[i];
        }
    }
    assert(ans.size() == N);
    reverse(all(ans));

    // assert(check(ans) == A);
    // auto ans2 = ans;
    // rep(i, ans2.size()) ans2[i] *= -1;
    // assert(check(ans2) == B);

    rep(i, ans.size()) {
        cout << ans[i] << (i == ans.size() - 1 ? "\n" : " ");
    }
    return true;
}

