    vector<int> As, Bs;
    if(B > N) return false;
    Bs.push_back(B);
    int sum = B;
    int nxt_a = A - 1;
    int nxt_b = B;    
    while(sum < N) {
        if(nxt_a == 0 and nxt_b == 0) return false;
        int left = N - sum;
        if(left > 0 and nxt_a > 0) {
            int v = min(nxt_a, left);
            As.push_back(v);
            sum += v;
            nxt_b--;
        }
        left = N - sum;
        if(left > 0 and nxt_b > 0) {
            int v = min(nxt_b, left);            
            Bs.push_back(v);
            sum += v;
            nxt_a--;
        }
    }
    if(A > 1 and As.size() == 0) return false;
    if(A > 1 and As[0] != A - 1) return false;
    if(As.size() > B or Bs.size() > A) return false;
    vector<int> ans;
