void compress(vector<ll> &v){
    ll N = v.size(), mn = LINF;
    vector<pair<ll,int>> a(N);
    for(int i=0; i<N; ++i){
        a[i].first = v[i];
        a[i].second = i;
        mn = min(mn, v[i]);
    }
    sort(a.begin(), a.end());

    int prev = mn-1, n = -1;
    for(int i=0; i<N; ++i){
        if(a[i].first == prev) v[a[i].second] = n;
        else{
            n++;
            prev = a[i].first;
            v[a[i].second] = n;
        }
    }
}

void Main(){
    ll N,A,B; cin >> N >> A >> B;

    if(!(A+B<=N+1 && A*B>=N)){
        cout << -1 << en;
        return;
    }

    auto f = [&](ll i, ll j){return i*A+j;};
    VL ans; REP(i,B) ans.push_back(f(B-1-i,0));
    N -= B;

    if(A>1){
        REP(i,N%(A-1)){
            REP(j,(N+A-2)/(A-1)) ans.push_back(f(B-1-j,i+1));
        }

        FOR(i,N%(A-1),A-1){
            REP(j,N/(A-1)) ans.push_back(f(B-1-j,i+1));
        }
    }

    N += B;
    compress(ans);
    REP(i,N) cout << ans[i]+1 << en;
    return;
}

