	const int INF = 1e9;
	vector<int> dp(n, INF);
	for(size_t i = 0; i < n; i++){
		*lower_bound(dp.begin(), dp.begin() + n, x[i]) = x[i]; // a_i < a_j
	}
	return vector<int>(dp.begin(), std::lower_bound(dp.begin(), dp.begin() + n, INF));
}

