int LIS(vi as) {
    int n = as.size();
    vi dp(n + 1, 1e9);
    for (int a : as) {
        *lower_bound(dp.begin(), dp.end(), a) = a;
    }
    for (int i = 0; i <= n; i++) {
        if (dp[i] == 1e9) return i;
    }
    return -1;
}

int LDS(vi as) {
    reverse(as.begin(), as.end());
    return LIS(as);
}

int main() {
