		if (c != 0)prev[i] = pos[c - 1];
	}

	vi ret;

	int p = pos[lower_bound(ALL(dp), INF) - dp.begin() - 1];


	while (p != -1) {
		ret.push_back(v[p]);
		p = prev[p];
	}
	reverse(ALL(ret));
	return ret;

}

