	if( A+B < N || N+1 < A+B ){
		cout << -1 << endl;
		return;
	}
	vector<int> ans(N,0);
	if( A+B==N+1 ){//A
		for(int i=0;i<B-1;++i){
			ans[i] = N-i;
		}
		for(int i=0;i<A;++i){
			ans[B-1+i] = i+1;
		}
	}else{//A+B==N
		if(A==1||B==1){
		cout << -1 << endl;
		return;
		}

		bool flag = false;
		if( A<B ){
			flag = true;
			swap(A,B);
		}

		for(int i=0;i<A-1;++i){
			ans[i] = B+1+i;
