		ans[N-1] = N;
		ans[A-1] = 1;
		for(int i=2;i<=B;++i){
			ans[A+i-2] = B-i+2;
		}
		if(flag){
		for(int i=0;i<N/2;++i){
			swap(ans[i],ans[N-1-i]);
		}
		}
	}


	//output
	for(int i=0;i<N;++i){
		if( i ) cout << " ";
