using namespace std;
const int N=4e5+5;
int n,a,b,s[N],f1[N],f2[N];
bool check()
{
    int ans1=0,ans2=0;
    for(int i=1;i<=n;i++)
    {
        f1[s[i]]=max(f1[s[i]-1]+1,1);
        f2[s[i]]=max(f2[s[i]+1]+1,1);
        ans1=max(ans1,f1[s[i]]);
        ans2=max(ans2,f2[s[i]]);
    }
    return ans1==a&&ans2==b;
}
void solve()
{
    int tot=0;
    for(int i=n-a+1;i<=n;i++)
        s[++tot]=i;
    n-=a;
    b--;
    if(b==0)
    {
        if(n==0)
            for(int i=1;i<=tot;i++)
            printf(i==tot?"%d\n":"%d ",s[i]);
        else printf("-1\n");
        return;
    }
    int len=n/b;
    for(int i=1;i<=n%b;i++)
    {
        for(int i=n-(len+1)+1;i<=n;i++)
            s[++tot]=i;
        n-=len+1;
    }
    for(int i=1;i<=b-n%b;i++)
    {
        for(int i=n-len+1;i<=n;i++)
            s[++tot]=i;
        n-=len;
    }
    n=tot;
    if(!check()) printf("-1\n");
    else for(int i=1;i<=n;i++)
        printf(i==n?"%d\n":"%d ",s[i]);
}
