	if (A == 1 && B == N) {
		REP(i,N) cout << N - i << " ";
		cout << endl;
		return 0;
	}

	if (B == 1 && A == N) {
		REP(i,N) cout << i + 1 << " ";
		cout << endl;
		return 0;
	}

	if (A + B == N + 1) {
		REP(i,A - 1) cout << i + 1 << " ";
		REP(i,B) cout << N - i << " ";
		cout << endl;
		return 0;
	}

	ll L = N - A - B + 2;
	if (A >= L && B >= L) {
		REP(i,A - 1) cout << i + 1 << " ";
		REP(i,B - 1) cout << N - i << " ";
		for (ll i = A; i <= N - (B - 1); i++) {
			cout << i << " ";
		}
		cout << endl;
		return 0;
	}

	/******/
	L --;
	ll a = 1, b = 1;
	for (ll i = 1; i * i <= L; i++) {
		if (L % i == 0) {
			a = i;
			b = L / i;
			if (a < A && b < B) break;
		}
	}

	if (!(a < A && b < B)) {
		goto finish;
		return 0;
	}

	vector < ll > left_t;
	for (ll i = A; i <= N - B; i++) {
		left_t.push_back(i);
	}
	for (ll i = b - 1; i >= 0; i--) {
		for (ll j = i * a; j < (i + 1) * a; j++) {
			cout << left_t[j] << " ";
		}
	}
	REP(i,A - 1) cout << i + 1 << " ";
	REP(i,B) cout << N - i << " ";
	cout << endl;

	finish:;

	a = -1, b = -1;
	for (ll i = 1; i * i <= N; i++) {
		a = N / i + (N % i > 0 ? 1 : 0);
		b = i;
		if (a == A && b == B) {
			for (ll i = 0; i < a; i++) {
				for (ll j = min((i + 1LL) * b - 1LL, N); j >= i * b; j--) {
					cout << j + 1 << " " << endl;
				}
			}
			cout << endl;
			return 0;
		}
		if (b == A && a == B) {
			for (ll i = a; i >= 1; i --){
				for (ll j = (i - 1) * b; j < i * b; j--) {
					cout << j + 1 << " ";
				}
			}
			cout << endl;
			return 0;
		}
	}

	cout << - 1 << endl;

	return 0;
}

