int i,j,k,l,s,n,m,A,B,ans;
struct node {
	int x,y;
}Ans[N];
int main() {
	scanf("%d%d%d",&n,&A,&B);
	if (1ll*A*B<n) return puts("-1"),0;	
	if (A+B-1>n) return puts("-1"),0;
	if (B==1&&A==n) {
		for (i=1;i<=n;i++) printf("%d ",i); return 0;
	}
	if (B==1) return puts("-1"),0;
	Ans[ans=1].x=n-A+1,Ans[1].y=n;
	n-=A; B--;
	while (n%B) Ans[++ans].x=n-(n/B),Ans[ans].y=n,n-=(n/B)+1,B--;
	int gt=n/B;
	for (i=1;i<=B;i++) Ans[++ans].x=n-(gt)+1,Ans[ans].y=n,n-=(gt);
	for (i=1;i<=ans;i++) for (j=Ans[i].x;j<=Ans[i].y;j++) printf("%d ",j);
}

