using namespace std;

string solve(int n, int m, int a, int b, bool mode) {
  if (n == 1) {
    if (a > 0 && b > 0) {
      if (mode)
        return to_string(m);
      else
        return "1";
    } else {
      return "-1";
    }
  }
  if ((b < n && a == 1) || (a < n && b == 1)) {
    return "-1";
  }
  if (a + b > n + 1)
    return "-1";
  vector<int> vl, vr;
  for (int i = 0; i < a; i++) {
    vl.push_back(n - a + i + 1);
  }
  for (int i = 0; i < b - 1; i++) {
    // [n - a - b, n - a - 1]
    vr.push_back(n - a + 2 - b + i);
  }
  if (mode) {
    for (int i = 0; i < vl.size(); i++)
      vl[i] = m - vl[i] + 1;
    for (int i = 0; i < vr.size(); i++)
      vr[i] = m - vr[i] + 1;
  }
  if (n - a - b + 1 == 0) {
    string ret = "";
    ret += to_string(vl[0]);
    for (int i = 1; i < vl.size(); i++)
      ret += " " + to_string(vl[i]);
    for (int i = 0; i < vr.size(); i++)
      ret += " " + to_string(vr[i]);
    return ret;
  }
  string middle = solve(n - a - b + 1, n, a - 1, b - 1, mode);
  if (middle == "-1")
    return "-1";
  string ret = "";
  ret += to_string(vl[0]);
  for (int i = 1; i < vl.size(); i++) {
    ret += " " + to_string(vl[i]);
  }
  ret += " " + middle;
  for (int i = 0; i < vr.size(); i++)
    ret += " " + to_string(vr[i]);
  return ret;
}

int main() {
  int n, a, b;
  cin >> n >> a >> b;
  if (a > b)
    cout << solve(n, n, a, b, false) << endl;
  else
    cout << solve(n, n, b, a, true) << endl;
  return 0;
}

