      }
      break;
    }
    if (a<=0 || b<=0) {
      cout << -1 << endl;
      return 0;
    }
    for (int i=top-a+1; i<=top; ++i) ans.push_back(i);
    for (int i=bottom+b-1; i>=bottom; --i) ans.push_back(i);
    n-=(a+b);
    top-=a; bottom+=b;
    a--; b--;
  }
