	if (N + 1 == A + B) {
		vector<int>ans;
		for (int i = 0; i < B - 1; ++i) {
			ans.push_back(N - i);
		}
		for (int j = B - 1; j < N; ++j) {
			ans.push_back(j - (B - 1) + 1);
		}
		print(ans);
		return 0;
	}
	if (A * B >= N && A + B <= N + 1) {
		vector<vector<int>>pack;
		pack.push_back(vector<int>());
		for (int i = 0; i < N; ++i) {
			pack.back().push_back(i + 1);
			if (pack.back().size() == A) {
				pack.push_back(vector<int>());
			}
		}
		int chomp = B - (int)pack.size();
		vector<vector<int>>rev;
		while (pack.size()) {
			vector<int>vec = pack.back();
			while (chomp > 0) {
				rev.push_back(vector<int>(1, vec.back()));
				vec.pop_back();
				--chomp;
			}
			if (vec.size()) {
				rev.push_back(vec);
			}
			pack.pop_back();
		}
		assert(chomp == 0);
		vector<int>ans;
		for (auto& elm : rev) {
			for (int x : elm) {
				ans.push_back(x);
			}
		}
		print(ans);
		return 0;
	}
	cout << "-1" << endl;
	return 0;
}

