template<typename T>
class compress_fn_t {
public:
  void add(T x) {
    if (! map_.count(x))
      map_[x] = 0;
  };

public:
  void clear() {
    map_.clear();
  };

public:
  std::pair<std::map<T, int>, std::vector<T>> get() {
    int size = map_.size(), i = 0;

    std::pair<std::map<T, int>, std::vector<T>> pair;

    pair.second.resize(size);

    for (auto& kv : map_) {
      kv.second = i;

      pair.second[i] = kv.first;

      i ++;
    }

    pair.first = map_;

    return std::move(pair);
  };

private:
  std::map<T, int> map_;
};


int main(int argc, char** argv)
{
  std::cin.tie(0);
  std::ios_base::sync_with_stdio(0);

  std::cout << std::fixed << std::setprecision(6);

  long long N, A, B;

  std::cin >> N >> A >> B;

  if (N < A + B - 1 || N > A * B) {
    std::cout << -1 << std::endl;

    return 0;
  }

  std::vector<std::pair<int, long long>> a;

  bool used[333333] = {0};

  int i;

  long long j;

  for (i = 0, j = A * B - A + 1; j >= 1; i ++, j -= A) {
    if (i == 0) {
      for (int k = 0; k < A; k ++) {
        a.emplace_back(i, j + k);

        if (j + k <= N)
          used[j + k] = true;
      }
    }
    else {
      a.emplace_back(i, j);

      if (j <= N)
        used[j] = true;
    }
  }

  for (int i = 1; a.size() < N; i ++)
    if (! used[i])
      a.emplace_back(B - (i - 1) / A - 1, i);

  std::sort(ALL(a));

  compress_fn_t<long long> fn;

  for (const auto& pair : a)
    fn.add(pair.second);

  auto map = fn.get().first;

  for (const auto& pair : a)
    std::cout << map[pair.second] + 1 << ' ';
  std::cout << std::endl;

  return 0;
}

