int dpa[15], dpb[15];
pii solve(vector<int> perm) {
    memset(dpa, 0, sizeof(dpa));
    memset(dpb, 0, sizeof(dpb));

    int N = perm.size();
    for(int i=0; i<N; i++) {
        int maa = 0, mab = 0;
        for(int j=0; j<i; j++) {
            if(perm[j] < perm[i]) chmax(maa, dpa[j]);
            if(perm[j] > perm[i]) chmax(mab, dpb[j]);
        }
        dpa[i] = maa + 1;
        dpb[i] = mab + 1;
    }
    int ra = *max_element(dpa, dpa+N);
    int rb = *max_element(dpb, dpb+N);
    return make_pair(ra, rb);
}

signed main() {
    int N, A, B; cin >> N >> A >> B;
    int div = (N + B - 1) / B;
    if(div != A) cout << -1 << endl;
    else {
        // printf("div = %lld\n", div);
        vector<int> ans;
        int sum = 0;
        int mo = N % B;
        if(mo * div + (N - mo) * (div - 1) != N) {
            cout << -1 << endl;
            return 0;
        }

        for(int i=0; i<B; i++) {
            int bucket = div;
            if(i < mo) bucket--;
            // printf("N = %lld, A = %lld, B = %lld\n", N, A, B);
            // printf("mo = %lld, div = %lld, bucket = %lld\n", mo, div, bucket);
            int base = N - sum - (bucket - 1);
            for(int k=0; k<bucket; k++) {
                ans.push_back(base + k);
            }
            sum += bucket;
        }

        for(int i=0; i<N; i++) {
            printf("%lld%c", ans[i], (i+1 == N ? '\n' : ' '));
        }
        assert(sum == N);
    }
    return 0;
}

