class UnionFind
{
public:
    vector<ll> Parent;

    UnionFind(ll N)
    {
        Parent = vector<ll>(N, -1);
    }
    ll find(ll A)
    {
        if (Parent[A] < 0)
            return A;
        return Parent[A] = find(Parent[A]);
    }

    ll size(ll A)
    {
        return -Parent[find(A)];
    }

    bool Union(ll A, ll B)
    {
        A = find(A);
        B = find(B);
        if (A == B)
        {
            return false;
        }
        if (size(A) < size(B))
            swap(A, B);

        Parent[A] += Parent[B];
        Parent[B] = A;

        return true;
    }
};

ll gcd(ll a, ll b)
{
    if (b == 0)
        return a;
    return gcd(b, a % b);
}

ll lcm(ll a, ll b)
{
    ll g = gcd(a, b);
    return a / g * b;
}

ll mulMod(ll a, ll b)
{
    return (((a % MOD) * (b % MOD)) % MOD);
}

ll powMod(ll a, ll p)
{
    if (p == 0)
    {
        return 1;
    }
    else if (p % 2 == 0)
    {
        ll half = powMod(a, p / 2);
        return mulMod(half, half);
    }
    else
    {
        return mulMod(powMod(a, p - 1), a);
    }
}

ll ceil(ll a, ll b)
{
    return (a + b - 1) / b;
}

void solve(long long N, long long A, long long B)
{
    if (A + B > N + 1)
    {
        cout << -1 << endl;
        return;
    }
    if (A * B < N)
    {
        cout << -1 << endl;
        return;
    }
    ll S = N - A;
    vector<int> ans(N);
    ll cur = N;
    for (int i = 0; i < A; i++)
    {
        int num = min(B - 1, S) + 1;
        S -= num - 1;
        for (int j = 0; j < num; j++)
        {
            ans.push_back(cur-num+1+j);
        }
        cur -= num;
    }

    reverse(ans.begin(),ans.end());

    for (int i = 0; i < N; i++)
    {
        cout << ans[i] << endl;
    }

}

