int n,A,B;
int tot;

int L,R;

void dec()
{
	int x=L+B-1;L=x+1;
	for(int tmp=B;tmp--;)s[++tot]=x,x--;
}
void inc()
{
	int x=R-A+1;R=x-1;
	for(int tmp=A;tmp--;)s[++tot]=x,x++;
}

bool solve()
{
	if(A+B>n+1)return 0;

	tot=0;
	while(tot<n)
	{
		if(!B)return 0;
		dec(),A--;
		if(tot==n)break;

		if(!A)return 0;
		inc(),B--;
	}

	return 1;
}

