			*iter++ = i+1;
		}

		int32_t rem = N - (iter - res);
		if (rem > (Dec - 1)*(Inc - 1)) {
			out << -1 << endl; return 0;
		}

		int32_t bottom = Dec;
		while (iter < (res + N)) {
			auto iter_last = iter;
			iter += (Dec - 1);
			iter = std::min(res + N, iter);
			auto iter_next = iter;
			for (int32_t i = 0; i < Dec-1 && iter_last<iter; i++)
			{
