void impossible(ll n, ll incr, ll decr)
{
    if (incr + decr > n + 1LL) {
        cout << -1;
        exit(0);
    }

    ll incr_nlen = n - decr;
    ll floor = incr_nlen / decr;
    ++floor; if (incr_nlen % decr) ++floor;

    if (incr < floor) {
        cout << -1;
        exit(0);
    }
}

void simple(ll n, ll incr, ll decr)
{
    if (decr == 1LL) {
        rep (i0, n) {
            ll i = i0 + 1LL;
            cout << i << (i == n ? "" : " ");
        }
        exit(0);
    }

    if (incr == 1LL) {
        rrep (i0, n) {
            ll i = i0 + 1LL;
            cout << i << (i == 1LL ? "" : " ");
        }
        exit(0);
    }
}

void make_decr(ll anslist[], ll n, ll decr)
{
    ll val = n - decr;
    rrep (i, n) {
        anslist[i] = ++val;
        if (val >= n) break;
    }
    debug_printf("---- anslist 1\n"); debug_print(anslist, n);
}

void make_incr(ll anslist[], ll n, ll incr, ll decr)
{
    ll remove_count = (n - decr + 1LL) - incr;
    int idx = 0;
    ll val = 1LL;

    while (remove_count) {
        debug_printf("xx1\n");
        if (remove_count >= decr - 1LL) {
            debug_printf("xx2\n");
            srep (i, idx, idx + decr) anslist[i] = ((idx + decr) + val - 1LL) - i;
            remove_count -= (decr - 1LL);
            idx += decr;
            val += decr;
        }
        else {
            debug_printf("xx3\n");
            ll width = remove_count + 1LL;
            srep (i, idx, idx + width) anslist[i] = ((idx + width) + val - 1LL) - i;
            remove_count -= (width - 1LL);
            idx += width;
            val += width;
        }
    }

    debug_printf("---- idx=%lld incr=%lld\n", idx, incr);
    srep (i, idx, n - decr) anslist[i] = val++;

    debug_printf("---- anslist 2\n"); debug_print(anslist, n);
}

