            ans[i]=N+i-(A-1);
        }
        REP(i,A-1,N-1){
            ans[i]=N-i;
        }
        ans[N-1]=N;
    }else{
        REP(i,0,A-1){
            ans[i]=N+i-(A-1);
        }
        ans[A-1]=1;
        ans[A]=N;
        REP(i,A+1,N){
            ans[i]=N-i+1;
        }
    }
    if(rev){
        RREP(i,1,N){
            cout<<ans[i]<<" ";
        }
        p(ans[0]);
    }else{
        REP(i,0,N-1){
            cout<<ans[i]<<" ";
        }
        p(ans[N-1]);
    }
    return 0;
}

