template<class H, class... Ts> vi rsortti(vector<H> head, vector<Ts>... tails) {    vi ind = iota(0, sz(head));    auto vec = make_vt(head, tails..., ind);    rsort(vec);    auto rets = take_vt(vec);    return get<sizeof...(tails) + 1>(rets);}
