	out.tie(nullptr);

	in >>N>> Inc>>Dec;

	if (N < Inc + Dec - 1) {
		out << -1 << endl; return 0;
	}
	else if (Inc==1 || Dec==1) {
		if (Inc == 1) {
			if (N == Dec) {
				out << Dec;
				for (int32_t i = Dec-1; i >= 1; --i) {
					out << ' ' << i;
				}
				out << endl;
			}
			else {
				out << -1 << endl;
			}
		}
		else {
			if (N == Inc) {
				out << 1;
				for (int32_t i = 2; i <= Inc; i++)
				{
					out << ' ' << i;
				}
				out << endl;
			}
			else {
				out << -1 << endl;
			}
		}
		return 0;
	}
	else
	{
		for (int32_t i = Inc-1; i >= 0 ; --i)
		{
			*iter++ = N - i;
		}
		for (int32_t i = Dec - 2; i >= 0; --i)
		{
			*iter++ = i+1;
		}

		int32_t rem = N - (iter - res);
		if (rem > (Dec - 1)*(Inc - 1)) {
			out << -1 << endl; return 0;
		}

		int32_t bottom = Dec;
		while (iter < (res + N)) {
			auto iter_last = iter;
			iter += (Dec - 1);
			iter = std::min(res + N, iter);
			auto iter_next = iter;
			for (int32_t i = 0; i < Dec-1 && iter_last<iter; i++)
			{
				*--iter = i + bottom;
			}
			iter = iter_next;
			//for (int32_t i = Dec - 1 - 1; iter != (res + N) && i >= 0; --i)
			//{
			//	*iter++ = i + bottom;
			//}
			bottom += Dec - 1;
			if (bottom >= N - (Inc - 1)) { break; }
		}

		out << res[0];
		for (int32_t i = 1; i < N; i++)
		{
			out << ' ' << res[i];
		}
		out << endl;
	}

	return 0;
}
