        reverse(ans, ans + n);
    }
    bool used[n + 1] = {};
    rep(i, n) {
        if (used[ans[i]] || ans[i] < 1 || n < ans[i]){
            cout << -1 << endl;
            return 0;
        }
        used[ans[i]] = true;
    }
    int dp[n + 1];
    fill(dp, dp + n + 1, INF);
    rep(i, n){
        *lower_bound(dp, dp + n + 1, ans[i]) = ans[i];
    }
    if (a != lower_bound(dp, dp + n + 1, INF) - dp){
        cout << -1 << endl;
        return 0;
    }
    reverse(ans, ans + n);
    fill(dp, dp + n + 1, INF);
    rep(i, n) {
        *lower_bound(dp, dp + n + 1, ans[i]) = ans[i];
    }
    if (b != lower_bound(dp, dp + n + 1, INF) - dp) {
        cout << -1 << endl;
        return 0;
    }
    reverse(ans, ans + n);
    rep(i, n) {
        if(i) cout << " ";
        cout << ans[i];
    }
    cout << endl;
    return 0;
}

