vector<ll> solve(ll N, ll A, ll B) {
    vector<ll> res;

    for (ll i = B - 1; i >= 0; i--) {
        res.push_back(i);
    }

    if (A == 1) {
        return res;
    }

    ll rem = N - B;
    ll p = rem / (A - 1);
    ll b = rem % (A - 1);
    ll c = A - 1 - b;

    for (ll i = 0; i < b; i++) {
        ll size = res.size();
        for (ll j = 0; j < p + 1; j++) {
            res.push_back(size + p - j);
        }
    }

    for (ll i = 0; i < c; i++) {
        ll size = res.size();
        for (ll j = 0; j < p; j++) {
            res.push_back(size + p - 1 - j);
        }
    }

    return res;
}

vector<ll> solve2(ll N, ll A, ll B) {
    vector<ll> res;

    for (ll a = 0; a < A; a++) {
        for (ll b = B - 1; b >= 0; b--) {
            ll i = b * A + a;
            if (i >= N) {
                continue;
            }
            res.push_back(b * A + a);
        }
    }

    return res;
}

