//変数
int N, A, B;
vector<int> ans;





//サブ関数
//入力
void input()
{
	cin >> N >> A >> B;
}

bool can(int N, int A, int B) {
	int big = max(A, B);
	int small = min(A, B);

	if (small == 1) {
		if (big == N)return true;
		else return false;
	}
	if (A + B >= N + 2)return false;

	N -= big;
	//cout << (double)N / (small - 1) << endl;
	if ((int)ceil((double)N / (small - 1)) <= big)return true;
	else return false;
}

//計算
void calc()
{
	if (!can(N, A, B)) {
		return;
	}
	if (min(A, B) == 1) {
		if (A > B) {
			REP(i, N) {
				ans.push_back(i + 1);
			}
		}
		else {
			REP(i, N) {
				ans.push_back(N - i);
			}
		}
	}
	else if (A + B == N + 1) {
		REP(i, A)ans.push_back(i + 1);
		REP(i, B)ans.push_back(N - i);
	}
	else {
		if (A < B) {

			FOR(i, N - B, N) {
				ans.push_back(i + 1);
			}
			N -= B;

			//残り
			int len = A - 1;
			int set = N / len;
			FOR(i, 1, set + 1) {
				REP(j, len) {
					ans.push_back(len*i - j);
				}
			}
			//余り
			for (int i = N; i > len*set; --i) {
				ans.push_back(i);
			}
			reverse(ans.begin(), ans.end());
		}
		else {
			REP(i, A) {
				ans.push_back(A - i);
			}
			N -= A;
			int len = B - 1;
			int set = N / len;
			FOR(i, 1, set + 1) {
				REP(j, len) {
					ans.push_back(N +1+ A - i * len + j);
				}
			}

			//余り
			for (int i = A + 1; i <= N+A - set * len; i++) {
				ans.push_back(i);
			}
			reverse(ans.begin(), ans.end());
		}
	}
}


//出力
void output()
{
	if (ans.size() == 0) {
		cout << "-1" << endl;
	}
	else {
		for (int num : ans) {
			cout << num << " ";
		}
		cout << endl;
	}
}


//デバッグ
void debug()
{
	int N;
	cin>>N;
}


//メイン関数
int main()
{
	input();
	calc();
	output();
	debug();

	return 0;
}

