std::deque<int> make_sequence(int N, int A, int B, int shift)
{
	if (A*B == N)
	{
		std::deque<int> deque;
		for (int i = 0; i < A; ++i)
		{
			for (int j = B; j > 0; --j)
			{
				deque.emplace_back(i*B + j + shift);
			}
		}
		return deque;
	}
	else if (A*(B - 1) >= N - 1)
	{
		auto deque = make_sequence(N - 1, A, B - 1, shift);
		deque.emplace_front(N + shift);
		return deque;
	}
	else if ((A - 1)*B >= N - 1)
	{
		auto deque = make_sequence(N - 1, A - 1, B, shift + 1);
		deque.emplace_front(shift + 1);
		return deque;
	}
	else
	{
		std::deque<int> deque;
		for (int i = 0; i < A - 1; ++i)
		{
			for (int j = B; j > 0; --j)
			{
				deque.emplace_back(i*B + j + shift);
			}
		}
		for (int j = N; j > A*B; --j)
		{
			deque.emplace_back(j);
		}
		return deque;
	}
}

