    for(ll inc=b+1;inc<=n;inc+=l){
      ll sf=min(inc+l-1,n);
      for(ll i1=inc,i2=sf;i1<=i2;i1++,i2--)swap(ans[i1],ans[i2]);
    }
    for(ll i=1;i<=n;i++)cout<<ans[i]<<" ";
    return 0;
}

