	for (int i = 1; i <= first; i++) {
		c[i] = i + n - first;
	}
	for (int i = 1; i <= n / a; i++) {
		for (int j = 1; j <= a; j++) {
			c[a * (i - 1) + j + first] = j + (n / a - i) * a;
		}
	}
