		if (first >= 1) {
			reverse(c + 1, c + first + 1);
			need -= first - 1;
		}
	} else {
		reverse(c + 1, c + need + 1);
		need = 0;
	}
	for (int i = 1; i <= n / a; i++) {
		if (!need) {
			break;
		}
		int f = first + a * (i - 1) + 1;
		if (need >= a - 1) {
			reverse(c + f, c + f + a);
			need -= a - 1;
		} else {
			reverse(c + f, c + f + need + 1);
			need = 0;
		}
	}
