        deq.push_back(i);
    }
    if (N > A * B || N < A + B - 1) {
        cout << -1 << endl;
        return 0;
    }
    int cnt = N;
    while (cnt > A) {
        vector<int> vec;
        for (int i = 0; i < B - 1 && cnt > A; i++) {
            vec.push_back(cnt);
            cnt--;
        }
        for (int i = 0; i < vec.size(); i++) {
            deq.push_front(vec[vec.size() - i - 1]);
        }
    }
    for (auto itr = deq.begin(); itr != deq.end(); ++itr) {
        int ans = *itr;
        if (flag) {
            ans = N - ans + 1;
        }
        cout << ans << " ";
