		cout << -1 << endl;
	}

	vector<int> blocks;
	blocks.push_back(B);
	REP(i, 0, A - 1) {
		blocks.push_back((N - B) / (A - 1));
	}
	int sum = accumulate(ALL(blocks), 0);
	int i = 1;
	while (sum < N) {
		++blocks[i];
		++sum;
		++i;
	}

	int mx = 0;
	vector<int> ans;
	for (int block : blocks) {
		int prev = mx;
		mx += block;
		REM(i, prev + 1, mx + 1) {
			ans.push_back(i);
		}
	}

	REP(i, 0, ans.size()) {
		cout << ans[i] << (i == ans.size() - 1 ? '\n' : ' ');
	}

 	return 0;
