		return 0;
	}

	if (A == 1 || B == 1)
	{
		if (A + B - 1 != N)
		{
			cout << -1 << endl;
			return 0;
		}
	}

	//! 増加部分
	for (size_t i = N - (A - 1); i <= N; i++)
	{
		cout << i << endl;
	}

	//! 減少部
	for (size_t i = (B - 1); i >= 1; i--)
	{
		cout << i << endl;
	}

	//! 増加部と減少部の長さが1になるように
	int max = N - A;
