using namespace std;

using ll = long long;
using p = pair<ll, ll>;

void out(vector<ll> v, bool rev) {
    if (rev) {
        for (ll i = v.size() - 1; i >= 0; i--) {
            cout << v[i] << " \n"[i == 0];
        }
    } else {
        for (ll i = 0; i < v.size(); i++) {
            cout << v[i] << " \n"[i == v.size() - 1];
        }
    }
}

int main(void) {
    cin.tie(0);
    ios::sync_with_stdio(false);

    ll N, A, B;
    cin >> N >> A >> B;

    vector<ll> ans;

    bool rev = B > A;
    if (rev) {
        swap(A, B);
    }

    for (ll i = N - A + 1; i <= N; i++) {
        ans.push_back(i);
    }

    if (N - A < B - 1) {
        cout << -1 << endl;
        return 0;
    }

    if (A == N) {
        out(ans, rev);
        return 0;
    }

    if (B == 1) {
        cout << -1 << endl;
        return 0;
    }

    if ((N - A) / (B - 1) + (((N - A) % (B - 1)) ? 0 : 1) > A) {
        cout << -1 << endl;
        return 0;
    }

    for (ll i = 0; i < (N - A) / (B - 1); i++) {
        for (ll j = (i + 1) * (B - 1); j > i * (B - 1); j--) {
            ans.push_back(j);
        }
    }

    if ((N - A) % (B - 1) != 0) {
        for (ll i = N - A; i >= N - A - N % (B - 1); i--) {
            ans.push_back(i);
        }
    }

    if (ans.back() <= 0) {
        cout << -1 << endl;
        return 0;
    }

    out(ans, rev);

    return 0;
}

