vector<int> solve(auto N, auto A, auto B) {
  if(N < A+B-1) return {-1};
  if(A*B < N)   return {-1};
  vector<int> res;
  vector<vector<int>> part(1);
  for(auto i=1; i<=N; ++i) {
    if(part.back().size()==B || N-i+1==A-part.size()) part.emplace_back(0);
    part.back().emplace_back(i);
  }
  if(part.front().size()!=B) return {-1};
  for(auto& i: part) reverse(begin(i), end(i));
  for(auto i: part) res.insert(end(res), begin(i), end(i));
  return res;
}
