            ans[2 * tempIdx + kosuu - 1 - i] = i + 1;
        }
        tempIdx += kosuu;
        a++;
    }
    int checkA = checkLIS(ans);
    reverse(ans.begin(), ans.end());
    int checkB = checkLIS(ans);
    reverse(ans.begin(), ans.end());
    if (checkA == A && checkB == B) {
        rep(i, N) cout << ans[i] << " ";
        cout << endl;
    } else {
        cout << -1 << endl;
    }

    return 0;
}

