// LIS and LDS
//
// verified:
//   ARC 091 E - LISDL
//     https://beta.atcoder.jp/contests/arc091/tasks/arc091_c
//

/*
    0 〜 N-1 の順列であって
    LIS (最長増加部分列) の長さが A
    LDS (最長減少部分列) の長さが B
    となるものを 1 つ求める


*/


#include <iostream>
#include <vector>
using namespace std;


// LIS and LDS
// A + B <= N+1, AB >= N are necessarily and sufficient
vector<long long> LISLDS(long long N, long long A, long long B) {
    vector<long long> res;
    for (long long i = B-1; i >= 0; --i) res.push_back(i);

    if (A == 1) return res;

    // 現在 B 個 使っているので残りの個数は N - B 個
    long long X = N - B;
    long long boxsize = (X+A-2)/(A-1); // box1つに入っている数値の個数
    long long lastboxsize ; // 最後の box に入っている数値の個数
    // cout << "boxsize = " << boxsize << endl;
    lastboxsize = X - boxsize*(A-2);
    // cout << "lastboxsize = " << lastboxsize << endl;
    // A-2個の箱には詰められるだけ詰めていく
    for(int i = 0 ; i < A-2 ;i++){
        int size = res.size();
        for(int j = 0 ; j < boxsize ; j++){
            // boxsize - 1 が最大
            res.push_back( size + boxsize - 1 - j);
            if(res.size()==N)return res;
        }
    }
    // 最後の箱には lastboxsize 詰めていく
    int size = res.size();
    for(int j = 0; j < lastboxsize ; j++){
        res.push_back(size + lastboxsize - 1 - j);
        if(res.size()==N)return res;
    }
    return res;
}

int main() {
    long long N, A, B; cin >> N >> A >> B;
    if (A + B > N+1 || A * B < N) cout << -1 << endl;
    else {
        vector<long long> res = LISLDS(N, A, B);
        for (int i = 0; i < res.size(); ++i) {
            cout << res[i] + 1;
            if (i != (int)res.size() - 1) cout << " ";
        }
        cout << endl;
    }
}

