class ELISDL {
public:
    void solve(std::istream& in, std::ostream& out) {
        int N, A, B;
        in >> N >> A >> B;
        if (N < A + B - 1) {
            out << -1 << "\n";
            return;
        }
        int top = N+1, bottom = 1;
        int diff = 0;
        vector<int> answer;
        while (top >= bottom) {
            if (A < B) {
                REP(i,top-A+diff,top) {
                    if (answer.size() == N) break;
                    answer.push_back(i);
                }
                top = top-A+diff;
                RREP(i,bottom,bottom+B-diff-1) {
                    if (answer.size() == N) break;
                    answer.push_back(i);
                }
                bottom = bottom+B-diff-1;
            } else {
                RREP(i,bottom,bottom+B-diff) {
                    if (answer.size() == N) break;
                    answer.push_back(i);
                }
                bottom = bottom+B-diff;
                REP(i,top-A+diff+1,top) {
                    if (answer.size() == N) break;
                    answer.push_back(i);
                }
                top = top-A+diff+1;
            }
            diff++;
        }
        if (answer.size() == N) {
            REP(i,0,N) {
                out << answer[i] << (i == N-1 ? "\n" : " ");
            }
        } else {
            out << -1 << "\n";
            return;
        }
    }
};


