    rep1(i, L) ans.pb(i);
    ll tp;
    for (ll i = L + 1; i <= N; ++i){
        if((i - L - 1) % B == 0) L += B, tp = min(L, N);
        ans.pb(tp);
        --tp;
    }
    for(auto a : ans) cout << a << " ";
    print("");

    return 0;
}

