vector<int> solve(int n, int a, int b) {
    if (1ll * a * b < n || a + b - 1 > n)
        return vector<int>();
    vector<int> ans;
    int cn = n - a + 1;
    insrange(ans, cn, n + 1);
    for (int i = 1; i < b; i++) {
        int left = n - ans.size();
        if (left == b - i) {
            insrange(ans, cn - 1, cn);
            cn--;
        } else if (b - i - 1 + a <= left) {
            insrange(ans, cn - a, cn);
            cn -= a;
        } else {
            insrange(ans, b - i, cn);
            cn = b - i;
        }
    }
    return ans;
}

