int main()
{
  scanf( "%d%d%d", &N, &A, &B );

  if( N < A+B-1 || N > A*B )
  { puts("-1"); return 0; }

  int p = A*B;
  for( int i = A-1; i < A*B; i += A )
  {
    rep( j, A )
      vs.push_back( p-(A-1-j) );

    p -= A;
  }

  //show(vs);

  std::vector<int> ans( vs.begin(), vs.begin()+A );
  int rest = N-(A+B-1);
  for( int i = A; i < A*B; i += A )
  {
    ans.push_back( vs[i] );

    rep( j, A-1 ) if( rest > 0 )
      ans.push_back( vs[i+j+1] ), --rest;
  }

  //show(ans);

  std::vector<int> sorted = ans;
  std::sort( sorted.begin(), sorted.end() );

  std::map<int, int> m;

  rep( i, sorted.size() )
    m[sorted[i]] = i+1;

  rep( i, ans.size() )
    printf( "%d%c", m[ans[i]], i==ans.size()-1?'\n':' ' );

  return 0;
}

