int main(){
  ll n,a,b;
  cin>>n>>a>>b;
  if(a*b<n||a+b-1>n){
    cout<<-1<<endl;
    return 0;
  }
  ll fn=n;
  n=a*b;
  int cnt=0;
  for(int i=n-a;i>=0;i-=a,cnt++){
    for(int j=i+1;j<=i+a;j++){
      vec[cnt].push_back(j);
    }
  }


  ll dec=n-fn;
  for(int i=cnt-1;i>0;i--){
    int kn=vec[i].size()-1;
    while(kn>0&&dec>0){
      vec[i].pop_back();
      dec--;
      kn--;
    }
  }
  vector<ll> ans;
  for(int i=0;i<cnt;i++){
    for(int j=0;j<vec[i].size();j++) ans.push_back(vec[i][j]);
  }
  out(ans,fn);
}

