class ELISDL {
public:
    int LDS(vector<int>& seq)
    {
        int n = seq.size();

        // Create an 2D array of integer
        // for tabulation
        vector<vector<int> > L(n + 1, vector<int>(n + 1));

        // Take the second sequence as the sorted
        // sequence of the given sequence
        vector<int> sortedseq(seq);

        sort(sortedseq.begin(), sortedseq.end(), greater<int>());

        // Classical Dynamic Programming algorithm
        // for Longest Common Subsequence
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 || j == 0)
                    L[i][j] = 0;

                else if (seq[i - 1] == sortedseq[j - 1])
                    L[i][j] = L[i - 1][j - 1] + 1;

                else
                    L[i][j] = max(L[i - 1][j], L[i][j - 1]);
            }
        }

        // Return the ans
        return L[n][n];
    }
    int LIS(vector<int>& seq)
    {
        int n = seq.size();

        // Create an 2D array of integer
        // for tabulation
        vector<vector<int> > L(n + 1, vector<int>(n + 1));

        // Take the second sequence as the sorted
        // sequence of the given sequence
        vector<int> sortedseq(seq);

        sort(sortedseq.begin(), sortedseq.end());

        // Classical Dynamic Programming algorithm
        // for Longest Common Subsequence
        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= n; j++) {
                if (i == 0 || j == 0)
                    L[i][j] = 0;

                else if (seq[i - 1] == sortedseq[j - 1])
                    L[i][j] = L[i - 1][j - 1] + 1;

                else
                    L[i][j] = max(L[i - 1][j], L[i][j - 1]);
            }
        }

        // Return the ans
        return L[n][n];
    }

    void solve(std::istream& cin, std::ostream& cout, std::ostream& cerr) {
    int N, A, B;
    cin >> N >> A >> B;
    if(A + B != N && A + B != N+1)BYE("-1");
    if(A < 1 || B < 1)BYE("-1");
    if(A + B == N + 1){
        if(A == 1){
            FOR(i,N+1,1)cout << i << " ";
        }
        else if(B == 1){
            FOR(i,1,N+1)cout << i << " ";
        }
        else{
            cout << 1 << " ";
            FOR(i,N-A+2,N+1)cout << i << " ";
            FOR(i,N-A+2,2)cout << i << " ";
        }
    }
    if(A + B == N){
        if(A == 1 || B == 1)BYE("-1");
        cout << 2 << " ";
        FOR(i,N-A+2,N+1)cout << i << " ";
        cout << 1 << " ";
        FOR(i,N-A+2,3)cout << i << " ";
    }
}


};


