int main(){
    int N, A, B;
    cin >> N >> A >> B;
    if(!(N <= A * B && A + B - 1 <= N)){
        cout << -1 << endl;
        return 0;
    }
    vector<int> v[B];
    int low = 1, up = N;
    for(int i = B - 1; 0 <= i; i--){
        v[i].push_back(B - i);
        low = B - i;
    }
    for(int i = N; v[0].size() < A; i--){
        v[0].push_back(i);
        up = i;
    }
    sort(v[0].begin(), v[0].end());
    int index = B - 1;
    for(int i = low + 1; i < up; i++){
        v[index].push_back(i);
        index--;
        if(!index) index = B - i;
    }
    for(int i = 0; i < B; i++) for(int u : v[i]) cout << u << " ";
    cout << endl;
    return 0;
}

