    vector<ll> a = b;
    rep(i, a.size()) {
        a[i] *= -1;
    }
    // dp[i][len] = [0, i]のから取れる長さlenのLISを想定した時、その最後の要素として考えられる最小の値
    // iはdpテーブルを使い回している
    vll dp; dp.reserve(100000);
    rep(i, a.size()) {
        auto it = lower_bound(all(dp), a[i]);
        if (it == dp.end()) 
            dp.pb(a[i]);
        else
            *it = a[i];
    }
    return dp.size();
}

vvll used;
void brutal(ll n) {
    used=vvll(n+1,vll(n+1));
    vll id(n);
    map<P, vll> memo;
    rep(i, n) {
        id[i] = 1+i;
    }
    do {
        chmax(memo[P(LISa(id),LISd(id))], id);
    } while (next_permutation(all(id)));
    for (auto x : memo) {
        used[x.fi.fi][x.fi.se] = 1;
        if (x.fi.fi >= x.fi.se)
            cout << x.fi << " " << x.se << endl;
    }
    rep(i, n+1) {
        rep(j,n+1){
            cout << used[i][j];
        }
        cout << endl;
    }

}

vll solve(ll n, ll a, ll b) {
    if (a+b>n+1) {
        return {-1};
    }
    bool swapped = 0;
    if (b > a) swap(a, b), swapped = 1;

    ll b0 = (n + a - 1) / a;
    ll rem = (n % a == 0 ? a : n % a);
    vll r;
    for (ll i = n; rem; i--, rem--) {
        r.pb(i);
    }
    reverse(all(r));
    if (b - b0 < 0) {
        return {-1};
    }
    if (b-b0+1 > r.size()) {
        return {-1};
    }
    reverse(r.begin(), r.begin()+b-b0+1);
    vll ret;
    rep(i, r.size()) {
        ret.pb(r[i]);
    }
    rep(i, b0-1) {
        rep(j, a) {
            ret.pb((b0-2-i)*a+j+1);
        }
    }

    if (swapped) {
        rep(i, ret.size()) {
            ret[i] = n+1-ret[i];
        }
        swap(a, b);
    }

    if (LISa(ret) != a || LISd(ret) != b) {
        cout << "##########################################" << endl;
        cout << n << " " << a << " " << b << endl;
    }
    return ret;
}

