			v.push_back(p*i-j);
			x = max(x,p*i-j);
		}
	}
	++p;
	for(i=1ll; i<=q; ++i){
		for(j=0; j<p; ++j){
			v.push_back(x+p*i-j);
		}
	}
	for(i=0ll; i<b; ++i){
		v.push_back(n-i);
	}
	for(i=0; i<n; ++i){
		cout << ((i)?" ":"") << v[i];
	}
	cout << endl;
	return 0;
}

