	{
		cout << "-1" << endl;
		return 0;
	}
	if (A == 1)
	{
		if (B == N)
		{
			REP(i, N) cout << (i ? " " : "") << (N - i);
			cout << endl;
		}
		else
		{
			cout << -1 << endl;
		}
		return 0;
