	{
		if (A == N)
		{
			REP(i, N) cout << (i ? " " : "") << (i + 1);
			cout << endl;
		}
		else
		{
			cout << -1 << endl;
		}
		return 0;
	}

	int need = A + B - 1;

	if (need > N)
	{
		cout << -1 << endl;
		return 0;
	}

	int crap = N - need;

	if (ceil(crap / (double)(A - 1)) <= B - 1)
	{
		for (int i = 0; i < crap; i++)
		{
			int t = i / (A - 1);
			int a = i % (A - 1);
			if (crap < (A - 1) * (t + 1))
			{
				int b = ((A - 1) * t);
				int n = A + i - b;
				cout << (i ? " " : "") << (n + 1);
			}
			else
			{
				int n = (N - (B - 1)) - ((A - 1) * t) - ((A - 1) - a);
				cout << (i ? " " : "") << (n + 1);
			}
		}
	}
	else if (ceil(crap / (double)(B - 1)) <= A - 1)
	{
		for (int i = 0; i < crap; i++)
		{
			int t = i / (B - 1);
			int a = i % (B - 1);
			if (crap < (A - 1) * (t + 1))
			{
				int r = crap - i;
				int n = (N - B) - r;
				cout << (i ? " " : "") << n;

			}
			else
			{
				int n = (A + 1) + ((B - 1) * t) + a;
				cout << (i ? " " : "") << n;
			}
		}
	}
	else
	{
		cout << "-1" << endl;
		return 0;
	}

	for (int i = 0; i < B - 1; i++)
	{
		cout << " " << (N - i);
	}

	for (int i = 0; i < A; i++)
	{
		cout << " " << (i + 1);
	}
}

