int T, A, B, N,zost,i,j,pud,ilezw,ilenor;

int main()
{
    T=1;
    while(T)
    {
        cin >> N >> A >> B;
        if ((long long)A*B<(long long)N || A + B - 1>N)
        {
            cout << -1<<endl;
            T--;
            continue;
        }
        if (B == 1)
        {
            for (i = 1; i <= N; i++)
                cout << i << " ";
            cout << endl;
            T--;
            continue;
        }
        for (i = 1; i <= A; i++)
            cout << N - A + i << " ";
        zost = N - A;
        pud = zost / (B - 1);//ile w pudelku
        ilezw = zost % (B - 1);//ile zwiekszonych pudelek o jeden
        for (i = 1; i <= ilezw; i++)
        {
            for (j = 1; j <= pud + 1; j++)
                cout << zost - (pud + 1) + j << " ";
            zost -= (pud + 1);
        }


        ilenor = B - 1 - ilezw;

        for (i = 1; i <= ilenor; i++)
        {
            for (j = 1; j<=pud; j++)
                cout << zost - pud + j << " ";
            zost -= pud;
        }
        cout << endl;
        pud = zost = ilezw = ilenor = 0;
        T--;
    }
    return 0;
}

