vector<ll> make_seq(ll N, ll A, ll B) {
    if (A + B - 1 > N) {
        return {};
    }
    if (A * B < N) {
        return {};
    }
    struct NumInfo {
        ll idx;
        ll number;
    };
    vector<ll> ans;
    vector<NumInfo> num_infos;
    for (ll i = 0; i < B; i++) {
        ans.push_back(-(ll)i * 1000000);
        num_infos.push_back(NumInfo{(ll)ans.size()-1, ans.back()});
        ll cnt = 0;
        while (N - ans.size() > B - i - 1 && cnt < A - 1) {
            ans.push_back(ans.back() + 1);
            num_infos.push_back(NumInfo{(ll)ans.size()-1, ans.back()});
            cnt++;
        }
    }
    sort(num_infos.begin(), num_infos.end(), [](NumInfo lhs, NumInfo rhs){ return lhs.number < rhs.number; });
    for (ll i = 0; i < num_infos.size(); i++) {
        NumInfo info = num_infos[i];
        ans[info.idx] = i + 1;
    }
    return ans;
}

int main() {
    ll N, A, B;
    cin >> N >> A >> B;
    vector<ll> ans = make_seq(N, A, B);
    if (ans.empty()) {
        cout << -1 << endl;
    } else {
        for (ll i = 0; i < ans.size(); i++) {
            cout << ans[i];
            if (i < ans.size() - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
}

