                mx = max(mx,V.back());
                V.pop_back();
            }
            reverse(all(V));
            for (int i: V) ans.pb(i);
            FORd(i,1,mx+1) ans.pb(i);
            break;
        } else {
            // cout << "B\n";
            reverse(all(V));
            for (int i: V) ans.pb(i);
        }
        cur ++;
    }
    for (int i: ans) cout << i << " ";
}

