vi lis(const vl &v) {
	int n = v.size();
	vi prev(n, -1);
	vi dp(n + 1, INF);
	vi pos(n + 1, -1);
	REP(i, n) {
		int c = lower_bound(ALL(dp), v[i]) - dp.begin();//lower:strongly increasing
														//int c = upper_bound(ALL(dp), v[i]) - dp.begin();// upper:weakly increasing
		pos[c] = i;
		dp[c] = v[i];
		if (c != 0)prev[i] = pos[c - 1];
	}

	vi ret;

	int p = pos[lower_bound(ALL(dp), INF) - dp.begin() - 1];


	while (p != -1) {
		ret.push_back(v[p]);
		p = prev[p];
	}
	reverse(ALL(ret));
	return ret;

}

int main() {
	cin.tie(0);
	ios::sync_with_stdio(false);
	ll n, a, b;
	cin >> n >> a >> b;
	if (n + 1 < a + b || a * b < n) {
		cout << -1 << endl;
		return 0;
	}
	vl ans(n);

	REP(i, n)ans[i] = i + 1;
	if (a != 1) {
		ll sum = a * b;
		vl tmp(a + 1, b - (sum - n) / (a - 1));
		REP(i, (sum-n)%(a-1))tmp[a - i]--;
		tmp[0] = 0;
		tmp[1] = b;
		REP(i, a)tmp[i + 1] += tmp[i];

		REP(i, a) {
			reverse(ans.begin() + tmp[i], ans.begin() + tmp[i + 1]);
		}
	}
	REP(i, n) {
		if (i)cout << " ";
		cout << ans[i];
	}
	cout << endl;
	int A = (lis(ans)).size();
	REP(i, n)ans[i] *= -1;
	int B = (lis(ans)).size();
	assert(A == a && B == b);
}

