        cout << -1 << endl;
        return 0;
    }

    VL ans;
    for(LL i = (B-1)*A+1; i <= A*B; i++){
        ans.eb(i);
    }
    int rem = N - (A+B-1);
    for(LL i = B-2; i >= 0; i--){
        for(int j = 0; j < A; j++){
            if(j == 0){
                ans.eb(i*A+j+1);
            }else{
                if(rem > 0){
                    rem--;
                    ans.eb(i*A+j+1);
                }
            }
        }
        if(rem == 0) break;
    }
    Compress<LL> comp;
    comp.add(ans);
    comp.build();
    for(LL x : ans){
        cout << comp.get(x)+1 << " ";
    }
    cout << endl;

}

