template<typename T>
class fixed_point : T {
  public:
    explicit constexpr fixed_point (T&& t) noexcept
      : T(std::forward<T>(t)) {}
    template<typename... Args>
    constexpr decltype(auto) operator()(Args&&... args) const
      {return T::operator()(*this, std::forward<Args>(args)...);}
};
template<typename T>
static inline constexpr decltype(auto) fix (T&& t) noexcept {
  return fixed_point<T>{std::forward<T>(t)};
}
int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  auto make = fix([&] (auto make, long long N, long long A, long long B)
    -> std::vector<int>
    {
    if (N == 0 || A == 0) {
      assert(N == 0 && A == 0);
      return {};
    }
    assert(A + B - 1 <= N && N <= A * B);
    long long r = std::min(B, std::max(1LL, N - ((A - 1) * B)));
    long long a = A - 1, b = B, n = N - r;
    auto ret = make(n, a, b);
    assert((int)ret.size() == n);
    auto another = std::vector<int>(r);
    std::iota(another.begin(), another.end(), n + 1);
    std::reverse(another.begin(), another.end());
    ret.insert(ret.end(), another.begin(), another.end());
    assert((int)ret.size() == N);
    return ret;
  });
  auto err = [&] {
    std::cout << -1 << std::endl;
    exit(0);
  };
  long long N, A, B;
  std::cin >> N >> A >> B;
  if (N < A + B - 1 || A * B < N) err();
  auto ret = make(N, A, B);
  assert((int)ret.size() == N);
  for (int i = 0; i < N; i++) {
    std::cout << (i > 0 ? " " : "") << ret.at(i);
  }
  std::cout << std::endl;
  return 0;
}

