void solve(ll N, ll A, ll B) {
  if (N > A * B) { cout << -1 << endl; return; }
  if (N < A + B - 1) { cout << -1 << endl; return; }
  set<pair<int,int>> s;
  REP(i,A) s.emplace(i, 0);
  REP(i,A) {
    if (int(s.size()) >= N) break;
    REP(j,B) {
      if (int(s.size()) >= N) break;
      if (j == 0) continue;
      s.emplace(i, j);
    }
  }
  vector<int> vec;
  for (auto p: s) vec.push_back(p.first * 1000000L - p.second);
  assert(int(vec.size()) == N);
  vector<int> sorted = vec;
  sort(ALL(sorted));
  REP(i,N) {
    int pos = lower_bound(ALL(sorted), vec[i]) - begin(sorted);
    cout << pos + 1 << " \n"[i == N - 1];
  }
}

