const int MAXN=0;

int N,A,B;

vi f(int a, int b) {
	vi v; v.clear();
	int n = B-1;
	if(N == A) {
		if(B != 1) return v;
		else FOR(i,1,N+1) v.pb(i);
		return v;
	}
	if(N == B) {
		if(A != 1) return v;
		else FOR(i,1,N+1) v.pb(i);
		return v;
	}
	int h = (N-A) / n;
	int m = (N-A) % n;
	if(h == 0) return v;
	if(m == 0) if(h   > A) return v;
	if(m  > 0) if(h+1 > A) return v;
	FOR(i,N-A+1,N+1) v.pb(i);
	int cur = N-A+1;
	FOR(i,0,n) {
		if(cur <= h) h = cur-1;
		cur -= h;
		if(m) v.pb(cur-1);
		FOR(j,0,h) v.pb(cur+j);
		if(m) cur--, m--;
	}
	return v;
}

