int dp[301010];
SegTree<int, 1 << 19> st;
int check() {
    rep(i, 0, N) if (ans[i] == 0) return 0;
    vector<int> v;
    rep(i, 0, N) v.push_back(ans[i]);
    sort(all(v));
    rep(i, 0, N) if (v[i] != i + 1) {
        return 0;
    }

    // 最長部分増加列
    rep(i, 0, N) dp[i] = 1;
    rep(i, 0, N) {
        int ma = st.get(0, ans[i]);
        chmax(dp[i], ma + 1);
        st.update(ans[i], dp[i]);
    }
    int lis = -1;
    rep(i, 0, N) chmax(lis, dp[i]);
    if (lis != A) {
        return 0;
    }

    // 最長減少部分列
    rep(i, 0, N) dp[i] = 1;
    rep(i, 0, N + 1) st.update(i, -1);
    rep(i, 0, N) {
        int ma = st.get(ans[i] + 1, N + 1);
        chmax(dp[i], ma + 1);
        st.update(ans[i], dp[i]);
    }
    int lis2 = -1;
    rep(i, 0, N) chmax(lis2, dp[i]);
    if (lis2 != B) {
        return 0;
    }

    return 1;
}
