        }

        if (B - (pile + 1) <= top - A) {
            rep(i, 0, A) {
                ans[idx + A - 1 - i] = top;
                top--;
            }
            idx += A;
            pile++;
            break;
        } else {
            //break;
            int use = top - (B - (pile + 1));
            if (use < 0) break;
            rep(i, 0, use) {
                ans[idx + use - 1 - i] = top;
                top--;
            }
            idx += use;
            pile++;
        }
    }

    /*rep(i, 0, N) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    } printf("\n");*/

    if (!check()) {
        printf("-1\n");
        return;
    }

    rep(i, 0, N) {
        if (i) printf(" ");
        printf("%d", ans[i]);
    } printf("\n");
}

