class LadderPermutation {
	public:
		vi createLadder(int n, int m, int k) {
			if (n + 1 < m + k) return vi();
			if ((ll) m * k < n) return vi();
			int i = 1;
			vi ans;
			int cur = 0;
			while(i <= n) {
				int c = (n - i + k - 1) / k;
				if (cur + 1 + c <= m) {
					ans.pb(i);
					i++;
					cur++;
					continue;
				}
				int rem = (n - i + 1) % k;
				if (rem == 0) {
					rem = k;
				}
				fj(0, rem - 1) {
					ans.pb(i + rem - 1 - j);
				}
				i += rem;
				cur++;
			}
			return ans;			
		};
};

