int main() {
	cin.sync_with_stdio(false);
	ll N, A, B;
	cin >> N >> A >> B;
	if (N<A + B - 1 || N>A*B)cout << -1 << endl;
	else {
		ll cnt = N - A - B + 1;
		vector<ll>p;
		ll num = A*B;
		rep(i, A) p.push_back(num - (A - 1 - i));
		num -= A;
		while (num > 1) {
			rep(i, A) {
				if (i ==0 )p.push_back(num - (A - 1 - i));
				else {
					if (cnt == 0)break;
					p.push_back(num - (A - 1 - i));
					cnt--;
				}
			}
			num -= A;
		}
		vector<ll>tmp = p;
		sort(tmp.begin(), tmp.end());
		map<ll, ll>mp;
		rep(i, tmp.size()) {
			mp[tmp[i]] = i + 1;
		}
		rep(i, p.size()) {
			cout << mp[p[i]];
			if (i != p.size() - 1)cout << " ";
			else cout << endl;
		}
	}
	return 0;
}

