int main() {
    int n; cin >> n;
    int inc, dec; cin >> inc >> dec;
    if (inc + dec - 1 > n || inc * dec < n) return !(cout << -1 << endl);
    vector<int> a(n);
    iota(a.begin(), a.end(), 1);
    if (dec > 1) {
        int q = (n - inc) / (dec - 1);
        for (int i = 0; i < n; i += q) {
            reverse(begin(a) + i, begin(a) + min(n, i + q));
        }
    }
