int LIS(const std::vector<int>& a) {
	int n = a.size();
	std::vector<int> dp(n, INFINT);
	for (int i = 0; i < n; ++i) {
		*std::lower_bound(dp.begin(), dp.end(), a[i]) = a[i];
	}
	return std::distance(dp.begin(), std::lower_bound(dp.begin(), dp.end(), INFINT));
}

void END() { OUT(-1)BR; exit(0); }

signed main() {
	INIT;

	VAR(int, n, a, b);
	if (a + b > n + 1) END();

	bool flag = false;
	if (a < b) {
		flag = true;
		std::swap(a, b);
	}
	std::vector<int> v(n);
	std::iota(ALL(v), 1);
	[&]{
		if (b == 1) {
			if (a == n) return;
			else END();
		}
		int t = n - a;
		int q = t / (b - 1);
		int r = t % (b - 1);
		if (q > a) END();
		std::vector<std::vector<int>> u(1);
		FOR(i, 1, t + 1) {
			if (u.back().size() == q + (u.size() <= r)) u.emplace_back();
			u.back().emplace_back(i);
		}
		std::reverse(ALL(u));
		REP(i, a) v[i] = n - a + 1 + i;
		int p = a;
		for (auto& uu : u) for (auto& x : uu) v[p++] = x;
	}();

	if (flag) {
		REP(i, n) v[i] = n + 1 - v[i];
		std::swap(a, b);
	}
	{ // check
		if (a != LIS(v)) END();
		auto u(v);
		std::reverse(ALL(u));
		if (b != LIS(u)) END();
	}
	REP(i, n) {
		OUT(v[i])SPBR(i, n);
	}
	return 0;
}

