vector<int> solve(int n, int a, int b){
    vector<int> res(n);
    if(b==1){
        if(a==n){
            REP(i,n){
                res[i] = i+1;
            }
        }else{
            put(-1);
            return res;
        }
    }else{
        int t = (n-a)/(b-1);
        REP(i,t){
            REP(j,b){
                res[i*b+j] = (i+1)*b-j;
            }
        }
        int k = n-t*b;
        REP(i,k-(a-t)){
            res[b*t+i] = n-i;
        }
        REP(i,a-t){
            res[b*t+k-(a-t)+i] = t*b+1+i;
        }
    }
    return res;
}

