vector<int> solve(int n, int a, int b) {
        vector<int> ans;
        int cur = a + 1;
        for (int i = 1; i <= a; i ++) {
                ans.push_back(i);
                if (i == a) {
                        break;
                }
                int t = b - 1;
                vector<int> tmp;
                while (t --) {
                        if (cur > n) break;
                        tmp.push_back(cur);
                        cur ++;
                }
                reverse(tmp.begin(), tmp.end());
                for (auto it : tmp) {
                        ans.push_back(it);
                }
        }
        if ((int)ans.size() < n) {
                return {};
        }
        return ans;
}

