			for(int i = 1; i <= n; i++) cout << i << " "; cout << endl;
		} else {
			cout << -1 << endl;
		}
	} else {
		if(a + b - 1 > n) cout << -1 << endl;
		else {
			vector<int> inc, dec;
			int fr = n;
			for(int i = 0; i < a; i++) inc.push_back(fr--);
			for(int i = 1; i < b; i++) dec.push_back(fr--);
			reverse(inc.begin(), inc.end());
			vector<int> ans;
			for(int i = 0; i < a - 1; i++){
				ans.push_back(inc[i]);
				int tk = min(b - 1, fr);
				vector<int> now;
				for(int j = 0; j < tk; j++) now.push_back(fr--);
				for(int v : now) ans.push_back(v);
			}
			ans.push_back(inc[a - 1]);
			for(int i = 0; i < b - 1; i++){
				int tk = min(a - 1, fr);
				vector<int> now;
				for(int j = 0; j < tk; j++) now.push_back(fr--);
				reverse(now.begin(), now.end());
				for(int v : now) ans.push_back(v);
				ans.push_back(dec[i]);
			}
			bool oka = true, okb = true;
			{
				vector<int> lis;
				for(int v : ans){
					int pt = lower_bound(lis.begin(), lis.end(), v) - lis.begin();
					if(pt == lis.size()) lis.push_back(v);
					else lis[pt] = v;
				}
				oka &= lis.size() == a;
			}
			{
				vector<int> lis;
				for(int v : ans){
					int pt = lower_bound(lis.begin(), lis.end(), -v) - lis.begin();
					if(pt == lis.size()) lis.push_back(-v);
