int dp[300001];
int N;
int LIS() {
	fill(dp + 1, dp + (N + 1), 1 << 30);
	for (int i = 1; i <= N; i++) {
		*lower_bound(dp + 1, dp + (N + 1), P[i]) = P[i];
	}
	return lower_bound(dp + 1, dp + (N + 1), 1 << 30) - (dp + 1);
}
int main() {
	int A, B;
	cin >> N >> A >> B;
	if (A + B > N + 1) {
		cout << -1 << endl;
		return 0;
	}
	bool rev = 0;
	if (A < B) {
		swap(A, B);
		rev = 1;
	}
	for (int i = 1; i <= A; i++) P[i] = N - A + i;
	for (int i = 1; i <= N - A; i++) P[i + A] = i;
	reverse(P + (N - B + 2), P + (N + 1));
	if (rev) {
		swap(A, B);
		reverse(P + 1, P + (N + 1));
	}
	int X = LIS();
	reverse(P + 1, P + (N + 1));
	int Y = LIS();
	reverse(P + 1, P + (N + 1));
	if (X != A || Y != B) {
		cout << -1 << endl;
		return 0;
	}
	cout << P[1];
