using namespace std;
typedef long long int ll;
typedef vector<int> VI;
typedef vector<ll> VL;
typedef pair<int, int> PI;

int lis(const VI &a) {
  int n = a.size();
  // LIS, longest increasing subsequence
  VI m(n + 1);
  int l = 0;
  REP(i, 0, n) {
    int lo = 0;
    int hi = l + 1;
    while (hi - lo > 1) {
      int mid = (hi + lo) / 2;
      if (a[m[mid]] < a[i]) {
	lo = mid;
      } else {
	hi = mid;
      }
    }
    int newl = lo + 1;
    m[newl] = i;
    if (newl > l) {
      l = newl;
    }
  }
  return l;
}


