void solve() {
	cin >> n >> a >> b;
	if(a + b - 1 > n || n > a * b) {
		cout << -1 << endl;
		return;
	}
	if(b == 1) {
		rep(i, n) {
			cout << i + 1 << " ";
		}
		return;
	}
	for(int i = n - a + 1; i <= n; ++ i) {
		cout << i << " ";
	}
	int x = (n - a) / (b - 1);
	int y = n - a - x * (b - 1);
	int cur = n - a + 1;
	rep(i, y) {
		cur -= (x + 1);
		rep(j, x + 1) {
			cout << cur + j << " ";
		}
	}
	rep(i, b - 1 - y) {
		cur -= x;
		rep(j, x) {
			cout << cur + j << " ";
		}
	}
	cout << endl;
}

