ll ck(vector<ll> a,ll x,ll y) {
  ll n=a.size();
  ll dp[n];
  fill(dp,dp+n,MAX);
  rep(i,n) *lower_bound(dp,dp+n,a[i])=a[i];
  ll xx=lower_bound(dp,dp+n,MAX)-dp;
  rep(i,n) a[i]*=-1;
  fill(dp,dp+n,MAX);
  rep(i,n) *lower_bound(dp,dp+n,a[i])=a[i];
  ll yy=lower_bound(dp,dp+n,MAX)-dp;
  rep(i,n) a[i]*=-1;
  if(x==xx&&y==yy) return 1;
  return 0;
}

