namespace my {
    template <class Num, class Pred>
    Num upper_bound(Num l, int r, Pred&& is_good) {
        if (l == r) {
            return r;
        }
        if (!is_good(l)) {
            return l;
        }
        while (r - l > 1) {
            int m = l + (r - l) / 2;
            if (is_good(m)) {
                l = m;
            } else {
                r = m;
            }
        }
        return r;
    }
}

