int inf = 1488228228;

template <class Iter>
int len_increasing(int maxn, Iter first, Iter last) {
    std::vector<int> dp(maxn + 1, inf);
    dp[0] = -inf;
    for (; first != last; ++first) {
        int x = std::upper_bound(dp.begin(), dp.end(), *first) - dp.begin();
        if (dp[x - 1] < *first && *first < dp[x]) {
            dp[x] = *first;
        }
    }
    return std::lower_bound(dp.begin(), dp.end(), inf) - dp.begin() - 1;
}

