    int memo = b;
    if(a + b > n + 1){
    	cout << -1 << endl;
    	return 0;
    }
    vector<int> ans;
    for(int i=n-a+1;i<=n;i++) ans.pb(i);
    b--;
    n -= a;
    while(n > 0){
    	if(n - a < b - 1){
    		if(n == b) while(n) ans.pb(n), n--;
    		else{
    			int num = max(1, n - a + 1);
    			int count = 1;
    			for(int i=num;i<=n;i++, count++){
    				ans.pb(i);
    				if(n - count == b){
    					while(n > 0) {
    						if(n == i) n = num - 1;
    						else ans.pb(n), n--;
    					}
    					break;
    				}
    			}
    			n -= a;
    		}
    	}
    	else{
    		for(int i=n-a+1;i<=n;i++) ans.pb(i);
    		n -= a;
    	}
    }
    vector<int> x, y;
    for(int i=0;i<n;i++){
    	int id = lower_bound(be(x), ans[i]) - x.begin();
    	if(id == x.size()) x.pb(ans[i]);
