            if(a != n){
                  puts("-1");
                  return 0;
            }
            for(int i = 1; i <= n; i ++)
                  printf("%d ", i);
            return 0;
      }

      if(a > n || b > n){
            puts("-1");
            return 0;
      }

      for(int i = 1; i <= n; i ++)
            ans[i] = i;

      int last = n - a + 1;

      for(int i = 1; i <= n; i += b){
            int l = i, r;
            r = l + b - 1;
            r = min(r, last);
            if(l >= r) break;
            reverse(ans + l, ans + r + 1);
            last ++;
      }

      for(int i = 1; i <= n; i ++){
            dp[i] = inf;
      }

      int mx = 0;

      for(int i = 1; i <= n; i ++){
