const int limit = 300010;
vector<int> box[limit];
vector<int> ans;

int main(void) {
	int n, a, b;
	cin >> n >> a >> b;

	const int lb = (n + a - 1) / a;


	if (a + b > n + 1 or b < lb) {
		puts("-1");
		return 0;
	}

	int bn = 0;
	rep(i, limit) {
		const int start = a * i + 1;
		if (start > n) break;
		rep(j, a) {
			int cur = a * i + 1 + j;
			if (cur <= n) box[i].push_back(cur);
		}
		bn++;
	}

	const int total = bn;

	rrep(i, total) {
		const int num = min<int>(box[i].size() - 1, b - bn);

		bn += num;
		sort(rbegin(box[i]), rend(box[i]));
		sort(begin(box[i]) + num, end(box[i]));

		for (auto &elem : box[i]) {
			ans.push_back(elem);
		}
	}

	rep(i, n) cout << (i ? " " : "") << ans[i];
	cout << endl;

	return 0;
}

