int main()
{
	ll N, A, B;
	cin >> N >> A >> B;
	if (A > N || B > N) {
		cout << -1 << endl;
		return 0;
	}
	if (N + 1 < A + B) {
		cout << -1 << endl;
		return 0;
	}
	if (N + 1 == A + B) {
		vector<int> res(N);
		for (int i = 0; i < A; i++) {
			res[i] = B + i;
		}
		for (int i = 0; i < B - 1; i++) {
			res[A + i] = B - 1 - i;
		}
		for (int i = 0; i < N; i++) {
			cout << res[i] << " \n"[i + 1 == N];
		}
		return 0;
	}
	bool flag = false;
	if (A > B) swap(A, B), flag = true;
	if (A == 1 && B != N - 1) {
		if (B != N - 1) {
			cout << -1 << endl;
			return 0;
		}
		vector<int> res(N);
		for (int i = 0; i < N; i++) {
			res[i] = N - i;
		}
		if (flag) reverse(res.begin(), res.end());
		for (int i = 0; i < N; i++) {
			cout << res[i] << " \n"[i + 1 == N];
		}
		return 0;
	}
	if (A + B - 1 <= N && N <= A * B) {
		vector<int> res(N);
		for (int i = 0; i < A; i++) {
			res[i] = N - A + i + 1;
		}
		vector<int> sp(B - 1);
		for (int i = 0; i < B - 1; i++) {
			sp[i] = (N - A + i) / (B - 1);
		}
		int sum = A;
		for (int i = 0; i < B - 1; i++) {
			sum += sp[i];
		}
		assert(sum == N);
		int tmp = N - A, pos = A;
		for (int i = 0; i < B - 1; i++) {
			for (int j = 0; j < sp[i]; j++) {
				res[pos++] = tmp - sp[i] + j + 1;
			}
			tmp -= sp[i];
		}
		if (flag) reverse(res.begin(), res.end());
		for (int i = 0; i < N; i++) {
			cout << res[i] << " \n"[i + 1 == N];
		}
		return 0;
	}
	cout << -1 << endl;
	return 0;
}

