int vals[300300];

void solve(){
	if(A + B > N + 1) no();
	if((long long)A * B < N) no();
	for(int i = 0; i < A; ++i){
		vals[i] = 1;
	}
	vals[0] = B;
	int tmp = A + B - 1;
	tmp = N - tmp;
	for(int i = 1; i < A; ++i){
		int cur = min(tmp, B - 1);
		vals[i] += cur;
		tmp -= cur;
	}
	int m = 0;
	for(int i = 0; i < A; ++i){
		int cur = vals[i];
		for(int x = m + cur; x > m; --x){
			ans.push_back(x);
		}
		m += cur;
	}
}

int main(){
