vector<ll> solve(){
    ll N,A,B; cin >> N >> A >> B;
    vector<ll> res(N); iota(res.begin(),res.end(),1);
    if(A+B > N+1) return vector<ll>{-1};
    for(int i = 0; i < B;i++){
        res[i] = B-i;
    }

    ll LIS = N-B+1;
    ll idx = N-1;
    while(LIS != A){
        if(res[idx-1] == 1) return vector<ll>{-1};
        swap(res[idx],res[idx-1]);
        LIS--;
        idx--;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

