const int inf = 1 << 30;

int LIS(vector<int> &v) {
    vector<int> dp(v.size(), inf);
    REP (i, 0, v.size()) {
        *lower_bound(dp.begin(), dp.end(), v[i]) = v[i];
    }
    return lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
}

int LDS(vector<int> &v) {
    REP (i, 0, v.size()) v[i] = -v[i];
    int ans = LIS(v);
    REP (i, 0, v.size()) v[i] = -v[i];
    return ans;
}

