    while(clock() < MAX_TIME) {
        vec< int > p2 = p;
        for(int i = 0;i < n;i++) {
            p2[i] = n + 1 - p2[i];
        }
        if(inc(p) == a && inc(p2) == b) {
            res = p;
            return true;
        }
    };
    return false;
}

