int main() {
    ios::sync_with_stdio(0), cin.tie(0), cout.tie(0);
	int N, A, B; cin >> N >> A >> B; swap(A, B);

	if (A + B == N + 1) {
		vi arr (N);
		F0R(i, B - 1) arr[i] = 1 + i;
		FOR(i, B - 1, N) arr[i] = N - (i - B + 1);
		for (int x : arr) cout << x << " ";
		cout << endl;
		return 0;
	}

	if (A + B > N + 1) {
		cout << -1 << endl;
		return 0;
	}

	vi arr (N);
	int onLeft = 0;
	while (true) {
		F0R(i, A) arr[onLeft * A + i] = A - i + onLeft * A;
		--B;
		if (B < 0) {
			cout << -1 << endl;
			return 0;
		}
		++onLeft;
		if ((onLeft + 1) * A - 1 + B >= N) break;
	}

	F0R(i, B) {
		arr[N-1-i] = N - i;
	}

	int hi = N - B;
	for (int x = onLeft * A; x < N && arr[x] == 0; ++x) {
		arr[x] = hi; --hi; 
	}

	for (int x : arr) cout << x << " ";
	cout << endl;
}

