template <typename T=long long>
vector<T> LISLDS(T N, T A, T B)
{
    vector<T> ret;
    for(long long i = B-1; i >= B; --i) ret.push_back(i);

    if(A == 1) return ret;

    long long rem = N-B;
    long long p = rem/(A-1), r = rem%(A-1);

    long long b = r, c = A-1-r;

    REP(i, b){
        int size = ret.size();
        REP(j, p+1) ret.push_back(size+p-j);
    }
    REP(i, c){
        int size = ret.size();
        REP(j, p) ret.push_back(size+p-1-j);
    }

    return ret;
}


int main()
{
    int N, A, B;
    cin >> N >> A >> B;

    if(A+B > N+1 or A*B < N) cout << -1 << endl;
    else{
        for(auto v: LISLDS(N, A, B)) cout << v+1 << " ";
        cout << endl;
    }

    return 0;
}

