int compress(vector< int > &x1, int W) {
	vector< int > xs;
	int N = x1.size();
	for (int i = 0; i < N; i++) {

		int tx1 = x1[i];

		xs.push_back(tx1);
	}

	sort(xs.begin(), xs.end());
	xs.erase(unique(xs.begin(), xs.end()), xs.end());
	for (int i = 0; i < N; i++) {
		x1[i] = lower_bound(xs.begin(), xs.end(), x1[i]) - xs.begin() + 1;
	}
	return (int)xs.size();
}

