  if(a>n||b>n||a+b>n+1||a*b<n){
    cout << -1 << endl;
    return 0;
  }

  vector<ll> ans(n);
  int x=n;
  rep(i,n){
    if(i%a==0){
      if(i+a-1>=n) ans[i]=1;
      else ans[i]=x-a+1;
      x-=a;
    }
    else ans[i]=ans[i-1]+1;
  }

  auto p=ans;
  reverse(all(p));

  int sa=b-lis(p);

  reverse(ans.begin(),ans.begin()+sa);

  rep(i,n){
    if(i!=0) cout << " ";
    cout << ans[i];
  }
  cout << endl;

}

