void solve(std::istream &in, std::ostream &out) {
  int n,a,b;
  in >> n >> a >> b;
  if (a + b + 1 > n || (int64_t) a * b < n) {
    out << "-1\n";
    return;
  }
  for (int block = 0, sz = a, el = n - a + 1; block < b; ++block) {
    for (int i = 0; i < sz; ++i) {
      out << el + i << ' ';
    }
    sz = min(n - (block + 1) * sz, a);
    el -= sz;
  }
}

