        if (itr + B <= N - A + cnt) {
            reverse(ans.begin() + itr, ans.begin() + itr + B);
            itr += B;
        } else {
            reverse(ans.begin() + itr, ans.end() - A + cnt);
            itr = N - A + cnt + 1;
        }

        if (cnt > A) {
            cout << -1 << endl;
            return 0;
        }
    }

    if (cnt == 0) {
        cout << -1 << endl;
        return 0;
    }

    NREP(i, N) {
        cout << ans[i] << " ";
    }
    cout << endl;

    return 0;
}

