lli getLisLength(vector<lli> a)
{
  lli inf = 1e18;
  vector<lli> dp(a.size() + 3, inf);
  //inf=>INF
  rep(i, a.size())
  {
    *lower_bound(dp.begin(), dp.end(), a[i]) = a[i];
  }
  return lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
}
