#include <cstdio>

using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)

const int N_MAX = 300000;

int N, A, B;
int a[N_MAX];

void solve() {
  if (A + B > N + 1) {
    puts("-1");
    return;
  }
  if (N > A * (B - 1) + (A - 1) * B) {
    puts("-1");
    return;
  }
  int n = N / 2;
  int m = N - n;
  if (n < A) {
    n = A; m = N - n;
  }
  if (m < B) {
    m = B; n = N - m;
  }
  REP(i, B - 1) {
    REP(j, A) {
      int k = i * A + j;
      if (k >= n) break;
      a[N - 1 - k] = (i + 1) * A - j;
    }
  }
  REP(i, A - 1) {
    REP(j, B) {
      int k = i * B + j;
      if (k >= m) break;
      a[m - 1 - k] = N - (i + 1) * B + 1 + j;
    }
  }
  REP(i, N) printf("%d%c", a[i], i + 1 == N ? '\n' : ' ');
}

void input() {
  scanf("%d%d%d", &N, &A, &B);
}

int main() {
  input();
  solve();
  return 0;
}

