const int N=301000;

int s[N];
int n,A,B;
int tot;

int L,R;

void dec()
{
	int x=L+B-1;L=x+1;
	if(x>R)x=R;
	for(int tmp=B;tot<n && tmp--;)s[++tot]=x,x--;
}
void inc()
{
	int x=R-A+1;R=x-1;
	if(x<L)x=L;
	for(int tmp=A;tot<n && tmp--;)s[++tot]=x,x++;
}

bool solve()
{
	if(A+B>n+1)return 0;

	tot=0;
	while(tot<n)
	{
		if(!B)return 0;
		dec(),A--;
		if(A<0)return 0;
		if(tot==n)break;

//		printf("%d--%d\n",L,R);

		if(!A)return 0;
		inc(),B--;
		if(B<0)return 0;

//		printf("%d--%d\n",L,R);
	}

	return 1;
}

