long long n, a, b;
vector<int> res;

bool solve();

int main() {
  cin >> n >> a >> b;
  if (solve())
    for (int i = 0; i < n; ++i) cout << res[i] << " \n"[i == n - 1];
  else
    cout << -1 << endl;
  return 0;
