bool solve() {
  if (n < a || n < b || b > (n + a - 1) / a) return 0;
  if (a == 1 && b == n) {
    for (int i = 1; i <= n; ++i) res.push_back(n - i + 1);
    return 1;
  }
  if (a == n && b == 1) {
    for (int i = 1; i <= n; ++i) res.push_back(i);
    return 1;
  }
  vector<vector<int>> v;
  for (int i = n; i >= 0;) {
    vector<int> tmp;
    for (int k = 0; k < a; ++k)
      if (i - a + 1 + k > 0) tmp.push_back(i - a + 1 + k);
    v.push_back(tmp);
    i -= a;
  }
  int p = v.size();
  if (p != b) return 0;
  for (auto ve : v)
    for (auto num : ve) res.push_back(num);
  return 1;
}

