bool solve(int N, int A, int B) {
    vector<int> As, Bs;
    if(A > N) return false;
    As.push_back(A);
    int sum = A;
    int nxt_a = A;
    int nxt_b = B;    
    while(sum < N) {
        nxt_a--;
        nxt_b--;
        int left = N - sum;
        if(left > 0) {
            int v = min(nxt_b, left);
            if(v == 0 and left > 0) return false;
            Bs.push_back(v);
            sum += v;
        }
        left = N - sum;
        if(left > 0) {
            int v = min(nxt_a, left);
            if(v == 0 and left > 0) return false;
            As.push_back(v);
            sum += v;
        }
    }
    if(B > 1 and Bs.size() == 0) return false;
    if(B > 1 and Bs.size() != B - 1) return false;
    vector<int> ans;
    int l = 1, r = N;
    rep(i, max(As.size(), Bs.size())) {
        if(i < As.size()) {
            for(int a = l + As[i] - 1; a >= l; a--) ans.push_back(a);
            l += As[i];
        }
        if(i < Bs.size()) {
            for(int b = r - Bs[i] + 1; b <= r; b++) ans.push_back(b);
            r -= Bs[i];
        }
    }
    assert(ans.size() == N);
    reverse(all(ans));
    rep(i, ans.size()) {
        cout << ans[i] << (i == ans.size() - 1 ? "\n" : " ");
    }
    return true;
}

int main() {
    cin.tie(0);
    ios::sync_with_stdio(false);

    int N, A, B; cin >> N >> A >> B;    

    if(not (solve(N, A, B) or solve(N, B, A))) {
        cout << - 1 << endl;
    }

    return 0;
}

