template <class IT> int count_lis(const IT &beg, const IT &end) {
	int n = end - beg;
	const auto inf = numeric_limits<typename IT::value_type>::max();
	vector<typename IT::value_type> dp(n, inf);
	for (auto it = beg; it < end; it++) *lower_bound(dp.begin(), dp.end(), *it) = *it;
	return lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
}

template <class IT> int count_lds(const IT &beg, const IT &end) {
	int n = end - beg;
	const auto inf = numeric_limits<typename IT::value_type>::max();
	vector<typename IT::value_type> dp(n, inf);
	for (auto it = beg; it < end; it++) *lower_bound(dp.begin(), dp.end(), -(*it)) = -(*it);
	return lower_bound(dp.begin(), dp.end(), inf) - dp.begin();
}

void naive(int n, int a, int b) {
	vi A(n);
	rep(i, 1, n+1) A[i-1] = i;

	do {
		int lis = count_lis(all(A));
		int lds = count_lds(all(A));
		int sum = lis + lds;
		if (lis == a && lds == b) out(A, lis, lds, sum);
	} while (next_permutation(all(A)));
}

void panic() {
	cout << -1 << endl;
	exit(0);
}

void Main() {
	ll n = ri(), a = ri(), b = ri();

	if (a * b < n) panic();
	if (a + b > n + 1) panic();

	vi A(a*b+1, -1);
	rep(i, n) {
		int idx1 = i / b * b;
		int idx2 = b - i % b - 1;
		int idx = idx1 + idx2;
		A[idx] = i+1;
	}
	out(A);
	vi ans;
	forr(x, A) if (x >= 1) ans.emplace_back(x);

	assert(count_lis(all(ans)) == a);
	assert(count_lds(all(ans)) == b);

	forr(x, ans) {
		cout << x << ' ';
	}
	cout << endl;
}

