int N, A, B;
int ans[int(3e5 + 5)], DP[int(3e5+5)];

int Increase(){
  fill(DP, DP + N + 1, 1e9);
  for (int i = 0; i < N; i++){
    if (ans[i] < DP[0]){
      DP[0] = ans[i]; continue;
    }

    int L = 0, R = N;
    while (R - L > 1){
      int mid = (L + R) / 2;

      if (ans[i] < DP[mid]) R = mid;
      else L = mid;
    }
    DP[R] = ans[i];
  }

  for (int i = 0; i <= N; i++){
    if (DP[i] == 1e9) return i;
  }
  return 0;
}

int Decrease(){
  fill(DP, DP + N + 1, 0);
  for (int i = 0; i < N; i++){
    if (DP[0] < ans[i]){
      DP[0] = ans[i]; continue;
    }
    int L = 0, R = N;
    while (R - L > 1){
      int mid = (L + R) / 2;
      if (DP[mid] < ans[i]) R = mid;
      else L = mid;
    }
    DP[R] = ans[i];
  }

  for (int i = 0; i <= N; i++){
    if (DP[i] == 0) return i;
  }

  return 0;
}

int main(){
  scanf("%d%d%d", &N, &A, &B);

  if (A + B > N + 1){
    printf("-1\n"); return 0;
  }

  int M = N;
  for (int i = A - 1; i >= 0; i--){
    ans[i] = M; M--;
  }

  int m = 1;
  for (int i = 0; i < B - 1; i++){
    ans[A + B - i - 2] = m;
    m++;
  }

  int cnt = 0;
  for (int i = A + B - 1; i < N; i++){
    if (cnt % 2 == 0) ans[i] = M, M--;
    else ans[i] = m, m++;
  }

  if (Increase() != A || Decrease() != B){
    printf("-1\n"); return 0;
  }

  cout << ans[0];
  for (int i = 1; i < N; i++) printf(" %d", ans[i]);
  cout << endl;

  return 0;
}

