		REP(i,B-1){
			int ct;
			if(i<r)ct = q + 1;
			else ct = q;
			dump(ct);
			REP(j,ct)v[i+1].push_back(t),t--;
		}
	}
//	assert(t==0);
	REP(i,B){
		reverse(ALL(v[i]));
	}
	REP(i,v.size())REP(j,v[i].size()){
		ans.push_back(v[i][j]);
	}
