int main(void){
    cin>>n>>a>>b;
    if(n+1<a+b||((n+a-1)/a>b&&(n+b-1)/b>a)){
        cout<<-1<<endl;
        return 0;
    }
    if(a==1){
        for(int i=n;i>=1;i--)ans.push_back(i);
    }else if(b==1)for(int i=1;i<=n;i++)ans.push_back(i);
    else if((n+a-1)/a<=b){
        int o=1;
        for(int i=o+b-1;i>=o;i--)ans.push_back(i);
        o+=b;
        int s=(n-o+1);
        a--;
        b=s/a;
        for(int i=0;i<s%a;i++){
            for(int j=o+b;j>=o;j--)ans.push_back(j);
            o+=b+1;
        }
        for(int i=0;i<a-s%a;i++){
            for(int j=o+b-1;j>=o;j--)ans.push_back(j);
            o+=b;
        }
    }else{
        int o=n;
        for(int i=o-b+1;i<=o;i++)ans.push_back(i);
        o-=b;
        int s=(n-o+1);
        a--;
        b=s/a;
        for(int i=0;i<s%a;i++){
            for(int j=o-b;j<=o;j++)ans.push_back(j);
            o-=(b+1);
        }
        for(int i=0;i<a-s%a;i++){
            for(int j=o-b+1;j<=o;j++)ans.push_back(j);
            o-=b;
        }
    }
    for(int i=0;i<ans.size();i++){
