                ans.push_back(i - j);
            }
        }
    }

    int lds = 1;
    for (int i = 0; i < n - 1; i++)
    {
        if (ans[i] > ans[i + 1])
        {
            lds++;
        }
    }

    if (lds != b)
    {
        for (int i = n - 2; i >= 0; i--)
        {
            if (ans[i] < ans[i + 1])
            {
                lds++;
            }
            if (lds == b)
            {
                sort(ans.begin() + i, ans.end());
                reverse(ans.begin() + i, ans.end());
                break;
            }
        }
    }

    for (int i = 0; i < n; i++)
    {
        if (i)
            cout << " ";
        cout << ans[i];
    }

    cout << endl;

    return 0;
}

