using namespace std;

#define REP(i,n)   for(int i=0; i<(int)(n); i++)
#define FOR(i,b,e) for(int i=(b); i<=(int)(e); i++)
#define ITR(c,it)  for(auto it = c.begin(); it != c.end(); it++)

typedef long long ll;

const int N_MAX = 300000;

int N, A, B;
ll a[N_MAX];

map<ll, int> mp;

void compress() {
  REP(i, N) mp[a[i]] = 1;
  int k = 1;
  ITR(mp, it) it->second = k++;
  REP(i, N) a[i] = mp[a[i]];
}

void solve() {
  if (A + B > N + 1) {
    puts("-1");
    return;
  }
  if (A * B < N) {
    puts("-1");
    return;
  }
  int k = 0;
  REP(j, B) REP(i, A) {
    if (i > 0 && j > 0) {
      ll k2 = (j - 1) * (A - 1) + i - 1;
      if (k2 >= N + 1 - A - B) break;
    }
    a[k++] = B * (i + 1) - j;
  }
  compress();
  REP(i, N) printf("%d%c", a[i], i + 1 == N ? '\n' : ' ');
}

void input() {
  scanf("%d%d%d", &N, &A, &B);
}

int main() {
  input();
  solve();
  return 0;
}

