        if(idx[i] > a || idx[i] == 0){
            cout << -1 << endl;
            return 0;
        }
    }
    start[b] = start[b-1] + idx[b-1];

    if(start[b] != n){
        cout << -1 << endl;
        return 0;
    }

    for(int i=b-1;i>=0;i--){
        reppp(j, start[i], start[i+1]){
            cout << j << " ";
        }
    }

    cout << endl;
    return 0;
}

