/*
長さ n, 増加 l, 減少 m を探します。
極端なのが長方形とお山で、l+m-1 <= n <= lm です。
n を l 個のブロックに分けて、各成分が 1 以上、max が m, 合計が n になるように分けます。
全成分 1 引いておくことで、a = n - l, b = m - 1 とおくと、max が b, 合計が a です。
a = b*q + r と置くことで、b が q 個、次に r、残りは 0 です。
*/

int main() {
  std::cin.tie(0); std::cin.sync_with_stdio(false);
  lint n, l, m;
  std::cin >> n >> l >> m;
  debug(l,m,n);
  require(l+m <= n+1 && n <= l*m);

  auto ans = [&]  {
    std::vector<int> ans(n);
    std::iota(all(ans),0);
    if (m == 1) {
      assert(l == n);
      return ans;
    }
    lint a = n - l, b = m - 1;
    debug(a,b);
    lint q = a / b, r = a % b;
    std::vector<lint> v(l);
    rep(i,0,q) {
      v.at(i) = b;
    }
    if (0 < r) {
      assert(q < l);
      v.at(q) = r;
    }
    for (lint & x : v) x++;
    debug(v);
    std::partial_sum(all(v),v.begin());
    v.insert(v.begin(),0);

    rep(i,0,l) {
      std::reverse(ans.begin() + v.at(i), ans.begin() + v.at(i+1));
    }
    return ans;
  }();

  for (int & x : ans) x++;

  rep(i,0,n) {
    std::cout << (0 < i ? " " : "") << ans.at(i);
  }
  std::cout << std::endl;
  return 0;
}

