void solve() {
    int n, a, b;
    cin >> n >> a >> b;
    if (a > n || b > n) {
        cout << -1;
        return;
    }
    vector<int> p(n);
    for (int i = 0; i < n; ++i) {
        p[i] = i + 1;
    }
    int inc = n - (b - 1);
    int i = b;
    reverse(begin(p), begin(p) + b);
    while (i < n && inc > a) {
        int len = min(n - i, min(b, inc - a + 1));
        reverse(begin(p) + i, begin(p) + i + len);
        inc -= len - 1;
        i += len;
    }
    if (inc != a) {
        cout << -1;
        return;
    }
    for (int i = 0; i < n; ++i) {
        cout << p[i] << ' ';
    }
}

