int N, A, B;

int judge() {
  if (A+B == N+1) return 1; /// 幅がぴったりの時
  if (A == 1 || B == 1 || A+B > N+1) return -1; /// 幅が足りない、もしくは幅が狭すぎる時
  return 0;
}

int main() {

  cin >> N >> A >> B;
  int j = judge();
  if (j == -1) { /// できなとき
    cout << -1 << endl;
    return 0;
  } else if (j == 1) { /// 単調増加してから単調減少数する
    if (A == 1) {
      cout << N;
      FORR (i, 1, N) cout << " " << i; 
    } else if (B == 1) {
      cout << 1;
      FOR (i, 2, N+1) cout << " " << i;
    } else {
      FOR (i, B, N+1) cout << i << " ";
      FORR (i, 2, B) cout << i << " ";
      cout << 1;
    }
    cout << endl;
    return 0;
  } else {
    int top = N-A+1;
    FOR (i, top, N+1) cout << i << " ";
    int bottom = B-1;
    FORR (i, 1, bottom+1) cout << i << " ";
    while (1) {
      if (top - bottom > 2) cout << --top << " ";
      else {
        cout << top-1 << endl;
        break;
      }
      if (top - bottom > 2) cout << ++bottom << " ";
      else {
        cout << bottom+1 << endl;
        break;
      }
    }
  }


  return 0;

}

