        teeth[0] = a;
        rep(i, b - 1)
        {
            if (i < r) {
                teeth[i + 1] = q + 1;
            } else {
                teeth[i + 1] = q;
            }
        }

        int j = n;
        for (int l : teeth) {
            rep(i, l)
            {
                cout << j - (l - 1) + i << " ";
            }
            j -= l;
        }
        cout << endl;
    }

    return 0;
}

