vector<ll> solve(){
    ll N,A,B; cin >> N >> A >> B;
    if(A + B > N + 1) return vector<ll>{-1};
    if(A*B < N) return vector<ll>{-1};
    vector<ll> res;
    ll now = 1;
    for(int i = 0; i < A;i++){
        ll R = min(N,now+B-1);
        while(R >= now) res.push_back(R--);
        now = now+B;
    }
    return res;
}
int main(void) {
    cin.tie(0); ios_base::sync_with_stdio(false);
    cout << solve() << endl;
    return 0;
}

