int N, A, B;
int arr[300300];

void flip(int index) {
    //index->[l,r]
    int l = N - (index * B) + 1;
    int r = N - (index * B) + B;
    if (l >= 1) {
        rep(i, B / 2) {
            swap(arr[l + i], arr[r - i]);
        }
        return;
    } else {
        rep(i, r / 2) {
            swap(arr[1 + i], arr[r - i]);
        }
        return;
    }
}

void flip(int index, int num) {
    int l = N - (index * B) + 1;
    if (l < 1)l = 1;
    int r = l + num - 1;
    rep(i, (r - l + 1) / 2) {
        swap(arr[l + i], arr[r + i]);
    }
}


signed main() {
    cin >> N >> A >> B;
    bool swp = (B > A);
    if (swp)swap(A, B);

    int minA = (N - 1) / B + 1;
    int maxA = N - B + 1;
    if (A < minA || A > maxA) {
        cout << "-1" << endl;
        return 0;
    }

    for (int i = 1; i <= N; ++i) {
        arr[i] = i;
    }
    for (int i = 1; i <= (N - 1) / B + 1; ++i) {
        flip(i);
    }

    int nokori = A - minA;
    int i = 2;
    while (nokori) {
        if (nokori >= B - 1) {
            flip(i);
            nokori -= B - 1;
            i++;
            continue;
        } else {
            flip(i, nokori + 1);
            break;
        }
    }

    if (swp) {
        for (int i = N; i >= 1; --i) {
            cout << arr[i];
            if (i != 1)cout << " ";
            else {
                cout << endl;
                return 0;
            }
        }
    } else {
        for (int i = 1; i <= N; ++i) {
            cout << arr[i];
            if (i != N)cout << " ";
            else {
                cout << endl;
                return 0;
            }
        }
    }

}

