    for (int i = N - A + 1; i >= 1; i -= A) {
        vector<int> tmp;
        for (int j = i; j < i + A; ++j) {
            tmp.emplace_back(j);
        }
        v.emplace_back(tmp);
    }
    if (N % A) {
        vector<int> tmp;
        for (int i = 1; i <= N % A; ++i) {
            tmp.emplace_back(i);
        }
        v.emplace_back(tmp);
    }
    vector<int> up;
    for (int i = (int)v.size() - 1; i > 0; --i) {
        for (int j = 0; j + 1 < v[i].size(); ++j) {
            up.emplace_back(v[i][j]);
        }
    }
    int idx = B - 1 - (int)v.size();
    int num = idx == -1 ? -1 : up[idx];
    vector<int> res;
    for (auto& a: v) {
        for (auto& e: a) {
            if (e > num) {
                res.emplace_back(e);
            }
        }
    }
    for (int i = num; i >= 1; --i) {
        res.emplace_back(i);
    }
    for (int i = 0; i < N; ++i) {
        cout << res[i] << " \n"[i == N - 1];
    }
}

