            REPS(j, b) ans.push_back(consumed + b - j);
            consumed += b;
        } else if (i == y) {
            REPS(j, x) ans.push_back(consumed + x - j);
            consumed += x;
        } else {
            ans.push_back(consumed ++);
        }
    }
    REP(i, ans.size()) cout << ans[i] << " \n"[i + 1 == ans.size()];
    return 0;
}

