	if (N < A + B - 1)
	{
		cout << -1 << endl;
		return 0;
	}

	if (A == 1 || B == 1)
	{
		if (A + B - 1 != N)
			cout << -1 << endl;
			return 0;
	}

	//! 増加部分
	for (size_t i = N - (A - 1); i <= N; i++)
	{
		cout << i;
		if (i != N)
		{
			cout << " ";
		}
		else if (B != 1)
		{
			cout << " ";
		}
	}

	//! 減少部
	for (size_t i = (B - 1); i >= 1; i--)
	{
		cout << i;
		if (i != 1)
		{
			cout << " ";
		}
		else if (A + B - 1 != N)
		{
			cout << " ";
		}
	}

	//! 増加部と減少部の長さが1になるように
	int max = N - A;
	int min = B;
	for (size_t i = 0; min <= max; i++)
	{
		if (i % 2 == 0)
		{
			cout << max;
			max--;
			if (max >= min)
			{
				cout << " ";
			}
			continue;
		}
		cout << min ;
		min++;
		if (max >= min)
		{
			cout << " ";
		}
	}
	cout << endl;
	return 0;
}

