vector<ll> out;

void solve() {
    memset(saw, 0, sizeof(saw));
    if (n < a || n < b) {
        cout << -1 << endl;
        return;
    }
    if (n/a+(n%a!=0) > b) {
        cout << -1 << endl;
        return;
