        ll add = 0;
        for ( ; i < min(cnt*a+a,n); i++) {
            ans[i] = n-(cnt+1)*a+(i-cnt*a)+1;
            if (f) {
                if (ans[i] <= 0) add = 1-ans[i];
            }
            ans[i] += add;
            f = false;
        }
        cnt++;
    }
    b -= n/a+(n%a!=0);
    rep(i,a) out.push_back(ans[i]);
    for (ll i = a; i < n; i += a) {
        for (ll j = i; j < min(i+a, n)-1; j++) {
            if (b != 0) {
                out.push_back(ans[min(i+a,n)-1-(j-i)]);
