using namespace std;

#define REP(i, n) for(int i = 0; i < (int)(n); ++i)
#define FOR(i, m, n) for(int i = (int)(m); i < (int)(n); ++i)

// 参考 URL
// http://kmjp.hatenablog.jp/entry/2018/03/11/1100

// 0 ~ N-1 であることに注意
template <typename T=long long>
vector<T> LISLDS(T N, T A, T B)
{
    vector<T> ret;
    for(long long i = B-1; i >= 0; --i) ret.push_back(i);

    if(A == 1) return ret;

    long long rem = N-B;
    long long p = rem/(A-1);  // 残りの A-1 個の部分列一つあたりに何個入れられるか
    long long r = rem%(A-1);  // 残りの A-1 個の部分列一つあたりに p 個入れた場合に何個余るか

    // 余りが出ないように A-1 この部分列を作る
    // 長さが p+1 の部分列を r 個作る <- 余りをなくす
    REP(i, r){
        int size = ret.size();
        for(int j = p; j >= 0; --j) ret.push_back(size+j);
    }
    // 長さが p の部分列を A-1-r 個作る
    REP(i, A-1-r){
        int size = ret.size();
        for(int j = p-1; j >= 0; --j) ret.push_back(size+j);
    }

    return ret;
}


