int main(){
	int n, a, b; cin >> n >> a >> b;
	if(a == 1){
		if(b == n){
			for(int i = n; i >= 1; i--) cout << i << " "; cout << endl;
		} else {
			cout << -1 << endl;
		}
	} else if(b == 1) {
		if(a == n){
			for(int i = 1; i <= n; i++) cout << i << " "; cout << endl;
		} else {
			cout << -1 << endl;
		}
	} else {
		if(a + b - 1 > n) cout << -1 << endl;
		else {
			vector<int> inc, dec;
			int fr = n;
			for(int i = 0; i < a; i++) inc.push_back(fr--);
			for(int i = 1; i < b; i++) dec.push_back(fr--);
			reverse(inc.begin(), inc.end());
			reverse(dec.begin(), dec.end());
			vector<int> ans, pl, pr;
			for(int i = 0; i < a - 1; i++){
				pl.push_back(inc[i]);
				int tk = min(i + 1, fr);
				vector<int> now;
				for(int j = 0; j < tk; j++) now.push_back(fr--);
				reverse(now.begin(), now.end());
				for(int v : now) pl.push_back(v);
			}
			pl.push_back(inc[a - 1]);
			for(int i = 0; i < b - 1; i++){
				pr.push_back(dec[i]);
				int tk = min(i + 1, fr);
				vector<int> now;
				for(int j = 0; j < tk; j++) now.push_back(fr--);
				reverse(now.begin(), now.end());
				for(int v : now) pr.push_back(v);
			}
			reverse(pr.begin(), pr.end());
			for(int v : pl) ans.push_back(v);
			for(int v : pr) ans.push_back(v);
			bool oka = true, okb = true;
			{
				vector<int> lis;
				for(int v : ans){
					int pt = lower_bound(lis.begin(), lis.end(), v) - lis.begin();
					if(pt == lis.size()) lis.push_back(v);
					else lis[pt] = v;
				}
				oka &= lis.size() == a;
			}
			{
				vector<int> lis;
				for(int v : ans){
					int pt = lower_bound(lis.begin(), lis.end(), -v) - lis.begin();
					if(pt == lis.size()) lis.push_back(-v);
					else lis[pt] = -v;
				}
				okb &= lis.size() == b;
			}
			if(ans.size() == n && oka && okb){
				for(int i = 0; i < n; i++) cout << ans[i] << " "; cout << endl;
			} else {
				cout << -1 << endl;
			}
		}
	}
	return 0;
}

