  cin >> N >> A >> B;
  if (N < A + B - 1 || A * B < N) no();
  vi32 cc;
  rep(j, A) cc.push_back((B - 1) * A + j);
  rep(j, A) {
    reps(i, B - 1) {
      if (cc.size() >= N) break;
      cc.push_back((B - i - 1) * A + j);
    }
