void rec(ll off = 0, ll blocks = 0) {
	if (!(off < n))
		return;
	ll w = max(min(b, (n - off) - (a - blocks - 1)), 1ll);
	rec(off + w, blocks + 1);
	for (ll i = 0; i < w; i++)
		res.emplace_front(off + i + 1);
}

