int main(void){
    int n, a, b; scanf("%d%d%d", &n, &a, &b);
    if(not (a + b <= n + 1 and n <= lli(a) * lli(b))){ puts("-1"); return 0;}
    std::stack<int> A; std::stack<int> Stk;
    for(int y = b - 1; y >= 0; --y) A.push(n - y);
    for(int z = a; z <= n - b; ++z) Stk.push(z);
    int x = a - 1;
    while(x >= 1){
        A.push(x--);
        int cnt = 0; std::stack<int> T;
        while((not Stk.empty()) and cnt < b - 1){
            T.push(Stk.top()); Stk.pop(); cnt++;
        }
        while(not T.empty()){ A.push(T.top()); T.pop();}
    }
    std::vector<int> P(n);
    REP(i, n) P[i] = A.top(), A.pop();
    VintOut(P);    
    return 0;
}

