	void Solve() {
		UL N, A, B; cin >> N >> A >> B;
		if (N < A + B - 1) { cout << -1 << endl; return; }
		if (N > A * B) { cout << -1 << endl; return; }
		vector<UL> ans;
		UL s = N;
		UL t = 0;
		while (B != t + s) {
			if (A + B - t <= s) {
				s -= A;
				rep(i, A) {
					ans.push_back(s + i + 1);
				}
			}
			else {
				UL l = s - (B - t - 1);
				s -= l;
				rep(i, l) {
					ans.push_back(s + i + 1);
				}
			}
			t++;
		}
		rep(i, s) ans.push_back(s - i);

		rep(i, ans.size()) { if (i) cout << " "; cout << ans[i]; }
		cout << endl;
	}


	Problem();
};
