	int curr = 1, rem = n, num = 1, A = a, B = b;

	while (rem > 0) {
		if (a + b > rem && a <= rem) {
			int m = num + rem - a;
			for (int i = 0 ; i < a ; ++i) {
				ans[curr++] = m++; 
			}
			for (int i = 1 ; i <= rem - a ; ++i) {
				ans[curr++] = num + rem - a - i;
			}
			break;
		}

		for (int i = 1 ; i <= b ; ++i) {
			ans[curr++] = num + b - i;
		}
		--a;
		num = num + b;
		rem -= b;
	}

	return ans;
}

