{
   int N, A, B; cin >> N >> A >> B;

   if (N < A+B-1 || A*B < N) {
      cout << -1 << endl;
      return 0;
   }

   if (B == 1) {
      if (N != A) {
         cout << -1 << endl;
         return 0;
      }
      FORE(i, 1, N) {
         cout << i << " ";
      }
      cout << endl;
      return 0;
   }

   int D = A*B - N;
   int p = D / (B-1), q = D % (B-1);
   V<int> ans;
   FORE(i, 1, p) {
      ans.PB(i);
   }
   RFORE(i, 1, B-q) {
      ans.PB(p+i);
   }
   FOR(i, 0, A-(p+1)) {
      RFORE(j, 1, B) {
         ans.PB(p+B-q + B*i+j);
      }
   }
   REP(i, SZ(ans)) {
      cout << ans[i] << " ";
   }
   cout << endl;

   return 0;
}

