void solve(long long N, long long A, long long B)
{
  lli n = N;
  if (A * B < N)
  {
    cout << -1 << endl;
    return;
  }
  bool rev = true;
  if (A < B)
  {
    rev = false;
    swap(A, B);
  }
  vector<int> ans(A);
  ans[0] = B;
  N -= (B + A - 1);
  for (int i = 1; i < A; i++)
    ans[i] = 1;
  for (int i = 1; i < A; i++)
  {
    if (N >= B - 1)
    {
      ans[i] += B - 1;
      N -= B - 1;
    }
    else
    {
      ans[i] += N;
      N = 0;
    }
  }
  vector<vector<int>> calc(A);
  int cnt = 1;
  rrep(i, A)
  {
    rep(j, ans[i])
    {
      calc[i].push_back(cnt++);
    }
  }
  vector<int> last;

  rep(i, A)
  {
    for (auto s : calc[i])
      last.push_back(s);
  }
  if (rev)
    reverse(last.begin(), last.end());
  assert(last.size() == n);
  rep(i, n) cout << last[i] << " ";
}

