//———————————————LIS　最長増加部分列—————————————————
ll lis(vector<ll> a) {
  int n=a.size();
  vector<ll> dp(n);
  rep(i,n) dp[i]=INF;
  rep(i,n) {
    int x=lb(dp,a[i]);
    dp[x] = a[i];
  }
  return lb(dp,INF);
}
