int main() {
    cin >> n >> a >> b;
    if (n > 1LL * a * b) {
        cout << "-1";
        return 0;
    }
    if (n < a + b - 1) {
        cout << "-1";
        return 0;
    }
    for (int i = 1; i <= n; i++) {
        c[i] = n + 1 - i;
    }
    int lst = 0;
    reverse(c + 1, c + a + 1);
    lst += a;
    for (int i = 2; i <= b; i++) {
        lst++;
        int sz = n - lst + 1;
        int block_sz = sz / (b - i + 1);
        reverse(c + lst, c + lst + block_sz);
        lst += block_sz - 1;
    }
    for (int i = 1; i <= n; i++) cout << c[i] << " ";
    return 0;
}

