            for (int i = 0; i < b; i++) {
                for (int j = 0; j < a; j++) {
                    if (!i || !j || ex) {
                        arr.push_back((b-i) + b*j);
                        ex -= i && j;
                    } else break;
                }
            }

            // adjust
            vector<ll> vals = arr;
            sort(vals.begin(), vals.end());
            map<ll,int> index;
