struct Tri {
    int f, s, t;
    Tri() {
        f = -1, s = -1, t = -1;
    }
    Tri(int f, int s, int t) : f(f), s(s), t(t) {}
    bool operator<(const Tri &r) const {
        return f != r.f ? f < r.f : s != r.s ? s < r.s : t < r.t;
        //return f != r.f ? f > r.f : s != r.s ? s > r.s : t > r.t; 大きい順
    }
    bool operator>(const Tri &r) const {
        return f != r.f ? f > r.f : s != r.s ? s > r.s : t > r.t;
        //return f != r.f ? f > r.f : s != r.s ? s > r.s : t > r.t; 小さい順
    }
    int operator[](int i) {
        assert(i < 3);
        switch (i) {
            case 0:
                return f;
                break;
            case 1:
                return s;
                break;
            default:
                return t;
                break;
        }
    }
};
