        vector<int> ans;
        int sum = 0;
        int mo = N % B;
        if(mo * (div - 1) + (B - mo) * div != N) {
            cout << -1 << endl;
            return 0;
        }

        for(int i=0; i<B; i++) {
            int bucket = div;
            if(i < mo) bucket--;
