            // printf("mo = %lld, div = %lld, bucket = %lld\n", mo, div, bucket);
            int base = N - sum - (bucket - 1);
            for(int k=0; k<bucket; k++) {
                ans.push_back(base + k);
            }
            sum += bucket;
        }

        for(int i=0; i<N; i++) {
            printf("%lld%c", ans[i], (i+1 == N ? '\n' : ' '));
        }
        assert(sum == N);
