const int MAXN = 3e5;
int ans[MAXN+5];
int n,a,b;


bool check(){
	if(a == 0 || b == 0 || a > n || b > n) return false;
	if(b == 1 && a != n) return false;
	if(b > 1){
		int cnt = (n-a)/(b-1) + (n-a) %(b-1);
		if(cnt > a) return false;
	}
	return true;
}

int main(){
	cin >> n >> a >> b;
	if(a + b <= n){
		if(a == 1 || b == 1){
			cout << "-1" << endl;
			return 0;
		}
		else if(a + b < n){
			if(check() == false){
				printf("-1\n");
				return 0;
			}
			int now = n;
			stack<int> S;
			for(int i = 1; i <= a; i++){
				S.push(now);
				now--;
			}
			while(!S.empty()){
				ans[++ans[0]] = S.top();
				S.pop();
			}
			int ned = 0;
			while(ned * (b-1) < n-a && ned < a){ned++;}
			for(int i = 1; i <= b-2; i++){
				while(now != 0 && ((int)S.size() < ned)){
					S.push(now);
					now--;
				}
				while(!S.empty()){
					ans[++ans[0]] = S.top();
					S.pop();
				}
			}
			while(now != 0 && (int)S.size() < a){
				S.push(now);
				now--;
			}
			while(!S.empty()){
				ans[++ans[0]] = S.top();
				S.pop();
			}
			if(now != 0)
				printf("-1\n");
			else
				for(int i = 1; i <= ans[0]; i++) printf("%d ", ans[i]);
			return 0;
		}
		int all = b - 1,x = n - 1;
		while(all--) cout << x-- << ' ';
		cout << n << ' ';
		all = a,x = 1;
		while(a--) cout << x++ << ' ';
		cout << endl;
	}
	else if(a + b == n + 1){
		for(int i = n;i >= n - b + 2;i--) cout << i << ' ';
		for(int i = 1;i <= a;i++) cout << i << ' ';
	}
	else cout << "-1" << endl;
}

