int main() {
  ios::sync_with_stdio(false);
  cin.tie(nullptr);
  int n, inc, dec;
  cin >> n >> inc >> dec;
  bool rev = inc < dec;
  if (rev) {
    debug puts("REV");
    swap(inc, dec);
  }
  if (inc < (n + 1) / 2 || n - inc + 1 < 1 || dec == 0) {
    puts("-1");
    return 0;
  }
  vi ans;
  int cntr = 1;
  for (int i = n - inc + 1; i <= n; i++) {
    debug printf("INC %d\n", i);
    ans.push_back(i);
    if (dec > 1) {
      if (dec - 1 >= n - inc + 1) {
        puts("-1");
        return 0;
      }
      for (int i = dec - 1; i >= 1; i--) {
        ans.push_back(i);
      }
      cntr = dec;
      dec = 1;
    } else {
      if (cntr < n - inc + 1) {
        ans.push_back(cntr++);
      }
    }
  }
  if (rev) {
    for (int &i : ans) {
      i = n - i + 1;
    }
  }
  for (int i = 0; i < SZ(ans); i++) {
    printf("%d%c", ans[i], i == SZ(ans) - 1 ? '\n' : ' ');
  }
  return 0;
}

