const ll MAX_N = 200005;
bool okay = false;
ll answer = 0;
ll n, a, b;
vl ans;

void solve(){
    bool rev = false;
    if (a > b) swap(a, b), rev = true;
    if (a + b - 1 > n) {prl(-1); return;}
    else if (a <= (n + 1) / 2 && (b > n - a + 1 || b < (n + a - 1) / a)){
        prl(-1); return;
    }

    if (a == 1){
        if (rev){
            rep(i, n - 1) prs(i + 1);
            prl(n);
        }else{
            revFor(i, n, 1) prs(i + 1);
            prl(1);
        }
        return;
    }

    ans = vl(n); ll idx = 0;
    while (idx * a < n){
        ll num = n - idx * a;
        rep(i, a){
            if (num - a >= 0)
                ans[num - i - 1] = a - i + idx * a;
            else if (num - i - 1 >= 0)
                ans[num - i - 1] = n - i;
        }
        idx++;
    }

    ll num = b;
    For(m, 1, b + 1){
        ll x = (n - m) % a; if (x == 0) x = a;
        ll k = b - m;
        if ((k - 1) * a + x + m == n) {num = m; break;}
    }

    sort(ans.begin(), ans.begin() + num);
    reverse(ans.begin(), ans.begin() + num);
    if (rev) reverse(all(ans));
    rep(i, n - 1) prs(ans[i]);
    prl(ans[n - 1]);
}

int main(void){
    in3(n, a, b);
    // assert(n <= 9);
    solve();
    return 0;
}

