V ret;
bool solve(int N,int U,int D) {
	ret = V(U,1);
	N -= U + D - 1;
	ret.front() = D;
	if (N < 0) {
		return false;
	}

	for (int i : range(U)) {
		int k = min(N, D - ret[i]);
		N -= k;
		ret[i] += k;
	}
	if (N > 0) {
		return false;
	}
	return true;
}
