using namespace std;
vector<int> solve(auto N, auto A, auto B) {
  if(N+1 < A+B) return {-1};
  if(2*A < N) return {-1};
  vector<int> res;
  for(auto i=N-A+1; i<=N; ++i) res.push_back(i);
  if(A+B==N+1) {
    for(auto i=0; i<B-1; ++i) res.push_back(N-B-i);
  } else if(B==1) {
    return {-1};
  } else {
    for(auto i=0; i<B-1; ++i) res.push_back(B-i-1);
    for(auto i=B; i<=N-A; ++i) res.push_back(i);
  }
  assert(res.size()==N);
  return res;
}
