vector<ll> make_seq(int N, int A, int B) {
    // 最大増加列と最大減少列の共有する元は高々1つまでなので、A+B-1 <= N
    if (A + B - 1 > N) {
        return {};
    }
    // 1,2,..,Nの順列を{極大増加部分列}{極大増加部分列}...{極大増加部分列}と分解すると、極大増加部分列の末尾を取ってきて並べると減少列。
    // よって、極大増加部分列の長さはA以下、極大増加部分列の個数はB以下なので、N <= AB
    if (A * B < N) {
        return {};
    }
    // これらの条件を満たす時は作れる
    struct NumInfo {
        int idx;
        ll number;
    };
    vector<ll> ans;
    vector<NumInfo> num_infos;
    for (int i = 0; i < B; i++) {
        ans.push_back(-(ll)i * 1000000);
        num_infos.push_back(NumInfo{(int)ans.size()-1, ans.back()});
        int cnt = 0;
        while (N - ans.size() > B - i - 1 && cnt < A - 1) {
            ans.push_back(ans.back() + 1);
            num_infos.push_back(NumInfo{(int)ans.size()-1, ans.back()});
            cnt++;
        }
    }
    sort(num_infos.begin(), num_infos.end(), [](NumInfo lhs, NumInfo rhs){ return lhs.number < rhs.number; });
    for (int i = 0; i < num_infos.size(); i++) {
        NumInfo info = num_infos[i];
        ans[info.idx] = i + 1;
    }
    return ans;
}

int main() {
    int N, A, B;
    cin >> N >> A >> B;
    vector<ll> ans = make_seq(N, A, B);
    if (ans.empty()) {
        cout << -1 << endl;
    } else {
        for (int i = 0; i < ans.size(); i++) {
            cout << ans[i];
            if (i < ans.size() - 1) {
                cout << " ";
            }
        }
        cout << endl;
    }
}

