	for(int i=N;i>N-A;i--){
		printf("%s%d",sp,i);
		sp=" ";
	}
	LL k=(N-A)/(B-1);
	LL r=(N-A)%(B-1);
	int m=N-A;
	for(int i=0;i<B-1;i++){
		int hi=m;
		int low;
		if(i<r){
			low=m-k;
		}
		else{
			low=m-k+1;
		}
		for(int i=low;i<=hi;i++){
			printf("%s%d",sp,i);
			sp=" ";
		}
		m=low-1;
	}
	assert(m==0);

