vi lis(const vi &v) {
	int n = v.size();
	vi prev(n, -1);
	vi dp(n + 1, INF);
	vi pos(n + 1, -1);
	REP(i, n) {
		int c = lower_bound(ALL(dp), v[i]) - dp.begin();//lower:strongly increasing
