ull rank[N_MAX];
ull parent[N_MAX];

void uf_init (ull n) {
	for (sll i = 0; i < n; i++) {
		rank[i] = 0;
		parent[i] = i;
	}
}
ull uf_find (ull x) {
	if (parent[x] == x) return x;
	return parent[x] = uf_find(parent[x]);
}
bool uf_same (ull a, ull b) {
	return (uf_find(a) == uf_find(b));
}
bool uf_union (ull a, ull b) {
	ull ap = uf_find(a);
	ull bp = uf_find(b);
	if (ap == bp) return false;

	if (rank[ap] > rank[bp]) {
		parent[bp] = ap;
	} else {
		parent[ap] = bp;
		if (rank[ap] == rank[bp]) rank[bp]++;
	}
	return true;
}

