int main(){
    int N, A, B;
    cin >> N >> A >> B;

    if(A + B - 1 > N || A * B < N){
        cout << -1 << endl;
        return 0;
    }

    if(A == 1){
        if(B == N){
            for(int i = N; i > 0; --i){
                cout << i;
                if(i != 1) cout << " ";
            }
            cout << endl;
        }
        else {
            cout << -1 << endl;
        }
        return 0;
    }

    int prev = 0;

    vector<int> ans;
    for(int i = 0; i < A; ++i){
        ans.push_back(i+1);
        if(i == 0){
            for(int j = A + B - 1; j > A; --j){
                ans.push_back(j);
            }
            prev = A + B - 1;
        }
        else if(i != A - 1 && prev < N){
            for(int j = min(N, prev + B - 1); j > prev; --j){
                ans.push_back(j);
            }
            prev += B - 1;
        }
    }
    for(int i = 0; i < N; ++i){
        cout << ans[i];
        if(i != N - 1) cout << " ";
    }
    cout << endl;
}

