			}
		}
		for(i = 1; i <= l; i++){
			printf("%lld ", N - k * A - l + i);
		}
		for(i = N - k * A - l; i > 0; i--){
			printf("%lld ", i);
		}
		printf("\n");
	}
	return 0;
}

