fun main(args: Array<String>) {
  val (n, a, b)= readLine()!!.split(" ").map(String::toInt)

  if (a + b > n + 1) {
    println(-1)
    return
  }

  if (a.toLong() * b.toLong() < n.toLong()) {
    println(-1)
    return
  }

  val ys = IntArray(a)
  ys[0] = b
  for (k in 0 until (n - b)) {
    ys[k % (a - 1) + 1]++
  }

  val xs = mutableListOf<Int>()
  var base = 0
  for (y in ys) {
    for (x in base + y downTo base + 1) {
      xs.add(x)
    }
    base += y
  }
  println(xs.joinToString(" "))
}

