fun main(args: Array<String>) {
  val (n, a, b)= readLine()!!.split(" ").map(String::toInt)
  if (a == 1) {
    if (b == n) {
      println((1..n).toList().joinToString(" "))
      return
    } else {
      println(-1)
      return
    }
  }
  if (b == 1) {
    if (a == n) {
      println((n downTo 1).toList().joinToString(" "))
      return
    } else {
      println(-1)
      return
    }
  }

  if (a + b > n + 1) {
    println(-1)
    return
  }

  if (a.toLong() * b.toLong() < n.toLong()) {
    println(-1)
    return
  }

  val xs = mutableListOf<Int>()
  val completeALoop = n / b
  for (i in 0 until completeALoop) {
    for (j in b downTo 1) {
      xs.add(i * b + j)
    }
  }
  val remaining = n % b
  for (x in n downTo (n - remaining + 1)) {
    xs.add(x)
  }
  println(xs.joinToString(" "))
}

