/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 *
 * @author palayutm
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        OutputWriter out = new OutputWriter(outputStream);
        TaskE solver = new TaskE();
        solver.solve(1, in, out);
        out.close();
    }

    static class TaskE {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.nextInt(), A = in.nextInt(), B = in.nextInt();
            if (n + 1 < A + B) {
                out.println(-1);
                return;
            }
            if ((n - 1) / B + 1 > A) {
                out.println(-1);
                return;
            }
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = n - i;
            }
            int sum = n - B;
            for (int i = 0, now = 0; i < B; i++) {
                int cnt = 1 + Math.min(A - 1, sum);
                ArrayUtil.reverse(a, now, now + cnt);
                now += cnt;
                sum -= (cnt - 1);
            }
            out.println(a);
        }

    }

    static class OutputWriter extends PrintWriter {
        public OutputWriter(OutputStream out) {
            super(out);
        }

        public OutputWriter(Writer out) {
            super(out);
        }

        public void close() {
            super.close();
        }

        public void print(int[] a) {
            for (int i = 0; i < a.length; i++) {
                if (i != 0) {
                    print(' ');
                }
                print(a[i]);
            }
        }

        public void println(int[] a) {
            print(a);
            println();
        }

    }

    static class ArrayUtil {
        public static void reverse(int[] a, int from, int to) {
            for (int left = from, right = to - 1; left < right; left++, right--) {
                int t = a[left];
                a[left] = a[right];
                a[right] = t;
            }
        }

    }

    static class InputReader {
        public BufferedReader reader;
        public StringTokenizer tokenizer;

        public InputReader(InputStream stream) {
            reader = new BufferedReader(new InputStreamReader(stream), 32768);
            tokenizer = null;
        }

        public String next() {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                try {
                    tokenizer = new StringTokenizer(reader.readLine());
                } catch (IOException e) {
                    throw new RuntimeException(e);
                }
            }
            return tokenizer.nextToken();
        }

        public int nextInt() {
            return Integer.parseInt(next());
        }

    }
}

import java.util.*;

public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int A = sc.nextInt();
		int B = sc.nextInt();
		int sq = (int)Math.sqrt((double)N);
		if((A+B>N+1) || (A<sq && B<sq)) System.out.println(-1);
		//(単調増加列)+(単調減少列)で表現できる
		else if(A+B==N+1){
			for(int i=B;i<=N;++i) System.out.print(i+" ");
			for(int i=B-1;i>=1;--i) System.out.print(i+" ");
			System.out.println();
		}else{
			//長さBの単調減少列のブロックを作れるだけ作る。その時最長増加部分列は
			//tempAで表されるので、Aとの差分を左端に単調増加列として追加する
			int tempA = (N/B)+(N%B!=0? 1:0);
			int hidari = 0;
			while(tempA+hidari!=A){
				hidari++;
				if(hidari>N){ //条件を満たす数列を作るのは無理くぼ
					System.out.println(-1);
					return;
				}
				if((N-hidari)%B==0) tempA--;
			}

			int nowN = N-hidari;
			for(int i=1;i<=hidari;++i){ System.out.print(i+" "); //左端の単調増加列
			for(int i=1;i<=nowN/B;i++){
				for(int j=i*B;j>(i-1)*B;j--){
					System.out.print((j+hidari)+" "); //単調減少列のブロック
				}
			}
			for(int j=nowN;j>B*(nowN/B);--j) System.out.print((j+hidari)+" "); //あまった奴
			System.out.println();
		}
		return;
	}
}

import java.util.Scanner;

public class Main {


    public static void main(String[] args) {
        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int a = scan.nextInt();
        int b = scan.nextInt();

        if(a + b  > n + 1 || a * b < n) {
            System.out.println(-1);
            return;
        }
        int c = 0;
        for (int i = 1; i <= a; i++) {
            int num =  Math.min(n - c - (a - i), b);
            for (int j = 0; j < num; j++) {
                System.out.print(c + num - j + " ");

            }
            c += num;
        }
        if ( c != n) {
            throw new RuntimeException();
        }
    }
}

