import java.io.*;
import java.util.*;

public class Main {

	private static Scanner sc;
	private static Printer pr;

	private static void solve() {
		int n = sc.nextInt();
		int a = sc.nextInt();
		int b = sc.nextInt();

		if (a > n || b > n) {
			pr.println(-1);
			return;
		}

		if (a + b == n + 1) {
			List<Integer> ans = new ArrayList<>(n);
			for (int i = n; i >= a + 1; i--) {
				ans.add(i);
			}
			for (int i = 1; i <= a; i++) {
				ans.add(i);
			}

			for (int i = 0, size = ans.size(); i < size; i++) {
				if (i > 0) {
					pr.print(' ');
				}
				pr.print(ans.get(i));
			}
			pr.println();
		} else if (a == 1 || b == 1) {
			pr.println(-1);
		} else if ((n + a - 1) / a == b) {
			List<List<Integer>> ans = new ArrayList<>();
			int cnt = 1;
			List<Integer> tmp = new ArrayList<>();
			while (cnt <= n) {
				tmp.add(cnt);
				if (cnt % a == 0) {
					ans.add(tmp);
					tmp = new ArrayList<>();
				}
				cnt++;
			}
			if (tmp.size() > 0) {
				ans.add(tmp);
			}

			boolean flag = false;
			for (int i = ans.size() - 1; i >= 0; i--) {
				for (int e : ans.get(i)) {
					if (!flag) {
						flag = true;
					} else {
						pr.print(' ');
					}
					pr.print(e);
				}
			}
			pr.println();
		} else if ((n + b - 1) / b == a) {
			List<List<Integer>> ans = new ArrayList<>();
			int cnt = 1;
			List<Integer> tmp = new ArrayList<>();
			while (cnt <= n) {
				tmp.add(cnt);
				if (cnt % b == 0) {
					ans.add(tmp);
					tmp = new ArrayList<>();
				}
				cnt++;
			}
			if (tmp.size() > 0) {
				ans.add(tmp);
			}

			boolean flag = false;
			for (int i = 0, size = ans.size(); i < size; i++) {
				for (int j = ans.get(i).size() - 1; j >= 0; j--) {
					if (!flag) {
						flag = true;
					} else {
						pr.print(' ');
					}
					pr.print(ans.get(i).get(j));
				}
			}
			pr.println();
		} else {
			pr.println(-1);
		}
//		pr.println(ans);
	}

	// ---------------------------------------------------
	public static void main(String[] args) {
		sc = new Scanner(System.in);
		pr = new Printer(System.out);

		solve();

		pr.close();
		sc.close();
	}

	@SuppressWarnings("unused")
	private static class Scanner {
		BufferedReader br;

		Scanner (InputStream in) {
			br = new BufferedReader(new InputStreamReader(in));
		}

		private boolean isPrintable(int ch) {
			return ch >= '!' && ch <= '~';
		}

		private boolean isCRLF(int ch) {
			return ch == '\n' || ch == '\r' || ch == -1;
		}

		private int nextPrintable() {
			try {
				int ch;
				while (!isPrintable(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}

				return ch;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		String next() {
			try {
				int ch = nextPrintable();
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (isPrintable(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		int nextInt() {
			try {
				// parseInt from Integer.parseInt()
				boolean negative = false;
				int res = 0;
				int limit = -Integer.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Integer.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				int multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		long nextLong() {
			try {
				// parseLong from Long.parseLong()
				boolean negative = false;
				long res = 0;
				long limit = -Long.MAX_VALUE;
				int radix = 10;

				int fc = nextPrintable();
				if (fc < '0') {
					if (fc == '-') {
						negative = true;
						limit = Long.MIN_VALUE;
					} else if (fc != '+') {
						throw new NumberFormatException();
					}
					fc = br.read();
				}
				long multmin = limit / radix;

				int ch = fc;
				do {
					int digit = ch - '0';
					if (digit < 0 || digit >= radix) {
						throw new NumberFormatException();
					}
					if (res < multmin) {
						throw new NumberFormatException();
					}
					res *= radix;
					if (res < limit + digit) {
						throw new NumberFormatException();
					}
					res -= digit;

				} while (isPrintable(ch = br.read()));

				return negative ? res : -res;
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		float nextFloat() {
			return Float.parseFloat(next());
		}

		double nextDouble() {
			return Double.parseDouble(next());
		}

		String nextLine() {
			try {
				int ch;
				while (isCRLF(ch = br.read())) {
					if (ch == -1) {
						throw new NoSuchElementException();
					}
				}
				StringBuilder sb = new StringBuilder();
				do {
					sb.appendCodePoint(ch);
				} while (!isCRLF(ch = br.read()));

				return sb.toString();
			} catch (IOException e) {
				throw new NoSuchElementException();
			}
		}

		void close() {
			try {
				br.close();
			} catch (IOException e) {
//				throw new NoSuchElementException();
			}
		}
	}

	private static class Printer extends PrintWriter {
		Printer(PrintStream out) {
			super(out);
		}
	}
}

