		int layer = 0;
		int left = n;
		while (left > 0) {
			int numUnvis = b - 1 - layer;
			if (left == numUnvis || vis[layer] == a) {
				layer++;
			}
			vis[layer]++;
			left--;
		}
		int leftNums = n;
		String ans = "";
		for (int i = 0; i < b; i++) {
			int numInLayer = vis[i];
			leftNums -= numInLayer;
			int start = leftNums + 1;
			for (int j = 0; j < numInLayer; j++) {
				ans += (start + j) + " ";
			}
		}
