import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.PrintWriter;
import java.util.StringJoiner;
import java.util.StringTokenizer;
import java.util.function.IntUnaryOperator;
import java.util.function.LongUnaryOperator;

class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int a = in.nextInt();
        int b = in.nextInt();
        if (a == 1 && b == 1) {
            out.println(n == 1 ? 1 : -1);
        } else if (a + b - 1 > n) {
            out.println(-1);
        } else if (a == 1) {
            if (b == n) {
                for (int i = n; i > 0; i--) {
                    out.println(i);
                }
            } else {
                out.println(-1);
            }
        } else if (b == 1) {
            if (a == n) {
                for (int i = 0; i < n; i++) {
                    out.println(i + 1);
                }
            } else {
                out.println(-1);
            }
        } else {
            b--;
            for (int i = 0; i < a; i++) {
                out.println(n - a + i + 1);
            }
            for (int i = 0; i < b; i++) {
                out.println(b - i);
            }
            int l = b + 1, r = n - a;
            boolean f = true;
            for (int i = 0; i < n - a - b; i++) {
                if (f) {
                    out.println(r);
                    r--;
                } else {
                    out.println(l);
                    l++;
                }
                f = !f;
            }
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class In {
    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 0x10000);
    private StringTokenizer tokenizer;

    String next() {
        try {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        } catch (IOException ignored) {
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    char[][] nextCharArray(int n, int m) {
        char[][] a = new char[n][m];
        for (int i = 0; i < n; i++) {
            a[i] = next().toCharArray();
        }
        return a;
    }

    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    int[] nextIntArray(int n, IntUnaryOperator op) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsInt(nextInt());
        }
        return a;
    }

    long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }
        return a;
    }

    long[] nextLongArray(int n, LongUnaryOperator op) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsLong(nextLong());
        }
        return a;
    }
}

class Out {
    private PrintWriter out = new PrintWriter(System.out);
    boolean autoFlush = false;

    void println(Object... a) {
        StringJoiner joiner = new StringJoiner(" ");
        for (Object obj : a) {
            joiner.add(String.valueOf(obj));
        }
        out.println(joiner);
        if (autoFlush) {
            out.flush();
        }
    }

    void println(int[] a) {
        StringJoiner joiner = new StringJoiner(" ");
        for (int i : a) {
            joiner.add(Integer.toString(i));
        }
        out.println(joiner);
        if (autoFlush) {
            out.flush();
        }
    }

    void println(long[] a) {
        StringJoiner joiner = new StringJoiner(" ");
        for (long i : a) {
            joiner.add(Long.toString(i));
        }
        out.println(joiner);
        if (autoFlush) {
            out.flush();
        }
    }

    void flush() {
        out.flush();
    }
}

import java.util.*;

public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int A = sc.nextInt();
		int B = sc.nextInt();
		int sq = (int)Math.sqrt((double)N);
		if((A+B>N+1) || (A<sq && B<sq)) System.out.println(-1);
		else if(A+B==N+1){
			for(int i=B;i<=N;++i) System.out.print(i+" ");
			for(int i=B-1;i>=1;--i) System.out.print(i+" ");
			System.out.println();
		}else{
			for(int i=1;i<=N/B;i++){
				for(int j=i*B;j>(i-1)*B;j--){
					System.out.print(j+" ");
				}
			}
			for(int j=N;j>B*(N/B);--j) System.out.print(j+" ");
			System.out.println();
		}
		return;
	}
}

import java.util.Arrays;

public class Main {


  private static void solve() {
    int n = ni();
    long a = ni();
    long b = ni();

    if ((long)a * b < n || a + b > n + 1) {
      System.out.println(-1);
      return;
    }

    long[][] arr = new long[n][3];
    int ptr = 0;
    for (int i = 0; i < b; i ++) {
      arr[ptr][0] = b - i;
      arr[ptr][1] = i;
      ptr ++;
    }

    for (int i = 0; i < a - 1; i ++) {
      arr[ptr][0] = b * (i + 2);
      arr[ptr][1] = (i + 1) * b;
      ptr ++;
    }

    long pos = b + 1;
    long val = b * 2 - 1;
    while (ptr < n) {
      for (int i = 0; ptr < n && i < b - 1; i ++) {
        arr[ptr][0] = val --;
        arr[ptr][1] = pos ++;
        ptr ++;
      }
      pos ++;
      val += 2 * b - 1;
    }
    Arrays.sort(arr, (o1, o2) -> Long.signum(o1[0] - o2[0]));
    for (int i = 0; i < n; i ++) {
      arr[i][2] = i + 1;
    }
    Arrays.sort(arr, (o1, o2) -> Long.signum(o1[1] - o2[1]));
