class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int a = in.nextInt();
        int b = in.nextInt();
        if (a == 1 && b == 1) {
            out.println(n == 1 ? 1 : -1);
        } else if (a + b - 1 > n) {
            out.println(-1);
        } else if (a == 1) {
            if (b == n) {
                for (int i = n; i > 0; i--) {
                    out.println(i);
                }
            } else {
                out.println(-1);
            }
        } else if (b == 1) {
            if (a == n) {
                for (int i = 0; i < n; i++) {
                    out.println(i + 1);
                }
            } else {
                out.println(-1);
            }
        } else {
            if (true) {
                throw new RuntimeException();
            }
            b--;
            for (int i = 0; i < a; i++) {
                out.println(n - a + i + 1);
            }
            for (int i = 0; i < b; i++) {
                out.println(b - i);
            }
            int l = b + 1, r = n - a;
            boolean f = true;
            for (int i = 0; i < n - a - b; i++) {
                if (f) {
                    out.println(r);
                    r--;
                } else {
                    out.println(l);
                    l++;
                }
                f = !f;
            }
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

class In {
    private BufferedReader reader = new BufferedReader(new InputStreamReader(System.in), 0x10000);
    private StringTokenizer tokenizer;

    String next() {
        try {
            while (tokenizer == null || !tokenizer.hasMoreTokens()) {
                tokenizer = new StringTokenizer(reader.readLine());
            }
        } catch (IOException ignored) {
        }
        return tokenizer.nextToken();
    }

    int nextInt() {
        return Integer.parseInt(next());
    }

    long nextLong() {
        return Long.parseLong(next());
    }

    char[][] nextCharArray(int n, int m) {
        char[][] a = new char[n][m];
        for (int i = 0; i < n; i++) {
            a[i] = next().toCharArray();
        }
        return a;
    }

    int[] nextIntArray(int n) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextInt();
        }
        return a;
    }

    int[] nextIntArray(int n, IntUnaryOperator op) {
        int[] a = new int[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsInt(nextInt());
        }
        return a;
    }

    long[] nextLongArray(int n) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = nextLong();
        }
        return a;
    }

    long[] nextLongArray(int n, LongUnaryOperator op) {
        long[] a = new long[n];
        for (int i = 0; i < n; i++) {
            a[i] = op.applyAsLong(nextLong());
        }
        return a;
    }
}

