import java.io.*;
import java.util.*;

public class Main {
  private static List<Integer> solve(int n, int a, int b) {
    List<Deque<Integer>> listDeque = new ArrayList<>();
    int k = n;
    for (int i = 0; i < b; i++) {
      Deque<Integer> deque = new ArrayDeque<>();
      deque.addLast(k);
      k--;
      listDeque.add(deque);
    }
    for (int i = 0; i < b; i++) {
      for (int j = 0; j < a-1; j++) {
        if (k == 0) {
          if (i == 0) {
            return Arrays.asList(-1);
          }
          break;
        }
        listDeque.get(i).addFirst(k);
        k--;
      }
    }
    if (k > 0) {
      return Arrays.asList(-1);
    }
    List<Integer> outputList = new ArrayList<>();
    for (Deque<Integer> deque : listDeque) {
      outputList.addAll(deque);
    }
    return outputList;
  }

  private static void execute(ContestReader reader, PrintWriter out) {
    int n = reader.nextInt();
    int a = reader.nextInt();
    int b = reader.nextInt();
    List<Integer> answers = solve(n, a, b);
    out.print(answers.get(0));
    for (int i = 1; i < answers.size(); i++) {
      out.print(" ");
      out.print(answers.get(i));
    }
    out.println();
  }

  public static void main(String[] args) {
    ContestReader reader = new ContestReader(System.in);
    PrintWriter out = new PrintWriter(System.out);
    execute(reader, out);
    out.flush();
  }
}

