    static class ELISDL {
        public void solve(int testNumber, InputReader in, OutputWriter out) {
            int n = in.readInt();
            int a = in.readInt();
            int b = in.readInt();

            if (n < a + b - 1 || n > (long) a * b) {
                out.printLine(-1);
                return;
            }

            long[] ans = new long[n];
            int idx = 0;
            int cnt = n - a - b + 1;
            long i;
            for (i = 0; i < a; i++) {
                for (int j = b; j > 0; j--) {
                    if (i != 0 && j != b && cnt-- <= 0) break;
                    ans[idx++] = i * b + j;
                }
            }
            for (; i < a; i++) ans[idx++] = i * b + 1;

            ArrayUtils.compress(ans);
            for (int j = 0; j < n; j++) ans[j]++;
            out.printLine(ans);
        }

    }

    static interface LongList extends LongReversableCollection {
        public abstract long get(int index);

        public abstract void set(int index, long value);

        public abstract void addAt(int index, long value);

        public abstract void removeAt(int index);

        default public void swap(int first, int second) {
            if (first == second) {
                return;
            }
            long temp = get(first);
            set(first, get(second));
            set(second, temp);
        }

        default public LongIterator longIterator() {
            return new LongIterator() {
                private int at;
                private boolean removed;

                public long value() {
                    if (removed) {
                        throw new IllegalStateException();
                    }
                    return get(at);
                }

                public boolean advance() {
                    at++;
                    removed = false;
                    return isValid();
                }

                public boolean isValid() {
                    return !removed && at < size();
                }

                public void remove() {
                    removeAt(at);
                    at--;
                    removed = true;
                }
            };
        }

        default public void add(long value) {
            addAt(size(), value);
        }

        default public LongList sort() {
            sort(LongComparator.DEFAULT);
            return this;
        }

        default public LongList sort(LongComparator comparator) {
            Sorter.sort(this, comparator);
            return this;
        }

        default LongList unique() {
            long last = Long.MIN_VALUE;
            LongList result = new LongArrayList();
            int size = size();
            for (int i = 0; i < size; i++) {
                long current = get(i);
                if (current != last) {
                    result.add(current);
                    last = current;
                }
            }
            return result;
        }

    }

