class Main {
    static In in = new In();
    static Out out = new Out();
    static long mod = 1000000007;
    static long inf = 0xfffffffffffffffL;

    void solve() {
        int n = in.nextInt();
        int a = in.nextInt();
        int b = in.nextInt();
        if (a == 1 && b == 1) {
            out.println(n == 1 ? 1 : -1);
        } else if (a + b - 1 > n) {
            out.println(-1);
        } else if (a == 1) {
            if (b == n) {
                for (int i = n; i > 0; i--) {
                    out.println(i);
                }
            } else {
                out.println(-1);
            }
        } else if (b == 1) {
            if (a == n) {
                for (int i = 0; i < n; i++) {
                    out.println(i + 1);
                }
            } else {
                out.println(-1);
            }
        } else if (n / a + n % a > b || n / b + n % b > a) {
            out.println(-1);
        } else {
            int c = n;
            while (c - a > b - 1) {
                c -= a;
                b--;
                for (int i = 1; i <= a; i++) {
                    out.println(c + i);
                }
            }
            for (int i = 0; i <= c - b; i++) {
                out.println(b + i);
            }
            b--;
            for (int i = b; i > 0; i--) {
                out.println(i);
            }
        }
    }

    public static void main(String[]$) {
        new Main().solve();
        out.flush();
    }
}

