	static String INPUT = "";

	static final long mod = (long) 1e9 + 7;
	static final int dx[] = { -1, 0, 1, 0 }, dy[] = { 0, -1, 0, 1 };
	static final int[] dx8 = { -1, -1, -1, 0, 0, 1, 1, 1 }, dy8 = { -1, 0, 1, -1, 1, -1, 0, 1 };
	static final int inf = Integer.MAX_VALUE / 3;
	static final long linf = Long.MAX_VALUE / 3;
	static final double dinf = Double.MAX_VALUE / 3;

	static void solve() {
		int n = ni();
		int a = ni(), b = ni();
		if(a + b - 1 > n || (long)a * b < n) {
			out.println(-1);
			return;
		}
		ArrayDeque<Long> qs[] = new ArrayDeque[b];
		for(int i=0;i<b;i++)qs[i] = new ArrayDeque<>();
		int j = 0;
		for(int i=0;i<b;i++) {
			qs[i].add((long)i*a+1);
		}
		int rem = n - b;
		for(int i=0;i<b;i++) {
			long now = qs[i].peekFirst();
			while(rem>0&&qs[i].size()<a) {
				qs[i].addLast(++now);
				rem --;
			}
