class Main{
    public static void main(String[] args){
        Scanner scan = new Scanner(System.in);
        int N = scan.nextInt();
        int A = scan.nextInt();
        int B = scan.nextInt();

        List<Integer> ansList = new ArrayList<>();
        int n=0,m=0,l=0;
        for(int i=1;i<=N;++i){
            if(N-i*B-(B+1) <=A-i){
                n=i;
                if(N-n*B == A-n){
                    m=A-n;
                    l=0;
                }else{
                    m=A-n-1;
                    l=N-m-n*B;
                }
                break;
            }
        }
        if(n<=0 || l>=B){
