import java.util.*;

public class Main{
	public static void main(String[] args){
		Scanner sc = new Scanner(System.in);
		int N = sc.nextInt();
		int A = sc.nextInt();
		int B = sc.nextInt();
		int sq = (int)Math.sqrt((double)N);
		if((A+B>N+1) || (A<sq && B<sq)) System.out.println(-1);
		//(単調増加列)+(単調減少列)で表現できる
		else if(A+B==N+1){
			for(int i=B;i<=N;++i) System.out.print(i+" ");
			for(int i=B-1;i>=1;--i) System.out.print(i+" ");
			System.out.println();
		}else{
			//長さBの単調減少列のブロックを作れるだけ作る。その時最長増加部分列は
			//tempAで表されるので、Aとの差分を左端に単調増加列として追加する
			int tempA = (N/B)+(N%B!=0? 1:0);
			int hidari = 0;
			while(tempA+hidari!=A){
				hidari++;
				if(hidari>N){ //条件を満たす数列を作るのは無理くぼ
					System.out.println(-1);
					return;
				}
				if((N-hidari)%B==0) tempA--;
			}

			int nowN = N-hidari;
			for(int i=1;i<=hidari;++i) System.out.print(i+" "); //左端の単調増加列
			for(int i=1;i<=nowN/B;i++){
				for(int j=i*B;j>(i-1)*B;j--){
					System.out.print((j+hidari)+" "); //単調減少列のブロック
				}
			}
			for(int j=nowN;j>B*(nowN/B);--j) System.out.print((j+hidari)+" "); //あまった奴
			System.out.println();
		}
		return;
	}
}

using System;
using System.Collections.Generic;

public class Program
{
    private int N, A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.NextInt();
        B = sc.NextInt();

        if (A + B - 1 > N)
        {
            Console.WriteLine(-1);
            return;
        }

        if ((long) A * B < N)
        {
            Console.WriteLine(-1);
            return;
        }

        List<int> l = new List<int>();
        l.Add(A);
        int i = A;

        // N-A個をB-1個に分ける
        if (B > 1)
        {
            int d = (N - A) / (B - 1);
            int m = (N - A) % (B - 1);
            for (int j = 0; j < B - 1; j++)
            {
                int tmp = d;
                if (j < m) tmp++;
                l.Add(tmp);
            }
        }

        var ans = new int[N];
        int t = N;
        int index = 0;
        foreach (int i1 in l)
        {
            for (int j = i1 - 1; j >= 0; j--)
            {
                ans[index] = t - j;
                index++;
            }

            t -= i1;
        }

        Console.WriteLine(String.Join(" ", ans));
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

class Scanner
{
    public Scanner()
    {
        _pos = 0;
        _line = new string[0];
    }

    const char Separator = ' ';
    private int _pos;
    private string[] _line;

    #region スペース区切りで取得

    public string Next()
    {
        if (_pos >= _line.Length)
        {
            _line = Console.ReadLine().Split(Separator);
            _pos = 0;
        }

        return _line[_pos++];
    }

    public int NextInt()
    {
        return int.Parse(Next());
    }

    public long NextLong()
    {
        return long.Parse(Next());
    }

    public double NextDouble()
    {
        return double.Parse(Next());
    }

    #endregion

    #region 型変換

    private int[] ToIntArray(string[] array)
    {
        var result = new int[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = int.Parse(array[i]);
        }

        return result;
    }

    private long[] ToLongArray(string[] array)
    {
        var result = new long[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = long.Parse(array[i]);
        }

        return result;
    }

    private double[] ToDoubleArray(string[] array)
    {
        var result = new double[array.Length];
        for (int i = 0; i < array.Length; i++)
        {
            result[i] = double.Parse(array[i]);
        }

        return result;
    }

    #endregion

    #region 配列取得

    public string[] Array()
    {
        if (_pos >= _line.Length)
            _line = Console.ReadLine().Split(Separator);

        _pos = _line.Length;
        return _line;
    }

    public int[] IntArray()
    {
        return ToIntArray(Array());
    }

    public long[] LongArray()
    {
        return ToLongArray(Array());
    }

    public double[] DoubleArray()
    {
        return ToDoubleArray(Array());
    }

    #endregion
}

