public sealed partial class Program
{
    int N, A, B;

    static int[] Failure = new[] { -1 };

    int[] TrySplit(int m, int k)
    {
        if (m < k) return null;

        var xs = new int[k + 1];
        var r = m % k;

        for (var i = 0; i < k; i++)
        {
            xs[i] = (m + k - 1) / k + (r == 0 || i < r ? 0 : -1);
        }

        return xs;
    }

    private int[] Solve()
    {
        if (A == N && B == 1)
        {
            return Enumerable.Range(1, N).ToArray();
        }
        if (A == 1 && B == N)
        {
            return Enumerable.Range(1, N).Reverse().ToArray();
        }

        if (A <= 1 || B <= 1) return Failure;
        if (N <= A || N <= B) return Failure;

        var chunkLengths = TrySplit(N - A, B - 1);
        if (chunkLengths == null) return Failure;
        chunkLengths[B - 1] = A;

        // Console.Error.WriteLine(chunkLengths.Intercalate(", "));
        if (chunkLengths.Sum() != N) throw new Exception("Bug.");

        if (!(chunkLengths.Length == B
        && chunkLengths.All(l => 1 <= l && l <= A)))
        {
            return Failure;
        }

        var chunks = B.MakeArray(i => new int[chunkLengths[i]]);
        var queue = new Queue<Tuple<int, int>>();
        for (var j = 0; j < B; j++)
        {
            queue.Enqueue(Tuple.Create(j, 0));
        }
        for (var i = 0; i < N; i++)
        {
            var pair = queue.Dequeue();
            var j = pair.Item1;
            var k = pair.Item2;

            chunks[j][k] = 1 + i;

            if (k + 1 < chunkLengths[j])
            {
                queue.Enqueue(Tuple.Create(j, k + 1));
            }
        }

        var result = new int[N];
        {
            var i = 0;
            foreach (var chunk in chunks.Reverse())
            {
                foreach (var x in chunk)
                {
                    result[i] = x;
                    i++;
                }
            }
        }
        return result;
    }

    public void EntryPoint()
    {
        // Check();

        var I = _scanner;
        N = I.N();
        A = I.N();
        B = I.N();

        WriteLine(Solve().Select(x => x.ToString()).Intercalate(" "));
    }

    void Check()
    {
        for (var m = 1; m < 20; m++)
        {
            for (var k = 1; k < m; k++)
            {
                var xs = TrySplit(m, k);
                if (xs == null) continue;

                if (xs.Sum() != m)
                {
                    Console.Error.WriteLine($"m={m} k={k} xs={ xs.Intercalate(", ")}");
                }
            }
        }
    }
}

using System;
using System.Linq;//リストの使用
using System.Collections.Generic;
using System.Text;//テキストの高速出力に必要
class Program
{
	static void Main()
	{
		string[] input = Console.ReadLine().Split(' ');
		long n = long.Parse(input[0]);
		long b = long.Parse(input[1]);
    long a = long.Parse(input[2]);
		bool answer = true;
    long[] answers = new long[n];
    long looked = 0;

    if(a > n) answer = false;
    else if(a+b-1 > n) answer = false;
    else if(a*b < n) answer = false;

    if(!answer) Console.WriteLine(-1);
    else if(b != 1)
    {
      for(long i = 0; i < a; i++)
      {
        answers[i] = a-i;
      }
      looked = a;

      long setc = (n-a)/(b-1);
      long restc = (n-a)%(b-1);
      long num = a;

      for(long i = 0; i < restc; i++)
      {
        num += setc+1;
        for(long j = 0; j < setc+1; j++)
        {
          answers[looked] = num-j;
          looked++;
        }
      }

      for(long i = 0; i < b-1-restc; i++)
      {
        num += setc;
        for(long j = 0; j < setc; j++)
        {
          answers[looked] = num-j;
          looked++;
        }
      }

      Console.WriteLine(string.Join(" ", answers));
    }else
    {
      for(long i = 0; i < n; i++) answers[i] = n-i;
      Console.WriteLine(string.Join(" ", answers));
    }
	}
}

