    {
        if (A == N && B == 1)
        {
            return Enumerable.Range(1, N).ToArray();
        }
        if (A == 1 && B == N)
        {
            return Enumerable.Range(1, N).Reverse().ToArray();
        }

        if (A <= 1 || B <= 1) return Failure;
        if (N <= A || N <= B) return Failure;

        var chunkLengths = new int[B];
        {
            chunkLengths[0] = A;

            var m = N - A; // >= 1
            var k = B - 1; // >= 1

            // m 個のものを k パーツに分ける
            var r = m / k;
            if (k >= 2 && m % k != 0)
            {
                for (var i = 1; i < B - 1; i++)
                {
                    chunkLengths[i] = m / k;
                }
                chunkLengths[B - 1] = m % k;
            }
            else
            {
                for (var i = 1; i < B; i++)
                {
                    chunkLengths[i] = m / k;
                }
            }
        }

        if (!(chunkLengths.Length == B
        && chunkLengths.Sum() == N
        && chunkLengths.All(l => l >= 1)))
        {
            return Failure;
        }

        var chunks = B.MakeArray(i => new int[chunkLengths[i]]);
        var queue = new Queue<Tuple<int, int>>();
        for (var j = 0; j < B; j++)
        {
            queue.Enqueue(Tuple.Create(j, 0));
        }
        for (var i = 0; i < N; i++)
        {
            var pair = queue.Dequeue();
            var j = pair.Item1;
            var k = pair.Item2;

            chunks[j][k] = 1 + i;

            if (k + 1 < chunkLengths[j])
            {
                queue.Enqueue(Tuple.Create(j, k + 1));
            }
        }

        var result = new int[N];
        {
            var i = 0;
            foreach (var chunk in chunks.Reverse())
            {
                foreach (var x in chunk)
                {
                    result[i] = x;
                    i++;
                }
            }
        }
        return result;
    }

    public void EntryPoint()
    {
        var I = _scanner;
        N = I.N();
        A = I.N();
        B = I.N();

        WriteLine(Solve().Select(x => x.ToString()).Intercalate(" "));
    }
}

using System;
