public class Program
{
    private int N, A, B;

    public void Solve()
    {
        var sc = new Scanner();
        N = sc.NextInt();
        A = sc.NextInt();
        B = sc.NextInt();

        if (A + B - 1 > N)
        {
            Console.WriteLine(-1);
            return;
        }

        if (A * B < N)
        {
            Console.WriteLine(-1);
            return;
        }

        List<int> l = new List<int>();
        l.Add(A);
        int i = A;

        while (i < N)
        {
            l.Add((N - A) / (B - 1));
            i += (N - A) / (B - 1);
        }

        if (N != i)
            l.Add(N - i);

        var ans = new int[N];
        int t = N;
        int index = 0;
        foreach (int i1 in l)
        {
            for (int j = i1 - 1; j >= 0; j--)
            {
                ans[index] = t - j;
                index++;
            }

            t -= i1;
        }

        Console.WriteLine(String.Join(" ", ans));
    }

    public static void Main(string[] args)
    {
        new Program().Solve();
    }
}

