                for (int i = 0; i < B; i++)
                {
                    ans[i] = new int[A];
                    for(int j = 0; j < A; j++)
                    {
                        ans[i][j] = (B - 1 - i) * A + 1 + j;
                    }
                }

                if (2 * (B - 1) > N)
                {
                    Console.WriteLine(-1);
                }
                else
                {
