class Solve{
    public Solve(){}
    StringBuilder sb;
    ReadData re;
    public static int Main(){
        new Solve().Run();
        return 0;
    }
    void Run(){
        sb = new StringBuilder();
        re = new ReadData();
        Calc();
        Console.Write(sb.ToString());
    }
    void Calc(){
        int N = re.i();
        long A = re.i();
        long B = re.i();
        if(A+B-1 > N || A*B < N){
            sb.Append("-1\n");
            return;
        }
        long[] ans = new long[N];
        long left = N-(A+B-1);
        int c = 0;
        for(int i=0;i<A;i++){
            ans[c] = B*i+A-1;
            c++;
        }
        for(int i=1;i<B;i++){
            ans[c] = A-1-i;
            c++;
            for(int j=1;j<A;j++){
                if(left == 0){
                    break;
                }
                ans[c] = B*j+A-1-i;
                left--;
                c++;
            }
        }
        int[] d = new int[N];
        for(int i=0;i<N;i++){
            d[i] = i;
        }
        Array.Sort(d,(x,y)=>(ans[x] > ans[y] ? 1 : (ans[x] == ans[y] ? 0 : -1)));
        for(int i=0;i<N;i++){
            sb.Append(d[i]+1);
            if(i == N-1){
                sb.Append("\n");
            }
            else{
                sb.Append(" ");
            }
        }
    }
}
