        private static int ReadInt() { return int.Parse(Read()); }
        private static long ReadLong() { return long.Parse(Read()); }
        private static double ReadDouble() { return double.Parse(Read()); }
        private static int[] ReadInts() { return Array.ConvertAll(Read().Split(), int.Parse); }
        private static long[] ReadLongs() { return Array.ConvertAll(Read().Split(), long.Parse); }
        private static double[] ReadDoubles() { return Array.ConvertAll(Read().Split(), double.Parse); }

        static private IEnumerable<int> LISDL(int N, int A, int B)
        {
            if (B == 1)
            {
                if (A == N) { return Enumerable.Range(1, N); }
            }
            else
            {
                if (A >= (N + B - 1) / B)
                {
                    var ranges = new List<IEnumerable<int>>();
                    int n = N - A;
                    for (int i = 0; i < B - 1; ++i)
                    {
                        int a = n * (i + 0) / (B - 1);
                        int b = n * (i + 1) / (B - 1);
                        ranges.Add(Enumerable.Range(a + 1, b - a));
                    }
                    ranges.Add(Enumerable.Range(N - A + 1, A));
                    var list = new List<int>();
                    for (int i = ranges.Count - 1; i >= 0; --i) { list.AddRange(ranges[i]); }
                    return list;
                }
            }
            return new int[] { -1 };
        }
        static private IEnumerable<int> Solve(int N, int A, int B)
        {
            return (A > B) ? LISDL(N, A, B) : LISDL(N, B, A).Reverse();
        }
        static void Main(string[] args)
        {
            int[] values = ReadInts();
            Console.WriteLine(string.Join(" ", Solve(values[0], values[1], values[2])));
        }
    }
}

