public class Solver
{
	public void Solve()
	{
		long N = GetLong();
		long A = GetLong();
		long B = GetLong();
		if(N < A + B - 1 || N > A * B)
		{
			WriteLine(-1);
			return;
		}

		var list = new List<long>();
		long free = N - (A + B - 1);
		for(long i = 1; i <= A; i++)
			list.Add(A * (B - 1) + i);

		for(long i = B - 2; i >= 0; i--)
		{
			list.Add(A * i + 1);
			if(free > 0)
			{
				for(long j = 2; j <= A; j++)
				{
					list.Add(A * i + j);
					free--;
					if(free == 0)
						break;
				}
			}
		}

		var tmp = new List<long>(list);
		tmp.Sort();
		var dict = tmp.Select((x, i) => (x, i)).ToDictionary(x => x.Item1, x => x.Item2);
		WriteLine(string.Join(" ", list.Select(x => dict[x] + 1)));
	}
}

