class Solver
{
    Scanner sc = new Scanner();
    //
    public void Solve()
    {
        int N, A, B;
        sc.Make(out N, out A, out B);
        var res = new int[N];
        if (A + B >= N + 2) Fail(-1);
        if ((long)A * B < N) Fail(-1);
        for (var i = B; i >= 1; i--)
            res[B-i] = i;
        for (var i = 0; i < A - 1; i++)
            res[B + i] = N - A + 2 + i;
        for (var i = 0; i < N - A - B + 1; i++)
            res[A + B - 1 + i] = B + 1 + i;

        Console.WriteLine(string.Join(" ", res));
    }
}

