using System.Threading.Tasks;

namespace ARC091E
{
    class Program
    {
        static void Main(string[] args)
        {
            var line1 = Console.ReadLine().Split().Select(int.Parse).ToArray();
            int N = line1[0];
            int A = line1[1];
            int B = line1[2];


            if (A + B > N + 1)
            {
                Console.WriteLine("-1");
            }
            else
            {
                List<int> ans = new List<int>();

                List<int> nums = new List<int>();
                for (int i = 0; i < N; i++) nums.Add(i + 1);
                while (true)
                {
                    if (nums.Count <= A - 1)
                    {
                        ans.AddRange(nums);
                        break;
                    }
                    ans.AddRange(nums.Take(A - 1));
                    nums = nums.Skip(A - 1).ToList();

                    if (nums.Count <= B - 1)
                    {
                        ans.AddRange(nums);
                        break;
                    }
                    ans.AddRange(nums.Skip(nums.Count - (B - 1)).Reverse());
                    nums = nums.Take(nums.Count - (B - 1)).ToList();
                }

                Console.WriteLine(string.Join(" ", ans));
            }
            Console.ReadKey();

        }
    }
}

