        //LDSは逆からのLIS
        if (nab[1] + nab[2] - 1 > nab[0] || nab[0] >= (nab[1] + nab[2] - 1) * 2)
        {
            Console.WriteLine(-1);
        }
        else
        {
            //核となる数字を決める。(全体のa:bくらいに基点を置きたい)
            int core = (int)Math.Ceiling(nab[2] * ((double)nab[0] / (nab[1] + nab[2])));

            //LIS生成
            int[] lis = new int[nab[1]];
            for (int i = 0; i < nab[1]; i++)
            {
                lis[i] = nab[0] - nab[1] + i + 1;
            }
            //LDS生成
            int[] lds = new int[nab[2]];
            for (int i = 0; i < nab[2]; i++)
            {
                lds[i] = nab[2] - i;
            }
            //ダミーLIS生成(コアの上の数個)
            int[] dlis = new int[lis[0] - core - 1];
            for (int i = 0; i < dlis.Length; i++)
            {
                dlis[i] = core + i + 1;
            }
            //ダミーLDS生成(コアの上の数個)
            int[] dlds = new int[core - lds[0] - 1];
            for (int i = 0; i < dlis.Length; i++)
            {
                dlis[i] = core - i - 1;
            }
            int[] res = new int[nab[0]];
            res[0] = core;
            int index = 1;
            lis.CopyTo(res, index);
            index += lis.Length;
            lds.CopyTo(res, index);
            index += lds.Length;
