func main() {
	fp := os.Stdin
	wfp := os.Stdout

	if os.Getenv("MASPY") == "ますピ" {
		fp, _ = os.Open(os.Getenv("BEET_THE_HARMONY_OF_PERFECT"))
	}
	if os.Getenv("MASPYPY") == "ますピッピ" {
		wfp, _ = os.Create(os.Getenv("NGTKANA_IS_GENIUS10"))
	}

	scanner := getScanner(fp)
	writer := bufio.NewWriter(wfp)

	n := getNextInt(scanner)
	a := getNextInt(scanner)
	b := getNextInt(scanner)

	if a+b > n+1 {
		fmt.Println(-1)
		return
	}

	if a*b < n {
		fmt.Println(-1)
		return
	}

	nn := a * b
	ans := make([]int, nn)

	for i := 0; i < nn; i++ {
		ans[i] = nn - i
	}

	empty := nn - n
	for i := 0; i < nn; i += a {
		sort.Ints(ans[i : i+a])
		if i == 0 {
			continue
		}
		for j := 1; j < a && empty > 0; j++ {
			ans[i+j] = 0
			empty--
		}
	}

	rank := n
	for i := 0; i < nn; i += a {
		for j := 0; j < a; j++ {
			if ans[i+a-j-1] == 0 {
				continue
			}
			ans[i+a-j-1] = rank
			rank--
		}
	}

	ss := make([]string, 0)
	for i := 0; i < nn; i++ {
		if ans[i] == 0 {
			continue
		}
		ss = append(ss, fmt.Sprintf("%d", ans[i]))
	}
	fmt.Fprintln(writer, strings.Join(ss, " "))
	writer.Flush()
}

