import "fmt"

func main() {
	var N, A, B int
	fmt.Scan(&N, &A, &B)
	if A+B-1 > N || A*B < N {
		fmt.Println(-1)
		return
	}
	for i := B; i > 0; i-- {
		fmt.Printf("%d ", i)
	}
	g := (N - B + A - 2) / (A - 1)
	r := B + 1
	for r <= N {
		rest := N - r + 1
		var l int
		if rest > g {
			l = r + g - 1
		} else {
			l = N
		}
		for i := l; i >= r; i-- {
			fmt.Printf("%d ", i)
		}
		r = l + 1
	}
}

