func main() {
	var N, A, B int
	fmt.Scanf("%d%d%d", &N, &A, &B)
	if A+B > N+1 {
		fmt.Println(-1)
		return
	}
	if false {
		min := 0
		NN := N
		root := 0
		for ; true; {
			root = int(math.Sqrt(float64(NN)))
			NN = NN - root*root
			if NN <= 2 {
				min += NN
				break
			}
			min += root
		}
		if A+B < min {
			fmt.Println(-1)
			return
		}
	} else {
		if A*B < N {
			fmt.Println(-1)
			return
		}
	}
	// Now divide N to A groups while the largest one is B
	// (A-1)*span + B = N
	span := (N - B) / (A - 1)
	left := (N - B) - span*(A-2)
	out := make([]int, N)
	iout := 0
	// span <= span <= B
	for i := 0; i < A-2; i++ {
		for ii := 0; ii < span; ii++ {
			out[iout] = i*span + span - ii
			iout++
		}
	}
	i := A - 2
	for ii := 0; ii < left; ii++ {
		out[iout] = i*span + left - ii
		iout++
	}
	for ii := 0; ii < B; ii++ {
		out[iout] = i*span + left + B - ii
		iout++
	}
	for i := 0; i < N-1; i++ {
		fmt.Print(out[i], " ")
	}
	fmt.Println(out[N-1])
}

