		for i := N - 1; i > 0; i-- {
			fmt.Print(i+1, " ")
		}
		fmt.Println(1)
		return
	}

	// Now divide N to A groups while the largest one is B
	// (A-1)*span + B = N
	span := (N - B) / (A - 1)
	left := (N - B) - span*(A-1)
	reversePrintSlice(1, B)
	for i := 0; i < A-1; i++ {
		if i < left {
			reversePrintSlice(B+1+(span+1)*i, span+1)
		} else {
			reversePrintSlice(B+1+span*i+left, span)
		}
	}
	fmt.Println()
	return

	out := make([]int, N)
	iout := 0
	// span <= span <= B
	for i := 0; i < A-2; i++ {
		for ii := 0; ii < span; ii++ {
			out[iout] = i*span + span - ii
			iout++
		}
	}
	i := A - 2
	for ii := 0; ii < left; ii++ {
		out[iout] = i*span + left - ii
		iout++
	}
	for ii := 0; ii < B; ii++ {
		out[iout] = i*span + left + B - ii
		iout++
	}
	for i := 0; i < N-1; i++ {
		fmt.Print(out[i], " ")
	}
	fmt.Println(out[N-1])
}

func reversePrintSlice(from, length int) {
	for i := from + length - 1; i >= from; i-- {
		fmt.Print(i, " ")
	}
}

