)

var reader = bufio.NewReaderSize(os.Stdin, 1000000)
var writer = bufio.NewWriter(os.Stdout)
func NextLine() string {
  var line, buffer []byte
  var isPrefix bool = true
  var err error
  for isPrefix {
    line, isPrefix, err = reader.ReadLine()
    if err != nil { panic(err) }
    buffer = append(buffer, line...)
  }
  return string(buffer)
}
func NextIntVec() []int {
  L := strings.Split(NextLine(), " ")
  N := make([]int, len(L))
  for i := range N {
    N[i], _ = strconv.Atoi(L[i])
  }
  return N
}
func Write(s interface{}) {
  fmt.Fprintln(writer, s)
}
func Output() {
  _ = writer.Flush()
}

func main() {
  NAB := NextIntVec()
  N := NAB[0]
  A := NAB[1]
  B := NAB[2]
  if N + 1 < A + B {
    Write(-1)
  } else if A * B < N {
    Write(-1)
  } else {
    P := make([]string, N)
    pos := A
    for i := 0; i < A; i++ {
      P[i] = strconv.Itoa(N - A + i + 1)
    }
    if B > 1 {
      k := (N - A) / (B - 1)
      m := (N - A) % (B - 1)
      upper := N - A
      for i := 0; i < B - 1; i++ {
        _k := k
        if m > 0 {
          _k++
          m--
        }
        for j := 0; j < _k; j++ {
          P[pos] = strconv.Itoa(upper + 1 - _k + j)
          pos += 1
        }
        upper -= _k
      }
    }
    Write(strings.Join(P, " "))
  }
  Output()
}

