void main() {
    int N, A, B;
    scanln(N, A, B);

    if (N < A+B-1) {
        writeln(-1);
        return;
    }
    if (N > A*B) {
        writeln(-1);
        return;
    }

    int[] xs = new int[A*B];
    foreach(i; 0..B) {
        foreach(j; 0..A) {
            xs[i*A+j] = (B-i-1)*A + j;
        }
    }

    auto g = new Generator!int({
        foreach(j; 0..A) {
            foreach(i; 1..B) {
                yield(i*A+j);
            }
        }
    });
    g.take(A*B - N).each!(i => xs[i]=-1);

    int[] ys = xs.filter!"a>=0".array;
