void main() {
    int N, A, B;
    scanln(N, A, B);

    if (N < A+B-1) {
        writeln(-1);
        return;
    }
    if (N > A*B) {
        writeln(-1);
        return;
    }

    int[] xs = new int[A*B];
    foreach(i; 0..B) {
        foreach(j; 0..A) {
            xs[i*A+j] = (B-i-1)*A + j;
        }
    }

    auto g = new Generator!int({
        foreach(j; 0..A) {
            xs[j].yield;
        }
        foreach(j; 0..A) {
            foreach(i; 1..B) {
                xs[i*A+j].yield;
            }
        }
    });
    int[] ys = g.take(N).array;
    int[] zs = new int[A*B];
    foreach(y; ys) {
        zs[y]++;
    }
    foreach(i; 1..A*B) {
        zs[i] += zs[i-1];
    }
    ys.map!(y => zs[y]).map!(to!string).join(" ").writeln;
}

