type seq2*[T] = seq[seq[T]]
proc newSeq2*[T](n1, n2: Natural): seq2[T] = newSeqWith(n1, newSeq[T](n2))

#------------------------------------------------------------------------------#
proc div_roundup(a, b: int): int = (a + (b - 1)) div b

proc reverse(a: var seq[int]; s, t: int) =
  let n = t - s
  for i in 0..<(n div 2):
    swap(a[s + i], a[t - 1 - i])

proc place(a: var seq[int]; b, s, t: int) =
  for i in s..<t:
    a[i] = b + (i - s)

proc solve(n, a, b: int): seq[int] = 
  if a == 1:
    var ans: seq[int] = @[]
    for i in countdown(n - 1, 0):
      ans.add(i)
    return ans

  if b == 1:
    var ans: seq[int] = @[]
    for i in 0..<n:
      ans.add(i)
    return ans

  let k = (n - b).div_roundup(a - 1)
  var ans = newSeq[int](b + k * (a - 1))
  ans.place(0, 0, b)
  ans.reverse(0, b)

  var i = b
  while i < ans.len():
    ans.place(i, i, i + k)
    ans.reverse(i, i + k)
    i += k

  return ans



