proc place(a: var seq[int]; b, s, t: int) =
  let n = t - s
  for i in 0..<n:
    a[s + i] = b + n - 1 - i

proc solve(n, a, b: int): seq[int] =
  if a == 1:
    var ans: seq[int] = @[]
    for i in countdown(n - 1, 0):
      ans.add(i)
    return ans

  if b == 1:
    var ans: seq[int] = @[]
    for i in 0..<n:
      ans.add(i)
    return ans

  var sec = newSeq[int](a)
  sec[0] = b

  let k = (n - b) div (a - 1)
  for i in 1..<a:
    sec[i] = k

  var rest = n - b - k * (a - 1)
  for i in 1..<n:
    if rest == 0:
      break
    sec[i] += 1
    rest -= 1

  var ans = newSeq[int](n)
  var j = 0
  for i in 0..<a:
    ans.place(j, j, j + sec[i])
    j += sec[i]

  return ans

