def solve(n, a, b):
    if n < a + b - 1:
        return [-1]
    if n > a * b:
        return [-1]
    ans = []
    t = 0
    for t in range(b, n + 1, b):
        ans.extend(range(t, t - b, -1))
    ans.extend(range(n, t, -1))
    return ans


