def f(a, b):
    return [
        p
        for p in [
            N - i * a + j
            for i in range(
                1,
                N // a + 1 if N % a > b - N // a else
                N // a
            )
            for j in range(1, a + 1)
        ] +
        [
            j
            for j in range(
                b - N // a if N % a > b - N // a else
                b - N // a + 1,
                N - (N // a) * a + 1 if N % a > b - N // a else
                N - (N // a - 1) * a + 1
            )
        ] +
        [
            j
            for j in reversed(
                range(
                    1,
                    b - N // a if N % a > b - N // a else
