    if A == B == 1:
        return -1
    n = 1
    m = N
    ans = []

    for _ in range(B):
        ans.append(m)
        m -= 1

    for _ in range(A):
        ans.append(n)
        n += 1

    if len(ans) > N:
        return -1

    rem = []
    while n <= m:
        rem.append(n)
        n += 1
        if n <= m:
            rem.append(m)
            m -= 1

    return ' '.join(map(str, rem + ans))


