def compress(xs):
    f = {}
    for i, x in enumerate(sorted(xs)):
        f[x] = i + 1
    return [ f[x] for x in xs ]

def solve(n, a, b):
    if a + b > n + 1:
        return [ -1 ]
    if a + b == n + 1:
        xs = [ 0 ]
        xs += list(map(lambda x:   10 ** 9 + x, range(a - 1)))
        xs += list(map(lambda x: - 10 ** 9 - x, range(b - 1)))
        return compress(xs)
    if a == 1 or b == 1:
        return [ -1 ]
    ys = []
    ys += list(map(lambda x:   10 ** 9 + x, range(a - 2)))
    ys += list(map(lambda x: - 10 ** 9 - x, range(b - 2)))
    i = 10 ** 6
    sign = +1
    xs = []
    while len(xs) + len(ys) < n:
        xs += [ sign * i ]
        i -= 1
        sign *= -1
    return compress(xs + ys)

