import numpy as np


def compress(array_like):
    tmp = sorted(array_like)

    m = {}
    for i, v in enumerate(tmp):
        m[v] = i + 1

    ret = []
    for a in array_like:
        ret.append(m[a])

    return ret


def main():
    N, A, B = map(int, input().split())
    # N, A, B = 300000, 1000, 1000
    # N, A, B = 10, 4, 5

    if A + B - 1 > N:
        return -1

    if A * B < N:
        return -1

    ans = np.arange(1, A * B + 1, dtype="int32").reshape(A, B).T[::-1, :]
    ans = list(ans)

    j = 0
    i = 0
    for _ in range(A * B - N):
        ans[j][i] = -1
        i += 1
        if i == A - j - 1:
            i += 1
        if i >= A:
            i = 0
            j += 1
        if i == A - j - 1:
            i += 1

    # print(ans)
    ans = np.array(ans).reshape(A * B)
    ans = ans[ans != -1]

    # return
    return ' '.join(map(str, compress(list(ans))))


if __name__ == '__main__':
    print(main())

