import sys
from bisect import bisect

def Longest_Increasing_Subsequence(N,lst):
    #配列の長さがN、配列がlstで与えられる最長増加部分列を返す
    #O(NlogN)

    MM=max(lst)+1
    data=[MM]*(N+1)
    #MMは配列の最大値とする
    #infだと計算量が結構大きくなるため

    data[0]=0
    for i in range(N):
        b=bisect(data,lst[i])
        data[b]=lst[i]

    ANS=1
    for i in range(1,N+1):
        if data[i]!=MM:
            ANS=i

    return ANS

def Longest_Decreasing_Subsequence(N,lst):
    #配列の長さがN、配列がlstで与えられる最長減少部分列を返す
    #O(NlogN)

    MM=max(lst)+1
    data=[MM]*(N+1)
    #MMは配列の最大値とする

    #配列を逆にして、最長増加部分列を求めればいよい
    lst=lst[::-1]

    data[0]=0
    for i in range(N):
        b=bisect(data,lst[i])
        data[b]=lst[i]

    ANS=1
    for i in range(1,N+1):
        if data[i]!=MM:
            ANS=i

    return ANS



