    rev = a < b
    if rev:
        b, a = a, b

    if n < a+b-1:
        return [-1]

    if n > a * b:
        return [-1]

    surrogate_ans = []
    for i in range(b):
        nd = i+1
        reminder = n - a*i
        tail = b - nd
        batch_length = min(a, reminder-tail)
        # print("i: {}, reminder: {}, tail: {}, batch_length: {}".format(i, reminder, tail, batch_length))
