fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (mut n, a, mut b): (usize, usize, usize) = io.read();

    let mut res: Vec<usize> = Vec::with_capacity(n);
    if !(a + b <= n + 1 && n <= a * b) {
        io.writeln(-1);
        return;
    }
    if a == 1 {
        res = (1..n + 1).rev().collect();
        io.writesln(&res, " ");
        return;
    }
    while n > b && n >= a && b > 0 {
        for i in n + 1 - a..n + 1 {
            res.push(i);
        }
        n -= a;
        b -= 1;
    }
    for i in 1..n + 1 {
        res.push(i);
    }

    io.writesln(&res, " ");
}

