fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (mut n, mut a, mut b): (usize, usize, usize) = io.read();

    let mut res: Vec<usize> = Vec::with_capacity(n);
    if !(a + b <= n + 1 && n <= a * b) {
        io.writeln(-1);
        return;
    }

    while n > 0 {
        if !(a + b <= n + 1) {
            a = n + 1 - b;
        }
        for i in n + 1 - a..n + 1 {
            res.push(i);
        }
        n -= a;
        b -= 1;
    }

    io.writesln(&res, " ");
}

