use std::cmp;

fn main() {
    input!(n: usize, a: usize, b: usize);
    if a + b > n + 1 {
        println!("-1");
        return;
    }
    let mut ans = vec![];
    for i in 0..((n + b - 1) / b) {
        for j in 0..b {
            let tmp = (i + 1) * b - j;
            if tmp > n {
                continue;
            }
            ans.push(tmp);
        }
    }
    ans.resize(n, 0);
    let mut cur_a = (n + b - 1) / b;
    if cur_a > a {
        println!("-1");
    }
    for i in (0..((n + b - 1) / b)).rev() {
        let end = cmp::min(n, cmp::min((i + 1) * b, i * b + a - cur_a + 1));
        ans[(i * b)..end].sort();
        cur_a += (end - (i * b)) - 1;
    }
    assert_eq!(a, cur_a);
    for i in 0..n {
        if i > 0 {
            print!(" ");
        }
        print!("{}", ans[i]);
    }
    println!();
}

