use std::cmp::min;
fn main() {
    input! { n, a, b };
    if a + b > n + 1 {
        println!("{}", -1);
        return;
    }
    let mut v = (1..b + 1).rev().chain(b + 1..n + 1).collect::<Vec<_>>();
    let mut x = n + 1 - b;
    let mut s = b;
    while a < x {
        let t = min(x - a + 1, min(b, n - s));
        (&mut v[s..s + t]).reverse();
        s += t;
        x -= t - 1;
        if s >= n {
            break;
        }
    }
    if x != a {
        println!("{}", -1);
    } else {
        for &x in &v {
            print!("{} ", x);
        }
        println!("");
    }
}

