use std::cmp;

fn main() {
    input!(n: usize, a: usize, b: usize);
    if a + b > n + 1 {
        println!("-1");
    } else if cmp::min(a + n / a, b + n / b) > a + b {
        println!("-1");
    } else {
        let (a, b, reversed) = if a > b { (a, b, false) } else { (b, a, true) };

        let mut ans = vec![];
        let one_box = b;
        let num_box = (n + b - 1) / b;

        let mut cur = n;
        for _ in 0..num_box {
            let mut b = vec![];
            for _ in 0..one_box {
                b.push(cur);
                cur -= 1;
                if cur == 0 {
                    break;
                }
            }
            ans.push(b);
        }
        ans.reverse();

        if a < num_box {
            unimplemented!();
        }
        let mut rest = a - num_box;
        assert!(n - one_box + 1 >= a);

        for i in 0..num_box {
            if ans[i].len() <= rest {
                ans[i].reverse();
                rest -= ans[i].len();
            } else {
                let mut next: Vec<usize> = vec![];
                for _ in 0..rest {
                    let t: usize = ans[i].pop().unwrap();
                    next.push(t);
                }
                for &t in ans[i].iter() {
                    next.push(t);
                }
                ans[i] = next;
                rest = 0;
            }

            if rest == 0 {
                break;
            }
        }

        let mut answer: Vec<usize> = vec![];
        for ans in ans.iter() {
            for &ans in ans.iter() {
                answer.push(ans);
            }
        }
        if reversed {
            answer.reverse();
        }

        for i in 0..n {
            if i > 0 {
                print!(" ");
            }
            print!("{}", answer[i]);
        }
        println!();
    }
}

