fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (mut n, a, mut b): (usize, usize, usize) = io.read();

    let mut res: Vec<usize> = Vec::with_capacity(n);
    if !(a + b <= n + 1 && n <= a * b) {
        io.writeln(-1);
        return;
    }
    while a + b <= n + 1 && n <= a * b && b > 0 {
        for i in n + 1 - a..n + 1 {
            res.push(i);
        }
        if b > 0 {
            n -= a;
            b -= 1;
        } else {
            break;
        }
    }
    for i in 1..n + 1 {
        res.push(i);
    }

    io.writesln(&res, " ");
}

