fn solve() {
    let (n, a, b) = get!(usize, usize, usize);

    if b > n {
        println!("-1");
        return;
    }

    let mut ls: BinaryHeap<usize> = (0..b).map(|_| 1).collect();
    let mut ans = Vec::new();

    for _ in 0..n - b {
        if let Some(x) = ls.pop() {
            if x + 1 >= a {
                ans.push(x + 1);
            } else {
                ls.push(x + 1);
            }
        } else {
            println!("-1");
            return;
        }
    }

    if ans.is_empty() {
        println!("-1");
        return;
    }

    ans.extend(ls.into_iter());

    if ans.is_empty() || ans[0] != a || ans.iter().sum::<usize>() != n {
        println!("-1");
        return;
    }

    let mut t = n;
    let mut v = Vec::new();
    // debug!(ans);
    for a in ans {
        v.extend((t - a)..t);
        t -= a;
    }

    println!(
        "{}",
        v.into_iter()
            .map(|x| (x + 1).to_string())
