fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();
    let a: usize = read();
    let b: usize = read();
    let maxb = n - a + 1;
    let minb = (n + a - 1) / a;
    if b < minb || maxb < b {
        println!("{}", -1);
        return;
    }
    let mut m = n;
    let mut restb = b;
    let mut seq = Vec::<usize>::new();
    for i in m-a..m {
        seq.push(i);
    }
    restb -= 1;
    m -= a;
    while m > 0 {
        assert!(restb != 0);
        let usable = std::cmp::min(a, m - (restb - 1));
        for i in m-usable..m {
            seq.push(i);
        }
        restb -= 1;
        m -= usable;
    }
    for i in 0..n {
        if i != 0 { print!(" "); }
        print!("{}", seq[i] + 1);
    }
    println!("");
}

