    if n % b != 0 {
        let mut part = vec![];
        for _ in 0..(n % b) {
            part.push(i + 1);
            i += 1;
        }
        part.reverse();
        ans.push(part);
    }
    while i < n {
        let mut part = vec![];
        for _ in 0..b {
            part.push(i + 1);
            i += 1;
        }
        part.reverse();
        ans.push(part);
    }

    let mut x = ans.len();
    for ans in ans.iter_mut() {
        if x == a {
            break;
        }
        if x + ans.len() <= a {
            ans.reverse();
            x += ans.len();
        } else {
            ans[0..(a - x)].reverse();
            x = a;
        }
    }
    for (i, ans) in ans.into_iter().enumerate() {
