    let b: usize = sc.read();
    if a + b - 1 > n {
        println!("-1");
        return;
    }

    let mut ans = vec![];
    let mut i = 0;
    while i < n {
        let mut part = vec![];
        for _ in 0..b {
            if i == n {
                break;
            }
            part.push(i + 1);
            i += 1;
        }
        part.reverse();
        ans.push(part);
    }

    let mut x = ans.len();
    if x > a {
        println!("-1");
        return;
    }
    for ans in ans.iter_mut() {
        if x == a {
            break;
        }
        if x + ans.len() <= a {
            ans.reverse();
            x += ans.len();
        } else {
            ans[0..(a - x)].reverse();
            x = a;
        }
    }
    for (i, j) in ans.into_iter().flatten().enumerate() {
        if i > 0 {
            print!(" ");
        }
        print!("{}", j);
    }
    println!();
