#[allow(unused_imports)]
use std::io::{stdout, stdin, BufWriter, Write};

fn main() {
    let out = std::io::stdout();
    let mut out = BufWriter::new(out.lock());
    macro_rules! puts {
        ($($format:tt)*) => (write!(out,$($format)*).unwrap());
    }

    input!{
      n: usize,
      mut a: usize,
      mut b: usize,
    }

    let mut rev = false;
    if a < b {
        rev = true;
        std::mem::swap(&mut a, &mut b);
    }

    if a > n || b > n {
        return puts!("{}\n", -1);
    }
    if !(a <= n-b+1 && a >= (n+b-1)/b) {
        return puts!("{}\n", -1);
    }
    let mut seq = vec![];
    for i in 0..n {
        seq.push(i+1);
    }
    if rev {
        seq.reverse();
    }

    let mut cur = 0;
    let mut ans = vec![];
    {
        let mut temp = vec![];
        for _ in 0..b {
            temp.push(seq[cur]);
            cur += 1;
        }
        temp.reverse();
        for v in temp {
            ans.push(v);
        }
    }

    let rem = n-b;
    let partition = a-1;
    if partition > 0 {
        let size = (rem + partition - 1) / partition;
        let t = partition - (size * partition - rem);

        for i in 0..partition {
            let mut temp = vec![];
            if i < t {
                for i in 0..size {
                    temp.push(seq[cur]);
                    cur += 1;
                }
            } else {
                for i in 0..size-1 {
                    temp.push(seq[cur]);
                    cur += 1;
                }
            }

            temp.reverse();
            for v in temp {
                ans.push(v);
            }
        }
    }

    for i in 0..ans.len() {
        if i == ans.len() - 1 {
            puts!("{}", ans[i]);
        } else {
            puts!("{} ", ans[i]);
        }
    }
    puts!("\n")
}

