fn solve(s: &str) {
    let mut it = s.split_whitespace();
    parse!(it, n: usize, a: usize, b: usize);
    if n > a * b || n < a + b - 1 || b > n {
        println!("{}", -1);
        return;
    }
    let mut ret: Vec<_>;
    if a == 1 {
        assert_eq!(b, n);
        ret = (1..=n).rev().collect();
    } else {
        let d = (n - b) / (a - 1);
        let mut e = (n - b) % (a - 1);
        ret = (1..=b).rev().collect();
        let mut l = b + 1;
        for _ in 1..a {
            let mut r = l + d;
            if e > 0 {
                r += 1;
                e -= 1;
            }
            ret.extend((l..r).rev());
            l = r;
        }
    }
    println!(
        "{}",
        ret.iter()
            .map(|x| x.to_string())
            .collect::<Vec<_>>()
            .join(" ")
    );
}

