fn solve() {
    let (n, a, b) = get!(usize, usize, usize);
    if n + 1 < a + b || n > a * b {
        println!("-1");
        return;
    }

    if a > b {
        let mut current = 0;
        for i in n - a..n {
            print!("{} ", i + 1);
            for j in (current..min!(current + b - 1, n - a)).rev() {
                print!("{} ", j + 1);
            }
            current = min!(current + b - 1, n - a);
        }
        println!("");
    } else {
        let mut current = b;
        for i in (0..b).rev() {
            print!("{} ", i + 1);
            for j in (current..min!(current + a - 1, n)).rev() {
                print!("{} ", n - j + b);
            }
            current = min!(current + a - 1, n);
        }
        println!("");
    }
}

