fn solve<R: std::io::Read, W: std::io::Write>(io: &mut IO<R, W>) {
    let (n, a, b): (usize, usize, usize) = io.read();
    let mut res: Vec<usize> = Vec::with_capacity(n);
    if !(a + b <= n + 1 && n <= a * b) {
        io.writeln(-1);
        return;
    }
    let mut n = n;
    let mut b = b;
    while a + b <= n + 1 && n >= a && b > 0 {
        for i in n + 1 - a..n + 1 {
            res.push(i);
        }
        n -= a;
        b -= 1;
    }
    for i in 1..n + 1 {
        res.push(i);
    }

    io.writesln(&res, " ");
}

