fn main() {
    let (n, a, b): (i64, i64, i64) = {
        let t = reads();
        (t[0], t[1], t[2])
    };

    let rep = (n + a - 1) / a;

    if rep > b || a + b - 1 >= n {
        println!("-1");
        return;
    }

    let mut ans: Vec<i64> = vec![];

    for i in 0..a {
        ans.push(i);
    }

    let mut base = -1;
    let mut rest = n - a;
    let mut rest_b = b - 1;
    while (rest + a - 1) / a < rest_b {
        rest -= 1;
        rest_b -= 1;
        ans.push(base);
        base -= 1;
    }

    while rest > 0 {
        let c = min(a, rest);
        for i in 0..c {
            ans.push(base - c + 1 + i);
        }
        base -= c;
        rest -= c;
    }

    assert_eq!(n as usize, ans.len());

    for i in 0..n {
        if i > 0 {
