use std::cmp::{max, min};

fn read_line() -> String {
    let mut s = String::new();
    std::io::stdin().read_line(&mut s).unwrap();
    s.trim().to_owned()
}

fn reads<T>() -> Vec<T>
where
    T: std::str::FromStr,
    <T as std::str::FromStr>::Err: std::fmt::Debug,
{
    read_line()
        .split_whitespace()
        .map(|w| w.parse().unwrap())
        .collect()
}

fn main() {
    let (n, a, b): (i64, i64, i64) = {
        let t = reads();
        (t[0], t[1], t[2])
    };

    let rep = (n + a - 1) / a;

    if rep > b || a + b - 1 > n {
        println!("-1");
        return;
    }

    let mut ans: Vec<i64> = vec![];

    for i in 0..a {
        ans.push(i);
    }

    let mut base = -1;
    let mut rest = n - a;
    let mut rest_b = b - 1;
    while (rest + a - 1) / a < rest_b {
        rest -= 1;
        rest_b -= 1;
        ans.push(base);
        base -= 1;
    }

    while rest > 0 {
        let c = min(a, rest);
        for i in 0..c {
            ans.push(base - c + 1 + i);
        }
        base -= c;
        rest -= c;
    }

    assert_eq!(n as usize, ans.len());

    for i in 0..n {
        if i > 0 {
            print!(" ");
        }
        print!("{}", ans[i as usize] - base);
    }
    println!();
}

use std::io::*;
use std::str::FromStr;

fn read<T: FromStr>() -> T {
    let stdin = stdin();
    let stdin = stdin.lock();
    let token: String = stdin
        .bytes()
        .map(|c| c.expect("failed to read char") as char)
        .skip_while(|c| c.is_whitespace())
        .take_while(|c| !c.is_whitespace())
        .collect();
    token.parse().ok().expect("failed to parse token")
}

fn main() {
    let n: usize = read();
    let a: usize = read();
    let b: usize = read();
    let maxb = n - a + 1;
    let minb = (n + a - 1) / a;
    if b < minb || maxb < b {
        println!("{}", -1);
        return;
    }
    let mut m = n;
    let mut restb = b;
    let mut seq = Vec::<usize>::new();
    while m > 0 {
        assert!(restb != 0);
        let usable = std::cmp::min(a, m - (restb - 1));
        for i in m-usable..m {
            seq.push(i);
        }
        restb -= 1;
        m -= usable;
    }
    for i in 0..n {
        if i != 0 { print!(" "); }
        print!("{}", seq[i] + 1);
    }
    println!("");
}

#[allow(unused_macros)]
macro_rules! input {
    (source = $s:expr, $($r:tt)*) => {
        let mut iter = $s.split_whitespace();
        let mut next = || { iter.next().unwrap() };
        input_inner!{next, $($r)*}
    };
    ($($r:tt)*) => {
        let stdin = std::io::stdin();
        let mut bytes = std::io::Read::bytes(std::io::BufReader::new(stdin.lock()));
        let mut next = move || -> String{
            bytes
                .by_ref()
                .map(|r|r.unwrap() as char)
                .skip_while(|c|c.is_whitespace())
                .take_while(|c|!c.is_whitespace())
                .collect()
        };
        input_inner!{next, $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! input_inner {
    ($next:expr) => {};
    ($next:expr, ) => {};

    ($next:expr, $var:ident : $t:tt $($r:tt)*) => {
        let $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };

    ($next:expr, mut $var:ident : $t:tt $($r:tt)*) => {
        let mut $var = read_value!($next, $t);
        input_inner!{$next $($r)*}
    };
}

#[allow(unused_macros)]
macro_rules! read_value {
    ($next:expr, ( $($t:tt),* )) => {
        ( $(read_value!($next, $t)),* )
    };

    ($next:expr, [ $t:tt ; $len:expr ]) => {
        (0..$len).map(|_| read_value!($next, $t)).collect::<Vec<_>>()
    };

    ($next:expr, chars) => {
        read_value!($next, String).chars().collect::<Vec<char>>()
    };

    ($next:expr, usize1) => {
        read_value!($next, usize) - 1
    };

    ($next:expr, $t:ty) => {
        $next().parse::<$t>().expect("Parse error")
    };
}

