#[derive(Eq, PartialEq, Clone, Debug)]
/// Equivalent to std::cmp::Reverse
pub struct Rev<T>(pub T);
impl<T: PartialOrd> PartialOrd for Rev<T> {
    fn partial_cmp(&self, other: &Rev<T>) -> Option<Ordering> {
        other.0.partial_cmp(&self.0)
    }
}
impl<T: Ord> Ord for Rev<T> {
    fn cmp(&self, other: &Rev<T>) -> Ordering {
        other.0.cmp(&self.0)
    }
}

fn solve1(n: usize, a: usize, b: usize) -> Option<Vec<usize>> {
    if b + a - 1 > n {
        return None;
    }

    let mut res = vec![1; b];
    res[0] = a;

    let mut rest = n + 1 - b - a;
    for x in &mut res[1..] {
        if rest != 0 {
            *x += min(rest, a - 1);
            rest -= min(rest, a - 1);
        }
    }

    if rest != 0 {
        return None;
    }

    Some(res)
}

fn solve() {
    let (n, a, b) = get!(usize, usize, usize);

    if let Some(ans) = solve1(n, a, b) {
        let mut rest = n;
        let mut v = Vec::new();
        for a in ans {
            v.extend((rest - a)..rest);
            rest -= a;
        }
        println!(
            "{}",
            v.into_iter()
                .map(|x| (x + 1).to_string())
                .collect::<Vec<_>>()
                .join(" ")
        );
        return;
    }

    if let Some(ans) = solve1(n, b, a) {
        let mut rest = n;
        let mut v = Vec::new();
        for a in ans {
            v.extend((rest - a)..rest);
            rest -= a;
        }
        println!(
            "{}",
            v.into_iter()
                .rev()
                .map(|x| (x + 1).to_string())
                .collect::<Vec<_>>()
                .join(" ")
        );
        return;
    }

    println!("-1");
    return;
}

use std::io::stdin;
use std::cmp::min;

fn read_line() -> Vec<String> {
    let mut line = String::new();
    stdin().read_line(&mut line).expect("Failed to read line");
    return line.trim().split_whitespace().map(|s| s.to_string()).collect();
}

struct Reader {
    v: Vec<String>,
    n: usize,
}

impl Reader {
    fn new() -> Reader {
        let v = read_line();
        return Reader { v: v, n: 0 };
    }
    fn next<T>(&mut self) -> T where T: std::str::FromStr, T::Err: std::fmt::Debug {
        if self.n == self.v.len() {
            self.v = read_line();
            self.n = 0;
        }
        let x = self.v[self.n].parse().expect(&self.v[self.n]);
        self.n += 1;
        return x;
    }
    fn nexts<T>(&mut self, n: usize) -> Vec<T>
    where T: std::str::FromStr, T::Err: std::fmt::Debug {
        let mut v = Vec::with_capacity(n);
        for _ in 0..n {
            v.push(self.next());
        }
        return v;
    }
}

fn main() {
    let mut r = Reader::new();
    let n: usize = r.next();
    let a: usize = r.next();
    let b: usize = r.next();

    if a + b > n + 1 || (a as u64) * (b  as u64) < (n as u64) {
        println!("-1");
        return;
    }

    let mut ans: Vec<usize> = Vec::new();

    for i in 0..a {
        for j in ((i * b + 1)..(1 + min(i * b + b, n))).rev() {
            ans.push(j);
        }
    }
    println!("{}", ans.iter().fold(String::new(), |mut x, y| {
        x.push_str(" ");
        x.push_str(&y.to_string());
        x
    }).trim());
}
